:root {
  --ink: #05030d;
  --ink-2: #0a0718;
  --panel: rgba(9, 6, 22, 0.88);
  --cyan: #5df7ff;
  --cyan-soft: #9bfbff;
  --magenta: #ff3fce;
  --violet: #8a5cff;
  --amber: #ffc36b;
  --red: #ff3e62;
  --white: #eefcff;
  --muted: #887fa8;
  --line: rgba(93, 247, 255, 0.28);
  --display: "Arial Black", "DejaVu Sans", "Helvetica Neue", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "DejaVu Sans Mono", monospace;
  --ui: "Trebuchet MS", "DejaVu Sans", "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: #020106;
  color: var(--white);
  font-family: var(--ui);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button { font-family: inherit; }
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }

#app { position: fixed; inset: 0; overflow: hidden; background: #020106; }

#stage {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    radial-gradient(ellipse at 50% 50%, #0b0820 0%, #020106 70%);
}

#game-wrap {
  position: relative;
  width: min(100vw, calc(100vh * 16 / 9));
  height: min(100vh, calc(100vw * 9 / 16));
  overflow: hidden;
  background: #05030d;
  box-shadow: 0 0 120px rgba(70, 40, 180, 0.22);
}

#game { display: block; width: 100%; height: 100%; touch-action: none; }

#grain, #vignette, #damage-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
#grain {
  opacity: 0.13;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grainShift 0.6s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(0, 0); }
}
#vignette {
  background:
    radial-gradient(ellipse at center, transparent 52%, rgba(2, 1, 8, 0.5) 84%, rgba(2, 1, 8, 0.92) 100%),
    linear-gradient(180deg, rgba(2, 1, 8, 0.22), transparent 14%, transparent 88%, rgba(2, 1, 8, 0.34));
}
#damage-flash {
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 30%, rgba(255, 32, 82, 0.38) 78%, rgba(255, 30, 80, 0.62) 100%);
  transition: opacity 0.15s ease-out;
}
#damage-flash.on { opacity: 1; transition: none; }

/* ------------------------------------------------------------------ HUD */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  font-family: var(--mono);
  opacity: 1;
  transition: opacity 0.4s ease;
}
#hud.hidden { opacity: 0; }
.hud-left {
  position: absolute;
  left: 2.3%;
  top: 4.2%;
  width: min(31%, 390px);
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.7));
}
.hud-name {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(9px, 0.9vw, 14px);
  letter-spacing: 0.22em;
  color: #dffdff;
  margin-bottom: 7px;
}
.hud-name .mark {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid rgba(93, 247, 255, 0.6);
  color: var(--cyan);
  font-size: 12px;
  transform: rotate(45deg);
  background: rgba(9, 24, 34, 0.8);
  box-shadow: 0 0 12px rgba(93, 247, 255, 0.25), inset 0 0 8px rgba(93, 247, 255, 0.18);
}
.hud-name .mark { text-shadow: 0 0 6px var(--cyan); }
.bar-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}
.bar-label {
  width: 20px;
  font-size: clamp(7px, 0.65vw, 10px);
  color: #7b96a8;
  letter-spacing: 0.12em;
}
.bar {
  position: relative;
  flex: 1;
  height: clamp(7px, 0.8vw, 11px);
  background: rgba(4, 8, 15, 0.82);
  border: 1px solid rgba(147, 241, 255, 0.26);
  transform: skewX(-22deg);
  overflow: hidden;
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.9);
}
.bar .fill {
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transition: width 0.18s cubic-bezier(0.2, 0.9, 0.3, 1), background 0.2s;
}
.bar.health .fill {
  background: linear-gradient(90deg, #00b7a6, #57ffcf 55%, #bbfff2);
  box-shadow: 0 0 14px rgba(70, 255, 214, 0.55);
}
.bar.health.low .fill {
  background: linear-gradient(90deg, #b81236, #ff3e62 60%, #ff9ab0);
  box-shadow: 0 0 14px rgba(255, 62, 98, 0.6);
  animation: lowPulse 0.7s ease-in-out infinite alternate;
}
@keyframes lowPulse { to { opacity: 0.6; } }
.bar.energy .fill {
  background: linear-gradient(90deg, #4b2aff, #8a5cff 45%, #5df7ff);
  box-shadow: 0 0 14px rgba(115, 92, 255, 0.6);
}
.bar-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 19%, rgba(3, 5, 10, 0.72) 19% 20%);
}
.bar-value {
  width: 27px;
  text-align: right;
  font-size: clamp(8px, 0.7vw, 11px);
  color: #b8e9ff;
  font-weight: 700;
}
.dash-pips { display: flex; gap: 5px; margin: 7px 0 0 26px; }
.dash-pips i {
  width: 24px;
  height: 3px;
  background: rgba(93, 247, 255, 0.15);
  transform: skewX(-30deg);
  border-left: 2px solid rgba(93, 247, 255, 0.15);
}
.dash-pips i.on {
  background: var(--cyan);
  border-color: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}
.dash-pips i.cool { background: rgba(138, 92, 255, 0.4); }

.hud-right {
  position: absolute;
  right: 2.3%;
  top: 4.2%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
.hud-caption {
  font-size: clamp(7px, 0.62vw, 10px);
  letter-spacing: 0.35em;
  color: #7c8da8;
}
.score {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(20px, 2.5vw, 38px);
  letter-spacing: 0.1em;
  color: #f3feff;
  line-height: 1;
  text-shadow: 0 0 22px rgba(93, 247, 255, 0.45), 0 2px 0 rgba(0, 0, 0, 0.5);
}
.orb-block {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: clamp(10px, 0.9vw, 14px);
  color: var(--cyan-soft);
  letter-spacing: 0.1em;
  background: rgba(5, 15, 24, 0.5);
  border: 1px solid rgba(93, 247, 255, 0.2);
  padding: 3px 8px;
  transform: skewX(-10deg);
}
.orb-icon {
  width: 9px;
  height: 9px;
  transform: rotate(45deg);
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
  border-radius: 50%;
}
.combo {
  position: fixed;
  left: 50%;
  top: 17%;
  transform: translateX(-50%) rotate(-3deg);
  display: flex;
  align-items: baseline;
  gap: 6px;
  text-shadow: 0 0 18px rgba(255, 63, 206, 0.7);
  transition: opacity 0.2s;
}
.combo span {
  font-family: var(--display);
  font-weight: 900;
  font-style: italic;
  font-size: clamp(26px, 3vw, 48px);
  color: #fff;
  -webkit-text-stroke: 1px rgba(255, 63, 206, 0.8);
}
.combo em {
  font-style: normal;
  font-size: clamp(8px, 0.8vw, 12px);
  letter-spacing: 0.3em;
  color: var(--magenta);
}
.combo.hidden { opacity: 0; }

.boss-hud {
  position: absolute;
  left: 50%;
  top: 3.2%;
  transform: translateX(-50%);
  width: min(62%, 780px);
  transition: opacity 0.4s, transform 0.4s;
}
.boss-hud.hidden { opacity: 0; transform: translate(-50%, -16px); }
.boss-meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 5px;
  font-size: clamp(7px, 0.7vw, 10px);
  letter-spacing: 0.18em;
}
.boss-tag { color: #ff8aa6; }
#boss-name {
  font-family: var(--display);
  font-size: clamp(11px, 1.2vw, 17px);
  letter-spacing: 0.28em;
  color: #fff;
  text-shadow: 0 0 14px rgba(255, 62, 98, 0.7);
}
.boss-phase { color: var(--amber); }
.boss-bar {
  height: clamp(8px, 0.8vw, 12px);
  border: 1px solid rgba(255, 113, 145, 0.5);
  background: rgba(14, 2, 8, 0.85);
  transform: skewX(-18deg);
  padding: 2px;
  box-shadow: 0 0 22px rgba(255, 20, 70, 0.18), inset 0 0 12px rgba(0, 0, 0, 0.9);
}
#boss-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #7a0b2d, #ff3e62 55%, #ffab6b);
  box-shadow: 0 0 16px rgba(255, 62, 98, 0.65);
  transition: width 0.2s ease-out;
}
.boss-bar-marks {
  position: absolute;
  inset: 2px;
  background: repeating-linear-gradient(90deg, transparent 0 24.6%, rgba(0, 0, 0, 0.5) 24.6% 25%);
}

.toast {
  position: absolute;
  left: 50%;
  top: 17%;
  transform: translate(-50%, -8px);
  padding: 8px 22px;
  border: 1px solid rgba(93, 247, 255, 0.34);
  background: linear-gradient(90deg, transparent, rgba(8, 24, 35, 0.92) 12%, rgba(8, 24, 35, 0.92) 88%, transparent);
  color: var(--cyan-soft);
  font-size: clamp(9px, 0.85vw, 13px);
  letter-spacing: 0.22em;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.3s, transform 0.3s;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.hint {
  position: absolute;
  left: 50%;
  bottom: 7%;
  transform: translateX(-50%);
  padding: 7px 16px;
  color: #c7e7f5;
  background: rgba(4, 9, 16, 0.6);
  border-left: 2px solid var(--cyan);
  font-size: clamp(8px, 0.72vw, 11px);
  letter-spacing: 0.16em;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.5s;
  text-shadow: 0 1px 3px #000;
}
.hint.show { opacity: 1; }
.hint b { color: var(--cyan); font-weight: 700; }

.sector-card {
  position: absolute;
  left: 50%;
  top: 38%;
  transform: translate(-50%, 8px);
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.55s, transform 0.55s;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.9);
}
.sector-card.show { opacity: 1; transform: translate(-50%, 0); }
.sector-kicker { font-size: clamp(7px, 0.65vw, 10px); letter-spacing: 0.6em; color: var(--magenta); }
#sector-title {
  font-family: var(--display);
  font-size: clamp(20px, 3.1vw, 48px);
  font-weight: 900;
  letter-spacing: 0.16em;
  color: #f4feff;
  margin: 4px 0;
}
.sector-sub { font-size: clamp(8px, 0.7vw, 11px); letter-spacing: 0.4em; color: #93b9c8; }

.hud-buttons {
  position: absolute;
  right: 2.3%;
  bottom: 4%;
  display: flex;
  gap: 6px;
  pointer-events: auto;
}
.icon-btn {
  width: clamp(26px, 2.3vw, 36px);
  height: clamp(26px, 2.3vw, 36px);
  border: 1px solid rgba(93, 247, 255, 0.28);
  background: rgba(5, 12, 20, 0.62);
  color: #a9e8f6;
  font-family: var(--mono);
  font-size: 12px;
  cursor: pointer;
  transition: 0.15s;
  backdrop-filter: blur(4px);
}
.icon-btn:hover { border-color: var(--cyan); color: #fff; box-shadow: 0 0 14px rgba(93, 247, 255, 0.3); }
.hud-zone {
  position: absolute;
  left: 2.3%;
  bottom: 4%;
  font-size: clamp(6px, 0.55vw, 9px);
  letter-spacing: 0.22em;
  color: rgba(138, 178, 192, 0.55);
  display: flex;
  align-items: center;
  gap: 6px;
}
.live-dot { width: 4px; height: 4px; background: var(--red); border-radius: 50%; box-shadow: 0 0 6px var(--red); animation: blink 1.1s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0.2; } }

/* --------------------------------------------------------------- SCREENS */
.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(27, 12, 55, 0.25), rgba(2, 1, 8, 0.88) 74%),
    linear-gradient(180deg, rgba(2, 1, 8, 0.25), rgba(2, 1, 8, 0.92));
  backdrop-filter: blur(3px);
}
.screen.active { display: grid; animation: screenIn 0.3s ease both; }
@keyframes screenIn { from { opacity: 0; } to { opacity: 1; } }
.screen.instant.active { animation: none; }

.menu-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.5;
  background:
    linear-gradient(180deg, transparent 30%, rgba(5, 3, 13, 0.9) 86%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(93, 247, 255, 0.025) 3px 4px);
  mask-image: linear-gradient(180deg, transparent, #000 40%);
}

.menu-shell {
