}
.eyebrow .rule { width: 44px; height: 1px; background: linear-gradient(90deg, transparent, var(--cyan)); }
.eyebrow .rule:last-child { background: linear-gradient(90deg, var(--cyan), transparent); }

.logo {
  position: relative;
  margin: 0;
  line-height: 0.9;
  font-family: var(--display);
  font-weight: 900;
  text-transform: uppercase;
  filter: drop-shadow(0 0 28px rgba(93, 247, 255, 0.17));
}
.logo-main {
  position: relative;
  display: block;
  font-size: clamp(38px, 7.8vw, 118px);
  letter-spacing: 0.035em;
  color: #f4feff;
  background: linear-gradient(180deg, #ffffff 8%, #c9f9ff 44%, #6fa9c8 54%, #d7f7ff 72%, #7b5fff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 0 42px rgba(93, 247, 255, 0.16);
}
.logo-main::before, .logo-main::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  background: none;
  -webkit-text-fill-color: initial;
  color: transparent;
  pointer-events: none;
}
.logo-main::before {
  color: rgba(255, 63, 206, 0.65);
  clip-path: polygon(0 34%, 100% 34%, 100% 48%, 0 48%);
  transform: translateX(-3px);
  animation: glitchA 4.1s steps(1) infinite;
  mix-blend-mode: screen;
}
.logo-main::after {
  color: rgba(93, 247, 255, 0.6);
  clip-path: polygon(0 62%, 100% 62%, 100% 71%, 0 71%);
  transform: translateX(3px);
  animation: glitchB 3.3s steps(1) infinite;
  mix-blend-mode: screen;
}
@keyframes glitchA {
  0%, 92%, 100% { transform: translateX(-3px); opacity: 0.7; }
  93% { transform: translateX(9px); opacity: 1; }
  94% { transform: translateX(-8px); }
  95% { transform: translateX(2px); opacity: 0.2; }
  96% { transform: translateX(-3px); opacity: 0.7; }
}
@keyframes glitchB {
  0%, 89%, 100% { transform: translateX(3px); opacity: 0.6; }
  90% { transform: translateX(-11px); opacity: 1; }
  91% { transform: translateX(7px); opacity: 0.15; }
  92% { transform: translateX(3px); opacity: 0.6; }
}
.logo-shadow {
  position: absolute;
  inset: 0;
  font-size: clamp(38px, 7.8vw, 118px);
  letter-spacing: 0.035em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(93, 247, 255, 0.2);
  transform: translate(0, 8px) scaleY(1.04);
  z-index: -1;
}
.logo-sub {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 14px;
  font-family: var(--display);
  font-size: clamp(13px, 2.1vw, 31px);
  letter-spacing: 0.5em;
  color: var(--magenta);
  text-shadow: 0 0 22px rgba(255, 63, 206, 0.7), 0 0 3px #fff;
}
.logo-sub i { width: clamp(16px, 3vw, 46px); height: 1px; background: linear-gradient(90deg, transparent, var(--magenta)); }
.logo-sub i:last-child { background: linear-gradient(90deg, var(--magenta), transparent); }
.tagline {
  margin: 3.2vh auto 0;
