/* -------------------------------------------------------------- TOUCH UI */
#touch-controls {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  display: none;
  font-family: var(--mono);
}
#touch-controls.active { display: block; }
.stick {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(18px, env(safe-area-inset-bottom));
  width: clamp(94px, 16vh, 128px);
  height: clamp(94px, 16vh, 128px);
  pointer-events: auto;
  touch-action: none;
}
.stick-ring {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(93, 247, 255, 0.22);
  background: radial-gradient(circle, rgba(93, 247, 255, 0.05), rgba(3, 7, 14, 0.35));
  border-radius: 50%;
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.5);
}
.stick-ring::after {
  content: "";
  position: absolute;
  inset: 14%;
  border: 1px dashed rgba(93, 247, 255, 0.12);
  border-radius: 50%;
}
.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42%;
  height: 42%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 40% 35%, rgba(168, 251, 255, 0.5), rgba(31, 96, 119, 0.45));
  border: 1px solid rgba(93, 247, 255, 0.55);
  border-radius: 50%;
  box-shadow: 0 0 16px rgba(93, 247, 255, 0.28);
}
.stick span { position: absolute; left: 50%; bottom: -15px; transform: translateX(-50%); font-size: 7px; letter-spacing: 0.3em; color: rgba(139, 205, 220, 0.45); }
.touch-actions {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  width: clamp(180px, 34vh, 260px);
  height: clamp(130px, 25vh, 190px);
  pointer-events: none;
}
.touch-btn {
  position: absolute;
  pointer-events: auto;
  touch-action: none;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(93, 247, 255, 0.12), rgba(4, 10, 19, 0.55));
  border: 1px solid rgba(93, 247, 255, 0.4);
  color: #c8f7ff;
  font-family: var(--mono);
  font-size: clamp(7px, 1.1vh, 10px);
  letter-spacing: 0.1em;
  box-shadow: 0 0 18px rgba(93, 247, 255, 0.12), inset 0 0 20px rgba(93, 247, 255, 0.05);
  transition: transform 0.08s, background 0.08s;
}
.touch-btn.pressed { transform: scale(0.92); background: radial-gradient(circle, rgba(93, 247, 255, 0.45), rgba(5, 18, 28, 0.7)); }
.touch-btn.attack { right: 70px; bottom: 30px; width: clamp(62px, 12vh, 84px); height: clamp(62px, 12vh, 84px); font-family: var(--display); font-size: clamp(20px, 3.6vh, 30px); border-color: rgba(255, 63, 206, 0.5); color: #ffe2f8; background: radial-gradient(circle at 35% 30%, rgba(255, 63, 206, 0.16), rgba(10, 4, 20, 0.55)); box-shadow: 0 0 22px rgba(255, 63, 206, 0.14); }
.touch-btn.attack.pressed { background: radial-gradient(circle, rgba(255, 63, 206, 0.5), rgba(20, 5, 28, 0.7)); }
.touch-btn.jump { right: 0; bottom: 76px; width: clamp(56px, 10vh, 70px); height: clamp(56px, 10vh, 70px); }
.touch-btn.dash { right: 10px; bottom: 0; width: clamp(48px, 8.5vh, 60px); height: clamp(48px, 8.5vh, 60px); font-size: clamp(6px, 0.9vh, 9px); border-color: rgba(138, 92, 255, 0.45); }

/* -------------------------------------------------------------- ROTATE */
.rotate-msg {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: none;
  place-items: center;
  align-content: center;
  gap: 14px;
  padding: 30px;
  text-align: center;
  background: radial-gradient(circle at 50% 40%, #100b25, #020106 70%);
  color: #dffbff;
}
.rotate-phone {
  width: 46px;
  height: 76px;
  border: 2px solid var(--cyan);
  border-radius: 8px;
  box-shadow: 0 0 22px rgba(93, 247, 255, 0.4);
  animation: rotatePhone 2.4s ease-in-out infinite;
  margin-bottom: 6px;
}
@keyframes rotatePhone { 0%, 20% { transform: rotate(0); } 55%, 100% { transform: rotate(90deg); } }
.rotate-msg strong { font-family: var(--display); letter-spacing: 0.18em; font-size: 16px; }
.rotate-msg span { color: #7f9caf; font-size: 12px; letter-spacing: 0.08em; }
@media (orientation: portrait) and (max-width: 820px) {
  .rotate-msg { display: grid; }
}

/* ------------------------------------------------------------- LOADING */
.loading {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 14px;
  background: #030208;
  transition: opacity 0.55s ease, visibility 0.55s;
}
.loading.done { opacity: 0; visibility: hidden; }
.load-mark {
  font-family: var(--display);
  font-size: 42px;
  color: var(--cyan);
  text-shadow: 0 0 30px rgba(93, 247, 255, 0.6);
  animation: loadPulse 1.3s ease-in-out infinite;
}
@keyframes loadPulse { 50% { opacity: 0.4; transform: scale(0.96); } }
.load-bar { width: 180px; height: 2px; background: rgba(93, 247, 255, 0.12); overflow: hidden; }
.load-bar i { display: block; width: 40%; height: 100%; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); animation: loadSlide 1.1s ease-in-out infinite; }
@keyframes loadSlide { 0% { transform: translateX(-110%); } 100% { transform: translateX(360%); } }
.load-text { font-family: var(--mono); font-size: 8px; letter-spacing: 0.4em; color: #6e8da0; }

/* ------------------------------------------------------------ UTILITY */
.hidden { display: none !important; }

@media (max-width: 760px) {
  .screen { padding: 14px; }
  .menu-shell { padding-top: 0; }
  .menu-footer { position: static; margin-top: 3vh; flex-direction: column; align-items: center; gap: 8px; }
  .key-hints { display: none; }
  .menu-actions { margin-top: 3vh; }
  .help-grid { grid-template-columns: 1fr; max-height: 54vh; overflow: auto; }
  .panel { padding: 24px 20px; }
  .panel.wide { max-height: 94vh; overflow: auto; }
  .bar-value { display: none; }
  .hud-left { width: 38%; }
