  .orb-block { font-size: 9px; }
  .boss-hud { width: 72%; }
  .logo-sub { letter-spacing: 0.32em; }
  .tagline { max-width: 340px; }
}
@media (max-height: 600px) {
  .tagline { margin-top: 2vh; }
  .menu-actions { margin-top: 2.5vh; gap: 6px; }
  .btn-primary { padding: 12px 26px; }
  .menu-footer { display: none; }
  .logo-sub { margin-top: 8px; }
  .help-grid { max-height: 42vh; overflow: auto; }
}
@media (prefers-reduced-motion: reduce) {
  #grain, .logo-main::before, .logo-main::after, .live-dot, .load-mark, .bar.health.low .fill { animation: none !important; }
}

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => clamp((v - a) / (b - a || 1), 0, 1);
export const smoothstep = (t) => { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); };
export const approach = (v, target, delta) => (v < target ? Math.min(v + delta, target) : Math.max(v - delta, target));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const hypot = (x, y) => Math.sqrt(x * x + y * y);
export const sign = (v) => (v < 0 ? -1 : 1);

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
export const easeInCubic = (t) => Math.pow(clamp(t, 0, 1), 3);
export const easeOutBack = (t) => {
  const c1 = 1.70158, c3 = c1 + 1, x = clamp(t, 0, 1);
  return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
};
export const easeInOut = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

export function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
export function circleRect(cx, cy, r, rect) {
  const nx = clamp(cx, rect.x, rect.x + rect.w);
  const ny = clamp(cy, rect.y, rect.y + rect.h);
  const dx = cx - nx, dy = cy - ny;
  return dx * dx + dy * dy <= r * r;
}
export function dist2(ax, ay, bx, by) {
  const dx = ax - bx, dy = ay - by;
  return dx * dx + dy * dy;
}
export function formatScore(n, pad = 6) {
  return String(Math.max(0, Math.floor(n))).padStart(pad, "0");
}
export function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}
export function rgba(hex, a) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map(c => c + c).join("") : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}
export function shade(hex, amt) {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map(c => c + c).join("") : h, 16);
  const r = clamp(((n >> 16) & 255) + amt, 0, 255);
  const g = clamp(((n >> 8) & 255) + amt, 0, 255);
  const b = clamp((n & 255) + amt, 0, 255);
  return `rgb(${r},${g},${b})`;
}

const KEY_ACTIONS = {
  ArrowLeft: "left", KeyA: "left",
  ArrowRight: "right", KeyD: "right",
  ArrowDown: "down", KeyS: "down",
  ArrowUp: "jump", KeyW: "jump", Space: "jump",
  KeyJ: "attack", KeyZ: "attack", KeyX: "attack",
  ShiftLeft: "dash", ShiftRight: "dash", KeyK: "dash",
};

const PREVENT = new Set([
  "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Space",
  "KeyA", "KeyD", "KeyW", "KeyS", "KeyJ", "KeyZ", "KeyX", "KeyK",
  "ShiftLeft", "ShiftRight",
]);

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.held = { left: false, right: false, down: false, jump: false, attack: false, dash: false };
    this.pressed = { left: false, right: false, down: false, jump: false, attack: false, dash: false, pause: false, mute: false };
    this.touch = { left: false, right: false };
    this.touchAxis = 0;
    this.touchActive = false;
    this.onPause = null;
    this.onMute = null;
    this.stickPointer = null;
    this.stickCenter = { x: 0, y: 0 };
    this.stickRadius = 44;
    this._bindKeyboard();
    this._bindTouch();
    this._bindMouse();
  }

  _bindKeyboard() {
    window.addEventListener("keydown", (e) => {
      if (e.code === "Escape" || e.code === "KeyP") {
        if (!e.repeat) {
          this.pressed.pause = true;
          this.onPause?.();
        }
        e.preventDefault();
        return;
      }
      if (e.code === "KeyM") {
        if (!e.repeat) this.onMute?.();
        return;
      }
      if (e.code === "KeyR") {
        if (!e.repeat) this.pressed.retry = true;
      }
      const action = KEY_ACTIONS[e.code];
      if (action) {
        if (PREVENT.has(e.code)) e.preventDefault();
        if (!e.repeat) this._press(action);
        else this.held[action] = true;
      }
    }, { passive: false });

    window.addEventListener("keyup", (e) => {
      const action = KEY_ACTIONS[e.code];
      if (action) this.held[action] = false;
    });

    window.addEventListener("blur", () => this.releaseAll());
  }

  _bindMouse() {
    this.canvas.addEventListener("pointerdown", (e) => {
      if (e.pointerType !== "mouse") return;
      if (e.button === 0) this._press("attack");
    });
    this.canvas.addEventListener("contextmenu", (e) => e.preventDefault());
  }

  _bindTouch() {
    const controls = document.getElementById("touch-controls");
    const stick = document.getElementById("stick");
    const knob = document.getElementById("stick-knob");
    if (!controls || !stick || !knob) return;

    const coarse = window.matchMedia?.("(pointer: coarse)").matches || navigator.maxTouchPoints > 0;
    this.isCoarse = !!coarse;
    if (!coarse) return;

    const updateStick = (e) => {
      const dx = e.clientX - this.stickCenter.x;
      const dy = e.clientY - this.stickCenter.y;
      const len = Math.hypot(dx, dy) || 1;
      const clamped = Math.min(len, this.stickRadius);
      const nx = (dx / len) * clamped;
      const ny = (dy / len) * clamped;
      knob.style.transform = `translate(calc(-50% + ${nx}px), calc(-50% + ${ny}px))`;
      let axis = nx / this.stickRadius;
      if (Math.abs(axis) < 0.16) axis = 0;
      this.touchAxis = Math.max(-1, Math.min(1, axis * 1.25));
      this.touch.left = this.touchAxis < -0.05;
      this.touch.right = this.touchAxis > 0.05;
      if (Math.abs(this.touchAxis) > 0.55) {
        if (!this._stickDashSent && e.pointerId === this.stickPointer) {
          this._stickDashSent = false;
        }
      }
    };

    stick.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      this.stickPointer = e.pointerId;
      stick.setPointerCapture?.(e.pointerId);
      const r = stick.getBoundingClientRect();
      this.stickCenter = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      this.stickRadius = r.width * 0.38;
      updateStick(e);
    });
    stick.addEventListener("pointermove", (e) => {
      if (e.pointerId !== this.stickPointer) return;
      e.preventDefault();
      updateStick(e);
    });
    const endStick = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      this.stickPointer = null;
      this.touchAxis = 0;
      this.touch.left = this.touch.right = false;
      knob.style.transform = "translate(-50%, -50%)";
    };
    stick.addEventListener("pointerup", endStick);
    stick.addEventListener("pointercancel", endStick);
    stick.addEventListener("lostpointercapture", endStick);

    const bindButton = (id, action) => {
      const el = document.getElementById(id);
      if (!el) return;
      let pid = null;
      const down = (e) => {
        e.preventDefault();
        pid = e.pointerId;
        el.setPointerCapture?.(e.pointerId);
        el.classList.add("pressed");
        this._press(action);
      };
      const up = (e) => {
        if (pid !== null && e.pointerId !== pid) return;
        pid = null;
        el.classList.remove("pressed");
        this.held[action] = false;
      };
      el.addEventListener("pointerdown", down);
      el.addEventListener("pointerup", up);
      el.addEventListener("pointercancel", up);
      el.addEventListener("lostpointercapture", up);
    };
    bindButton("touch-jump", "jump");
    bindButton("touch-attack", "attack");
    bindButton("touch-dash", "dash");
  }

  setTouchVisible(visible) {
    this.touchActive = visible;
    const el = document.getElementById("touch-controls");
    if (el) el.classList.toggle("active", visible && !!this.isCoarse);
  }

  _press(action) {
    if (!(action in this.held)) return;
    this.pressed[action] = true;
    this.held[action] = true;
    if (action === "jump") this.pressed.jumpAt = performance.now();
  }

  consume(action) {
    if (this.pressed[action]) {
      this.pressed[action] = false;
      return true;
    }
    return false;
  }

  releaseAll() {
    for (const k of Object.keys(this.held)) this.held[k] = false;
    this.touchAxis = 0;
    this.touch.left = this.touch.right = false;
  }

  get axis() {
    let a = 0;
    if (this.held.left) a -= 1;
    if (this.held.right) a += 1;
    if (this.touch.left) a -= Math.abs(this.touchAxis);
    if (this.touch.right) a += Math.abs(this.touchAxis);
    return Math.max(-1, Math.min(1, a));
  }

  get jumpHeld() { return this.held.jump; }
  get attackHeld() { return this.held.attack; }
  get dashHeld() { return this.held.dash; }

  clearFramePresses() {
    for (const key of Object.keys(this.pressed)) {
      if (key !== "pause" && key !== "retry") this.pressed[key] = false;
    }
    this.pressed.pause = false;
    this.pressed.retry = false;
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.ready = false;
    this.musicPlaying = false;
    this.nextIntensity = 0;
    this.nextNoteTime = 0;
    this.step = 0;
    this.noise = null;
    this._lastSfx = new Map();
  }

  init() {
    if (this.ready) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 8;
    comp.attack.value = 0.004;
    comp.release.value = 0.22;
    comp.connect(ctx.destination);

    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.85;
    this.master.connect(comp);
    this.sfxGain = ctx.createGain();
    this.sfxGain.gain.value = 0.9;
    this.sfxGain.connect(this.master);
    this.musicGain = ctx.createGain();
    this.musicGain.gain.value = 0;
    this.musicGain.connect(this.master);

    this.noise = this._makeNoise(2);
    this.ready = true;
    this._buildPad();
  }

  _makeNoise(seconds) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.85, t, 0.04);
    }
    try { localStorage.setItem("shadowstrike.muted", muted ? "1" : "0"); } catch {}
    return muted;
  }

  toggle() { return this.setMuted(!this.muted); }

  _env(node, gain, attack, decay, peak = 1) {
    const t = this.ctx.currentTime;
    node.gain.cancelScheduledValues(t);
    node.gain.setValueAtTime(0.0001, t);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak * gain), t + attack);
    node.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  }

  _tone(freq, dur, type = "sine", gain = 0.12, slide = 0, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.012, dur * 0.15));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.sfxGain);
    o.start(t);
    o.stop(t + dur + 0.03);
  }

  _noiseBurst(dur, filterType, freq, gain, slide = 0, q = 0.8, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(freq, t);
    if (slide) filter.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);
    filter.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(g).connect(this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  play(name, intensity = 1) {
    if (!this.ready || this.muted) return;
    const now = performance.now();
    const throttle = this._lastSfx.get(name) || 0;
    if (now - throttle < 28) return;
    this._lastSfx.set(name, now);
    switch (name) {
      case "ui":
        this._tone(720, 0.05, "square", 0.025);
        break;
      case "jump":
        this._tone(260, 0.16, "sine", 0.08, 640);
        this._noiseBurst(0.1, "highpass", 900, 0.018);
        break;
      case "doubleJump":
        this._tone(420, 0.18, "triangle", 0.07, 1000);
        this._noiseBurst(0.13, "highpass", 1400, 0.02);
        break;
      case "land":
        this._noiseBurst(0.08, "lowpass", 420, 0.05);
        break;
      case "dash":
        this._noiseBurst(0.3, "bandpass", 1800, 0.11, 260, 1.3);
        this._tone(190, 0.22, "sawtooth", 0.03, 70);
        break;
      case "slash":
        this._noiseBurst(0.14, "highpass", 2200, 0.095, 780, 0.7);
        this._tone(740, 0.1, "triangle", 0.028, 300);
        break;
      case "slash2":
        this._noiseBurst(0.16, "bandpass", 2900, 0.085, 900, 1.2);
        this._tone(920, 0.11, "triangle", 0.024, 410);
        break;
      case "slash3":
        this._noiseBurst(0.24, "highpass", 1800, 0.12, 420, 0.6);
        this._tone(320, 0.26, "sawtooth", 0.045, 90);
        break;
      case "hit":
        this._tone(160, 0.09, "square", 0.07, 54);
        this._noiseBurst(0.13, "bandpass", 1300, 0.11, 300, 1.1);
        break;
      case "heavy":
        this._tone(92, 0.22, "sine", 0.13, 38);
        this._noiseBurst(0.2, "lowpass", 800, 0.13, 140);
        break;
      case "hurt":
        this._tone(180, 0.25, "sawtooth", 0.09, 48);
        this._noiseBurst(0.2, "lowpass", 900, 0.08, 180);
        break;
      case "orb":
        this._tone(980, 0.12, "sine", 0.055, 1480);
        this._tone(1470, 0.14, "triangle", 0.025, 1960, 0.04);
        break;
      case "heal":
        this._tone(520, 0.3, "sine", 0.055, 780);
        this._tone(780, 0.4, "triangle", 0.03, 1040, 0.08);
        break;
      case "checkpoint":
        [392, 523.25, 659.25].forEach((f, i) => this._tone(f, 0.7, "sine", 0.045, 0, i * 0.07));
        this._noiseBurst(0.5, "highpass", 3000, 0.02);
        break;
      case "enemyDie":
        this._tone(120, 0.32, "square", 0.055, 38);
        this._noiseBurst(0.4, "lowpass", 1200, 0.12, 120);
        break;
      case "bossHit":
        this._tone(110, 0.16, "square", 0.05, 50);
        this._noiseBurst(0.18, "bandpass", 900, 0.07, 240);
        break;
      case "bossRoar":
        this._tone(70, 1.15, "sawtooth", 0.12, 34);
        this._tone(46, 1.3, "sine", 0.12, 28);
        this._noiseBurst(1.2, "lowpass", 500, 0.13, 90);
        break;
      case "shockwave":
        this._tone(54, 0.6, "sine", 0.18, 26);
        this._noiseBurst(0.5, "lowpass", 500, 0.16, 80);
        break;
      case "laser":
        this._tone(1100, 0.8, "sawtooth", 0.06, 130, 0.02);
        this._noiseBurst(0.75, "bandpass", 2400, 0.08, 400, 1.6, 0.05);
        break;
      case "parry":
        this._tone(1600, 0.12, "square", 0.04, 2400);
        this._noiseBurst(0.06, "highpass", 5000, 0.05);
        break;
      case "death":
        this._tone(140, 1.4, "sawtooth", 0.09, 30);
        this._noiseBurst(1.1, "lowpass", 900, 0.12, 60);
        break;
      case "victory":
        [261.63, 329.63, 392, 523.25, 659.25, 783.99].forEach((f, i) => {
          this._tone(f, 1.6, "triangle", 0.045, 0, i * 0.13);
          this._tone(f / 2, 2.0, "sine", 0.03, 0, i * 0.13);
        });
        break;
      case "bossDie":
        this._noiseBurst(1.8, "lowpass", 1400, 0.2, 60);
        this._tone(70, 1.6, "sawtooth", 0.12, 24);
        [0, 0.18, 0.4, 0.72, 1.1].forEach((d, i) => this._noiseBurst(0.35 + i * 0.08, "bandpass", 500 + i * 350, 0.13, 100, 0.9, d));
        break;
      default:
        break;
    }
  }

  _buildPad() {
    const ctx = this.ctx;
    const pad = ctx.createGain();
    pad.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 420;
    filter.Q.value = 4;
    pad.connect(filter).connect(this.musicGain);
    const freqs = [55, 82.41, 110, 164.81];
    freqs.forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i % 2 ? "triangle" : "sawtooth";
      o.frequency.value = f;
      o.detune.value = (i - 1.5) * 7;
      const g = ctx.createGain();
      g.gain.value = i === 3 ? 0.035 : 0.055;
      o.connect(g).connect(pad);
      o.start();
    });
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 180;
    lfo.connect(lfoGain).connect(filter.frequency);
    lfo.start();
    this.padGain = pad;
    this.padFilter = filter;
    this.musicGain.gain.setTargetAtTime(0.55, ctx.currentTime, 1.2);
    this.musicPlaying = true;
    this.nextNoteTime = ctx.currentTime + 0.2;
  }

  setIntensity(value) {
    this.nextIntensity = value;
    if (this.padFilter) this.padFilter.frequency.setTargetAtTime(360 + value * 340, this.ctx.currentTime, 1.5);
  }

  update(dt) {
    if (!this.ready || !this.musicPlaying || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    if (this.nextNoteTime < now) this.nextNoteTime = now + 0.02;
    const stepDur = 0.285;
    const bass = [55, 55, 65.41, 55, 73.42, 65.41, 49, 55];
    const high = [220, 261.63, 329.63, 261.63, 293.66, 349.23, 196, 220];
    let guard = 0;
    while (this.nextNoteTime < now + 0.12 && guard++ < 8) {
      const t = this.nextNoteTime;
      const step = this.step % 8;
      this._scheduleBass(bass[step], t, 0.26);
      if (this.nextIntensity > 0.15 || step % 2 === 0) {
        this._schedulePluck(high[step] * (this.nextIntensity > 0.6 ? 2 : 1), t, 0.18, 0.012 + this.nextIntensity * 0.018);
      }
      if (step === 0 || step === 4) this._scheduleKick(t);
      this.nextNoteTime += stepDur;
      this.step++;
    }
  }

  _scheduleBass(freq, t, dur) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    const f = ctx.createBiquadFilter();
    o.type = "sawtooth";
    o.frequency.value = freq;
    f.type = "lowpass";
    f.frequency.setValueAtTime(240, t);
    f.frequency.exponentialRampToValueAtTime(110, t + dur);
    f.Q.value = 5;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.07, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f).connect(g).connect(this.musicGain);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  _schedulePluck(freq, t, dur, gain) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = "triangle";
    o.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.musicGain);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  _scheduleKick(t) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = "sine";
    o.frequency.setValueAtTime(110, t);
    o.frequency.exponentialRampToValueAtTime(40, t + 0.16);
    g.gain.setValueAtTime(0.10, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
    o.connect(g).connect(this.musicGain);
    o.start(t);
    o.stop(t + 0.22);
  }

  stopMusic() {
    if (!this.ready || !this.musicGain) return;
    this.musicGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.4);
    this.musicPlaying = false;
  }

  resumeMusic() {
    if (!this.ready || !this.musicGain) return;
    this.musicGain.gain.setTargetAtTime(0.55, this.ctx.currentTime, 0.5);
    this.musicPlaying = true;
    this.nextNoteTime = this.ctx.currentTime + 0.08;
  }
}

import { rand, randInt, TAU, clamp } from "./util.js";

const MAX_PARTICLES = 700;

export class Particles {
  constructor() {
    this.items = [];
    this.texts = [];
    this.rings = [];
  }

  add(opts) {
    if (this.items.length >= MAX_PARTICLES) this.items.shift();
    this.items.push({
      x: opts.x, y: opts.y,
      vx: opts.vx ?? 0, vy: opts.vy ?? 0,
      gravity: opts.gravity ?? 0,
      drag: opts.drag ?? 0.98,
      life: opts.life ?? 0.5,
      maxLife: opts.life ?? 0.5,
      size: opts.size ?? 3,
      endSize: opts.endSize ?? 0,
      color: opts.color ?? "#5df7ff",
      alpha: opts.alpha ?? 1,
      additive: opts.additive !== false,
      shape: opts.shape ?? "dot",
      rotation: opts.rotation ?? 0,
      spin: opts.spin ?? 0,
      glow: opts.glow ?? 0,
      stretch: opts.stretch ?? 1,
      tail: opts.tail ?? 0,
    });
  }

  spark(x, y, color, count = 8, power = 260) {
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU);
      const s = rand(power * 0.25, power);
      this.add({
        x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - power * 0.15,
        gravity: 700, drag: 0.93, life: rand(0.18, 0.48), size: rand(1, 2.6),
        endSize: 0, color, shape: "line", stretch: rand(0.5, 1.6), glow: 8,
      });
    }
  }

  hit(x, y, color = "#fff6cc", heavy = false) {
    this.spark(x, y, color, heavy ? 16 : 9, heavy ? 420 : 280);
    for (let i = 0; i < (heavy ? 5 : 2); i++) {
      this.add({
        x: x + rand(-8, 8), y: y + rand(-8, 8),
        vx: rand(-60, 60), vy: rand(-120, -20), gravity: 300,
        life: rand(0.3, 0.6), size: rand(8, 18), endSize: rand(20, 36),
        color, shape: "smoke", alpha: 0.15, additive: false, drag: 0.96,
      });
    }
    this.ring(x, y, color, heavy ? 52 : 30, heavy ? 0.28 : 0.18);
  }

  dust(x, y, color = "#6fd4e8", count = 4, power = 70) {
    for (let i = 0; i < count; i++) {
      this.add({
        x: x + rand(-8, 8), y: y - rand(0, 5),
        vx: rand(-power, power), vy: rand(-power * 0.7, -8),
        gravity: 120, drag: 0.92, life: rand(0.25, 0.5), size: rand(3, 7),
        endSize: rand(9, 17), color, shape: "smoke", alpha: 0.4, additive: false,
      });
    }
  }

  explosion(x, y, color = "#ff8a3d", scale = 1) {
    this.add({ x, y, vx: 0, vy: 0, life: 0.32, size: 10 * scale, endSize: 100 * scale, color: "#fff3d0", shape: "flash", glow: 30 });
    this.ring(x, y, color, 40 * scale, 0.42, 5);
    this.ring(x, y, "#fff3d0", 24 * scale, 0.22, 3);
    this.spark(x, y, color, Math.round(22 * scale), 460 * scale);
    this.spark(x, y, "#ffffff", Math.round(10 * scale), 360 * scale);
    for (let i = 0; i < 12 * scale; i++) {
      const a = rand(0, TAU);
      this.add({
        x, y,
        vx: Math.cos(a) * rand(40, 170) * scale,
        vy: Math.sin(a) * rand(40, 170) * scale - 50,
        gravity: 520, drag: 0.985,
        life: rand(0.45, 1.05), size: rand(2, 6) * scale, endSize: 1,
        color: i % 3 === 0 ? "#ffcf7a" : color, shape: "shard",
        rotation: rand(0, TAU), spin: rand(-12, 12), glow: 6,
      });
    }
    for (let i = 0; i < 7; i++) {
      this.add({
        x: x + rand(-20, 20), y: y + rand(-20, 20),
        vx: rand(-40, 40), vy: rand(-90, -20), drag: 0.97,
        life: rand(0.6, 1.3), size: rand(14, 30) * scale, endSize: rand(40, 70) * scale,
        color: "#3a2a44", shape: "smoke", alpha: 0.28, additive: false,
      });
    }
  }

  orbTrail(x, y, color = "#5df7ff") {
    this.add({
      x: x + rand(-3, 3), y: y + rand(-3, 3), vx: rand(-30, 30), vy: rand(-30, 30),
      drag: 0.9, life: rand(0.2, 0.45), size: rand(2, 5), color, glow: 10, shape: "dot",
    });
  }

  slashTrail(x1, y1, x2, y2, color = "#bffcff", width = 3) {
    this.add({
      x: x1, y: y1, vx: (x2 - x1) * 2, vy: (y2 - y1) * 2,
      life: 0.12, size: width, color, shape: "line", glow: 12, drag: 0.9,
      stretch: 1, tail: 0,
    });
  }

  ring(x, y, color, radius, life = 0.3, width = 2) {
    if (this.rings.length > 30) this.rings.shift();
    this.rings.push({ x, y, color, radius, life, maxLife: life, width });
  }

  text(x, y, text, color = "#bffcff", size = 16, vy = -50) {
    if (this.texts.length > 24) this.texts.shift();
    this.texts.push({ x, y, text, color, size, vy, life: 0.85, maxLife: 0.85, vx: rand(-12, 12) });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const p = this.items[i];
      p.life -= dt;
      if (p.life <= 0) { this.items.splice(i, 1); continue; }
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy = p.vy * Math.pow(p.drag, dt * 60) + p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rotation += p.spin * dt;
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      if (r.life <= 0) this.rings.splice(i, 1);
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      if (t.life <= 0) { this.texts.splice(i, 1); continue; }
      t.y += t.vy * dt;
      t.x += t.vx * dt;
      t.vy += 60 * dt;
    }
  }

  draw(ctx) {
    // smoke/dark particles first
    ctx.save();
    for (const p of this.items) {
      if (p.additive) continue;
      const t = p.life / p.maxLife;
      const alpha = p.alpha * t;
      if (alpha <= 0.005) continue;
      const size = p.size + (p.endSize - p.size) * (1 - t);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = p.color;
      if (p.shape === "smoke") {
        ctx.beginPath();
        ctx.arc(p.x, p.y, size, 0, TAU);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, size, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();

    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const p of this.items) {
      if (!p.additive) continue;
      const t = p.life / p.maxLife;
      const alpha = p.alpha * (t > 0.8 ? (1 - t) / 0.2 : t / 0.8);
      if (alpha <= 0.005) continue;
      const size = p.size + (p.endSize - p.size) * (1 - t);
      ctx.globalAlpha = Math.min(1, alpha);
      ctx.fillStyle = p.color;
      ctx.strokeStyle = p.color;
      if (p.glow > 0) {
        ctx.shadowBlur = p.glow;
        ctx.shadowColor = p.color;
      } else {
        ctx.shadowBlur = 0;
      }
      if (p.shape === "line") {
        const len = Math.max(size, size * (p.stretch + 1));
        const speed = Math.hypot(p.vx, p.vy) || 1;
        ctx.lineWidth = Math.max(0.7, size * 0.65);
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - (p.vx / speed) * len, p.y - (p.vy / speed) * len);
        ctx.stroke();
      } else if (p.shape === "shard") {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rotation);
        ctx.beginPath();
        ctx.moveTo(-size, -size * 0.3);
        ctx.lineTo(size * 0.4, -size * 0.55);
        ctx.lineTo(size, size * 0.4);
        ctx.lineTo(-size * 0.5, size * 0.35);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      } else if (p.shape === "flash") {
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, size);
        g.addColorStop(0, "rgba(255,255,255,0.95)");
        g.addColorStop(0.35, p.color);
        g.addColorStop(1, "rgba(255,255,255,0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(p.x, p.y, size, 0, TAU);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0.4, size), 0, TAU);
        ctx.fill();
      }
    }
    for (const r of this.rings) {
      const t = 1 - r.life / r.maxLife;
      ctx.globalAlpha = (1 - t) * 0.85;
      ctx.strokeStyle = r.color;
      ctx.lineWidth = r.width * (1 - t) + 0.5;
      ctx.shadowBlur = 12;
      ctx.shadowColor = r.color;
      ctx.beginPath();
      ctx.arc(r.x, r.y, Math.max(1, r.radius * t), 0, TAU);
      ctx.stroke();
    }
    // text
    ctx.globalCompositeOperation = "source-over";
    for (const t of this.texts) {
      const a = clamp(t.life / t.maxLife * 1.6, 0, 1);
      ctx.globalAlpha = a;
      ctx.font = `700 ${t.size}px "DejaVu Sans Mono", monospace`;
      ctx.textAlign = "center";
      ctx.fillStyle = "#05030d";
      ctx.fillText(t.text, t.x + 1.5, t.y + 1.5);
      ctx.fillStyle = t.color;
      ctx.fillText(t.text, t.x, t.y);
    }
    ctx.restore();
  }

  clear() {
    this.items.length = 0;
    this.texts.length = 0;
    this.rings.length = 0;
  }
}

import { TAU, clamp, lerp, mulberry32, rand } from "./util.js";

export const VIEW_W = 1280;
export const VIEW_H = 720;
export const GROUND_Y = 620;
export const WORLD_W = 12200;

export const ZONES = [
  { id: 0, x0: 0, x1: 3260, name: "NEON DISTRICT", sub: "INFILTRATE THE SPIRE", label: "01", palette: { top: "#05020f", mid: "#1a0a34", glow: "#ff3fce", accent: "#5df7ff", haze: "#3d1b5e" } },
  { id: 1, x0: 3260, x1: 7480, name: "GHOST MARKET", sub: "CUT THROUGH THE MACHINES", label: "02", palette: { top: "#020a12", mid: "#062838", glow: "#5df7ff", accent: "#ff3fce", haze: "#0d4050" } },
  { id: 2, x0: 7480, x1: 10480, name: "SPIRE ASCENT", sub: "CLIMB TOWARD THE SIGNAL", label: "03", palette: { top: "#080414", mid: "#210b38", glow: "#8a5cff", accent: "#ffc36b", haze: "#341455" } },
  { id: 3, x0: 10480, x1: WORLD_W, name: "ZERO SPIRE", sub: "CUT THE HEAD OFF THE CITY", label: "04", palette: { top: "#0d0208", mid: "#2a0712", glow: "#ff3e62", accent: "#ffc36b", haze: "#4d0d19" } },
];

function hexToRgb(hex) {
  const n = parseInt(hex.replace("#", ""), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
function mixRgb(a, b, t) {
  const A = hexToRgb(a), B = hexToRgb(b);
  return {
    r: Math.round(lerp(A.r, B.r, t)),
    g: Math.round(lerp(A.g, B.g, t)),
    b: Math.round(lerp(A.b, B.b, t)),
  };
}
function css(c, a = 1) { return `rgba(${c.r},${c.g},${c.b},${a})`; }

export class Background {
  constructor() {
    this.layers = [];
    this.time = 0;
    this.camera = 0;
    this.flash = 0;
    this.nextLightning = 9;
    this.cars = [];
    this.rain = [];
    this.stars = [];
    this.dust = [];
    this.billboards = [
      { x: 360, y: 228, w: 156, h: 210, text: "NEO KYOTO", color: "#ff3fce", speed: 0.31, vertical: true },
      { x: 1450, y: 190, w: 210, h: 120, text: "零 // ZERO", color: "#5df7ff", speed: 0.18, vertical: false },
      { x: 2400, y: 250, w: 120, h: 190, text: "RONIN", color: "#8a5cff", speed: 0.25, vertical: true },
    ];
    this.build();
    this.seedDynamic();
  }

  build() {
    const rng = mulberry32(0xC0FFEE);
    const make = (w, h) => {
      const c = document.createElement("canvas");
      c.width = w; c.height = h;
      return c;
    };

    // FAR SKYLINE ---------------------------------------------------------
    const far = make(2000, 720);
    let f = far.getContext("2d");
    f.fillStyle = "#070517";
    let x = -20;
    while (x < 2020) {
      const w = 32 + rng() * 95;
      const h = 90 + rng() * 230;
      const y = 720 - h;
      f.fillRect(x, y, w, h);
      if (rng() > 0.45) f.fillRect(x + w * 0.45, y - 20 - rng() * 50, 2, 50 + rng() * 30);
      if (rng() > 0.72) {
        f.fillRect(x + 4, y + 8, w - 8, 2);
        f.fillStyle = "rgba(128,88,190,0.16)";
        f.fillRect(x + 6, y + 10, w - 12, 2);
        f.fillStyle = "#070517";
      }
      x += w + 3 + rng() * 18;
    }
    // sparse windows
    for (let i = 0; i < 260; i++) {
      const wx = rng() * 2000, wy = 380 + rng() * 330;
      f.fillStyle = rng() > 0.5 ? "rgba(100,170,220,0.18)" : "rgba(220,80,180,0.12)";
      f.fillRect(wx, wy, 2, 2);
    }
    this.layers.push({ canvas: far, factor: 0.035, y: 0 });

    // MID SKYLINE ---------------------------------------------------------
    const mid = make(2400, 720);
    const m = mid.getContext("2d");
    x = -40;
    while (x < 2420) {
      const w = 76 + rng() * 150;
      const h = 150 + rng() * 300;
      const y = 720 - h;
      m.fillStyle = "#0a0820";
      m.fillRect(x, y, w, h);
      m.fillStyle = "#14102f";
      m.fillRect(x, y, w, 3);
      // rooftop structures
      if (rng() > 0.35) {
        const rw = w * (0.18 + rng() * 0.3);
        m.fillStyle = "#0a0820";
        m.fillRect(x + w * 0.2, y - 12 - rng() * 32, rw, 40);
      }
      if (rng() > 0.5) {
        m.fillStyle = "#0e0b26";
        m.fillRect(x + w * 0.6, y - 38 - rng() * 60, 2.5, 100);
        m.fillStyle = "rgba(255,62,98,0.7)";
        m.fillRect(x + w * 0.6 - 1, y - 40 - rng() * 0, 4.5, 2.5);
      }
      // vertical strip lights
      if (rng() > 0.55) {
        m.fillStyle = rng() > 0.5 ? "rgba(93,247,255,0.34)" : "rgba(255,63,206,0.28)";
        m.fillRect(x + 5, y + 12, 2, h * 0.5);
      }
      // windows
      const cols = Math.max(2, Math.floor(w / 18));
      const rows = Math.max(3, Math.floor(h / 26));
      for (let c = 0; c < cols; c++) {
        for (let r = 0; r < rows; r++) {
          if (rng() > 0.72) {
            const warm = rng();
            m.fillStyle = warm > 0.8 ? "rgba(255,195,107,0.55)" : warm > 0.45 ? "rgba(93,247,255,0.4)" : "rgba(255,63,206,0.32)";
            m.fillRect(x + 8 + c * ((w - 14) / cols), y + 12 + r * ((h - 20) / rows), 2, 3);
          }
        }
      }
      x += w + 8 + rng() * 26;
    }
    // big neon signs baked into mid layer
    const signs = [
      { x: 300, y: 470, text: "RAMEN", col: "#ff3fce", size: 20 },
      { x: 1120, y: 390, text: "NIGHT//CITY", col: "#5df7ff", size: 17 },
      { x: 1690, y: 510, text: "CYBER", col: "#ffc36b", size: 24 },
      { x: 2120, y: 430, text: "OPEN", col: "#ff3fce", size: 15 },
    ];
    for (const s of signs) {
      m.save();
      m.translate(s.x, s.y);
      m.font = `700 ${s.size}px "DejaVu Sans Mono", monospace`;
      m.fillStyle = "rgba(4,3,12,0.85)";
      m.fillRect(-6, -s.size, s.text.length * s.size * 0.62 + 12, s.size * 1.5);
      m.shadowColor = s.col;
      m.shadowBlur = 16;
      m.fillStyle = s.col;
      m.fillText(s.text, 0, 0);
      m.shadowBlur = 0;
      m.globalAlpha = 0.7;
      m.fillStyle = "#fff";
      m.fillText(s.text, 0, 0);
      m.restore();
    }
    this.layers.push({ canvas: mid, factor: 0.11, y: 0 });

    // NEAR SKYLINE --------------------------------------------------------
    const near = make(2600, 720);
    const n = near.getContext("2d");
    x = -60;
    while (x < 2620) {
      const w = 130 + rng() * 220;
      const h = 220 + rng() * 360;
      const y = 720 - h;
      n.fillStyle = "#060513";
      n.fillRect(x, y, w, h);
      n.strokeStyle = "rgba(90,70,150,0.08)";
      n.lineWidth = 1;
      n.strokeRect(x + 2, y + 2, w - 4, h);
      // ledges / fire escapes
      for (let k = 1; k < 5; k++) {
        const ly = y + (h / 5) * k;
        n.fillStyle = "rgba(8,7,20,0.95)";
        n.fillRect(x + w * 0.62, ly, w * 0.38, 4);
        n.fillStyle = "rgba(93,247,255,0.13)";
        n.fillRect(x + w * 0.62, ly, w * 0.38, 1);
      }
      // awning glow
      if (rng() > 0.4) {
        const ac = rng() > 0.5 ? "#ff3fce" : "#5df7ff";
        n.fillStyle = ac;
        n.globalAlpha = 0.25;
        n.fillRect(x + 10, y + h * 0.45, w * 0.3, 3);
        n.globalAlpha = 1;
      }
      // windows sparse
      for (let k = 0; k < 10; k++) {
        if (rng() > 0.76) {
          n.fillStyle = rng() > 0.5 ? "rgba(93,247,255,0.3)" : "rgba(255,195,107,0.26)";
          n.fillRect(x + 8 + rng() * (w - 16), y + 18 + rng() * (h - 40), 2.5, 3.5);
        }
      }
      x += w + 45 + rng() * 70;
    }
    this.layers.push({ canvas: near, factor: 0.25, y: 0 });

    // FOREGROUND SILHOUETTES (low, edges) --------------------------------
    const fg = make(1800, 720);
    const g = fg.getContext("2d");
    g.fillStyle = "#030208";
    x = -50;
    while (x < 1850) {
      const w = 100 + rng() * 190;
      const h = 120 + rng() * 180;
      g.fillRect(x, 720 - h, w, h);
      g.fillStyle = "rgba(4,3,10,0.9)";
      g.fillRect(x - 20, 720 - h + 30, w + 40, h);
      g.fillStyle = "#030208";
      x += w + 200 + rng() * 260;
    }
    this.layers.push({ canvas: fg, factor: 0.62, y: 0, alpha: 0.55 });
  }

  seedDynamic() {
    const rng = mulberry32(0xBEEF);
    for (let i = 0; i < 150; i++) {
      this.rain.push({
        x: rng() * VIEW_W, y: rng() * VIEW_H,
        len: 8 + rng() * 18, speed: 680 + rng() * 620, alpha: 0.06 + rng() * 0.2,
        layer: rng(),
      });
    }
    for (let i = 0; i < 90; i++) {
      this.stars.push({ x: rng() * 2400, y: rng() * 300, s: rng() * 1.4 + 0.3, p: rng() * TAU });
    }
    for (let i = 0; i < 5; i++) {
      this.cars.push({
        x: rng() * VIEW_W, y: 120 + rng() * 220, speed: 18 + rng() * 46,
        dir: rng() > 0.5 ? 1 : -1, size: 8 + rng() * 9, hue: rng() > 0.5 ? "#ff3fce" : "#5df7ff", trail: 0,
      });
    }
    for (let i = 0; i < 30; i++) {
      this.dust.push({
        x: rng() * VIEW_W, y: rng() * VIEW_H, s: rng() * 1.7 + 0.4,
        speed: 6 + rng() * 14, drift: rng() * 8 - 4, alpha: rng() * 0.22 + 0.05,
        color: rng() > 0.5 ? "#5df7ff" : "#ff3fce",
      });
    }
  }

  update(dt, cameraX) {
    this.time += dt;
    this.camera = cameraX;
    for (const d of this.rain) {
      d.y += d.speed * dt;
      d.x -= d.speed * 0.16 * dt;
      if (d.y > VIEW_H + 24) { d.y = -20; d.x = Math.random() * VIEW_W + 220; }
      if (d.x < -40) d.x += VIEW_W + 80;
    }
    for (const c of this.cars) {
      c.x += c.speed * c.dir * dt;
      if (c.x > VIEW_W + 160) c.x = -120;
      if (c.x < -160) c.x = VIEW_W + 120;
    }
    for (const d of this.dust) {
      d.y -= d.speed * dt;
      d.x += Math.sin(this.time * 0.3 + d.y * 0.01) * d.drift * dt;
      if (d.y < -20) { d.y = VIEW_H + 10; d.x = Math.random() * VIEW_W; }
    }
    this.nextLightning -= dt;
    if (this.nextLightning <= 0) {
      this.nextLightning = 9 + Math.random() * 14;
      this.flash = 0.55 + Math.random() * 0.35;
    }
    this.flash = Math.max(0, this.flash - dt * 2.2);
  }

  paletteFor(x) {
    const zi = Math.max(0, Math.min(ZONES.length - 1, ZONES.findIndex(z => x >= z.x0 && x < z.x1)));
    const i = zi === -1 ? ZONES.length - 1 : zi;
    const z = ZONES[i];
    const next = ZONES[Math.min(ZONES.length - 1, i + 1)];
    const blend = clamp((x - (z.x1 - 380)) / 380, 0, 1);
    const a = z.palette, b = next.palette;
    return {
      top: css(mixRgb(a.top, b.top, blend)),
      mid: css(mixRgb(a.mid, b.mid, blend)),
      glow: css(mixRgb(a.glow, b.glow, blend)),
      accent: css(mixRgb(a.accent, b.accent, blend)),
      haze: css(mixRgb(a.haze, b.haze, blend)),
      glowRaw: mixRgb(a.glow, b.glow, blend),
      accentRaw: mixRgb(a.accent, b.accent, blend),
    };
  }

  draw(ctx, cameraX, menu = false) {
    const pal = this.paletteFor(menu ? 420 : cameraX);
    const W = VIEW_W, H = VIEW_H;
    // sky
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    sky.addColorStop(0, pal.top);
    sky.addColorStop(0.48, pal.mid);
    sky.addColorStop(0.78, pal.haze);
    sky.addColorStop(1, "#05030d");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, H);

    // horizon glow
    const hg = ctx.createRadialGradient(W * 0.56, H * 0.7, 20, W * 0.56, H * 0.7, W * 0.7);
    hg.addColorStop(0, `rgba(${pal.glowRaw.r},${pal.glowRaw.g},${pal.glowRaw.b},0.22)`);
    hg.addColorStop(0.4, `rgba(${pal.glowRaw.r},${pal.glowRaw.g},${pal.glowRaw.b},0.07)`);
    hg.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = hg;
    ctx.fillRect(0, 0, W, H);

    // stars
    ctx.save();
    const starOff = (cameraX * 0.015) % 2400;
    for (const s of this.stars) {
      let sx = s.x - starOff;
      if (sx < -10) sx += 2400;
      const tw = 0.45 + 0.55 * Math.abs(Math.sin(this.time * 0.8 + s.p));
      ctx.globalAlpha = tw * 0.8;
      ctx.fillStyle = "#d9fbff";
      ctx.fillRect(sx, s.y, s.s, s.s);
    }
    ctx.restore();

    // moon / ringed planet
    const moonX = 1010 - (cameraX * 0.012 % 600);
    const moonY = 136;
    ctx.save();
    const halo = ctx.createRadialGradient(moonX, moonY, 10, moonX, moonY, 190);
    halo.addColorStop(0, "rgba(255,150,220,0.22)");
    halo.addColorStop(0.35, "rgba(150,120,255,0.10)");
    halo.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(moonX, moonY, 190, 0, TAU); ctx.fill();
    ctx.translate(moonX, moonY);
    ctx.rotate(-0.22);
    ctx.strokeStyle = "rgba(191,154,255,0.25)";
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(0, 0, 130, 28, 0, 0, TAU); ctx.stroke();
    ctx.strokeStyle = "rgba(255,114,210,0.18)";
    ctx.beginPath(); ctx.ellipse(0, 0, 150, 34, 0, 0, TAU); ctx.stroke();
    const body = ctx.createLinearGradient(-44, -44, 44, 44);
    body.addColorStop(0, "#f4d9ff");
    body.addColorStop(0.4, "#c48de0");
    body.addColorStop(0.7, "#6b4c99");
    body.addColorStop(1, "#26173f");
    ctx.fillStyle = body;
    ctx.beginPath(); ctx.arc(0, 0, 53, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.2;
    ctx.fillStyle = "#2b1748";
    for (let i = 0; i < 6; i++) {
      ctx.beginPath();
      ctx.arc(Math.sin(i * 2.1) * 26, Math.cos(i * 1.7) * 22, 5 + (i % 3) * 4, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // parallax skyline layers
    for (const layer of this.layers) {
      const lw = layer.canvas.width;
      const offset = ((cameraX * layer.factor) % lw + lw) % lw;
      ctx.save();
      ctx.globalAlpha = layer.alpha ?? 1;
      for (let i = -1; i < Math.ceil(W / lw) + 1; i++) {
        ctx.drawImage(layer.canvas, Math.round(-offset + i * lw), layer.y);
      }
      if (layer.factor < 0.3) {
        ctx.globalCompositeOperation = "screen";
        ctx.globalAlpha = 0.06;
        ctx.fillStyle = pal.glow;
        ctx.fillRect(0, 0, W, H);
      }
      ctx.restore();
    }

    // holographic billboards
    for (const b of this.billboards) {
      let bx = b.x - ((cameraX * b.speed + this.time * 7) % 2900);
      if (bx < -300) bx += 2900;
      bx = ((bx + 300) % 2900) - 300;
      if (bx > W + 260) continue;
      this.drawBillboard(ctx, bx, b);
    }

    // flying cars
    for (const c of this.cars) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      const grad = ctx.createLinearGradient(c.x - c.dir * 90, c.y, c.x, c.y);
      grad.addColorStop(0, "rgba(0,0,0,0)");
      grad.addColorStop(1, c.hue === "#ff3fce" ? "rgba(255,63,206,0.32)" : "rgba(93,247,255,0.32)");
      ctx.fillStyle = grad;
      ctx.fillRect(c.x - (c.dir > 0 ? 90 : -10), c.y - 1, 90, 2);
      ctx.shadowBlur = 14;
      ctx.shadowColor = c.hue;
      ctx.fillStyle = c.hue;
      ctx.fillRect(c.x - c.size / 2, c.y - 2, c.size, 2.5);
      ctx.fillStyle = "#fff";
      ctx.fillRect(c.x + c.dir * (c.size / 2) - 1, c.y - 1.5, 2, 1.5);
      ctx.restore();
    }

    // lightning flash
    if (this.flash > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.globalAlpha = this.flash * 0.22;
      ctx.fillStyle = "#cfeaff";
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }

    // low fog bands
    ctx.save();
    const fog = ctx.createLinearGradient(0, 500, 0, 720);
    fog.addColorStop(0, "rgba(20,12,40,0)");
    fog.addColorStop(0.6, "rgba(20,12,40,0.32)");
    fog.addColorStop(1, "rgba(8,5,18,0.6)");
    ctx.fillStyle = fog;
    ctx.fillRect(0, 470, W, 250);
    ctx.restore();

    // floating embers
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const d of this.dust) {
      ctx.globalAlpha = d.alpha * (0.6 + 0.4 * Math.sin(this.time + d.y));
      ctx.fillStyle = d.color;
      ctx.beginPath(); ctx.arc(d.x, d.y, d.s, 0, TAU); ctx.fill();
    }
    ctx.restore();

    // rain
    ctx.save();
    ctx.lineCap = "round";
    for (const d of this.rain) {
      ctx.globalAlpha = d.alpha;
      ctx.strokeStyle = d.layer > 0.7 ? "#b9d9ff" : "#6f9bb8";
      ctx.lineWidth = d.layer > 0.7 ? 1.15 : 0.7;
      ctx.beginPath();
      ctx.moveTo(d.x, d.y);
      ctx.lineTo(d.x - d.len * 0.18, d.y + d.len);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawBillboard(ctx, x, b) {
    const glitch = Math.sin(this.time * 2.1 + b.x) > 0.96 ? 5 : 0;
    ctx.save();
    ctx.translate(x, b.y);
    ctx.globalAlpha = 0.82;
    // frame
    ctx.fillStyle = "rgba(5,4,15,0.55)";
    ctx.fillRect(-b.w / 2, -b.h / 2, b.w, b.h);
    ctx.strokeStyle = "rgba(93,247,255,0.16)";
    ctx.strokeRect(-b.w / 2, -b.h / 2, b.w, b.h);
    // scanlines
    ctx.globalAlpha = 0.09;
    ctx.fillStyle = b.color;
    for (let y = -b.h / 2 + 4; y < b.h / 2; y += 5) ctx.fillRect(-b.w / 2 + 4, y, b.w - 8, 1);
    ctx.globalAlpha = 0.85;
    ctx.shadowColor = b.color;
    ctx.shadowBlur = 15;
    ctx.fillStyle = b.color;
    if (b.vertical) {
      ctx.translate(-b.w / 2 + 28, -b.h / 2 + 22);
      ctx.font = '700 19px "DejaVu Sans Mono", monospace';
      const chars = b.text.split("");
      for (let i = 0; i < chars.length; i++) ctx.fillText(chars[i], (i % 2) * 14 + (i === 0 ? glitch : 0), i * 23);
    } else {
      ctx.textAlign = "center";
      ctx.font = '700 22px "DejaVu Sans Mono", monospace';
      ctx.fillText(b.text, glitch, 4);
      ctx.globalAlpha = 0.5;
      ctx.font = '400 8px "DejaVu Sans Mono", monospace';
      ctx.fillText("SIGNAL // ACTIVE", 0, 26);
    }
    ctx.restore();
  }
}

function makePlatform(x, y, w, h = 14, opts = {}) {
  return {
    x, y, w, h, baseX: x, baseY: y,
    type: opts.type ?? (h > 40 ? "ground" : "platform"),
    oneWay: opts.oneWay ?? h <= 20,
    moving: opts.moving ?? null,
    dx: 0, dy: 0,
    id: opts.id ?? Math.random().toString(36).slice(2),
  };
}

export class World {
  constructor() {
    this.time = 0;
    this.groundY = GROUND_Y;
    this.width = WORLD_W;
    this.respawn = { x: 150, y: GROUND_Y - 64 };
    this.platforms = [];
    this.hazards = [];
    this.orbs = [];
    this.checkpoints = [];
    this.enemies = [];
    this.arena = { x0: 10490, x1: 12160, trigger: 10580, center: 11325, active: false };
    this.gateOpen = false;
    this.build();
  }

  build() {
    // ground segments (safe concrete)
    const groundSegs = [
      [0, 1500], [1680, 3260], [3420, 5320], [5500, 7480], [7650, 10480], [10640, 12200],
    ];
    for (const [x0, x1] of groundSegs) {
      this.platforms.push(makePlatform(x0, GROUND_Y, x1 - x0, 140, { type: "ground" }));
    }
    // floating platforms
    const ps = [
      [520, 500, 180], [760, 410, 150], [1040, 500, 190],
      [1720, 495, 200], [2000, 400, 160], [2260, 510, 170], [2600, 430, 200],
      [3350, 500, 160], [3620, 410, 180], [3970, 500, 160], [4350, 440, 220],
      [4720, 340, 180], [5000, 470, 200],
      [5600, 500, 180], [5880, 400, 150],
      [6250, 480, 170], [6510, 380, 150], [6850, 500, 200], [7180, 420, 160],
