      [10720, 500, 170], [11250, 450, 220], [11780, 500, 170],
    ];
    for (const [x, y, w] of ps) this.platforms.push(makePlatform(x, y, w, 14));
    // moving platforms
    this.platforms.push(makePlatform(5310, 525, 140, 14, {
      moving: { axis: "x", dist: 55, speed: 1.05, phase: 0 }, id: "mover1",
    }));
    this.platforms.push(makePlatform(6980, 460, 150, 14, {
      moving: { axis: "y", dist: 72, speed: 1.15, phase: 1.2 }, id: "mover2",
    }));

    this.hazards = [
      { type: "laser", x: 5650, y: 594, w: 120, h: 24, period: 2.3, onTime: 1.05, offset: 0.2, damage: 16 },
      { type: "laser", x: 8990, y: 594, w: 130, h: 24, period: 2.7, onTime: 1.15, offset: 1.5, damage: 18 },
      { type: "laser", x: 10920, y: 594, w: 100, h: 24, period: 3.2, onTime: 1.3, offset: 0.8, damage: 18 },
    ];

    // checkpoints
    this.checkpoints = [
      { id: 0, x: 2800, y: GROUND_Y, active: false },
      { id: 1, x: 6160, y: GROUND_Y, active: false },
      { id: 2, x: 8050, y: GROUND_Y, active: false },
      { id: 3, x: 9800, y: GROUND_Y, active: false },
      { id: 4, x: 10430, y: GROUND_Y, active: false },
    ];

    // collectible orbs (first wave + platform rewards + arena)
    const orbPositions = [
      [420, 555], [560, 452], [800, 362], [1080, 452], [1230, 555],
      [1760, 555], [2060, 352], [2320, 462], [2660, 382], [3010, 555],
      [3400, 555], [3680, 362], [4020, 452], [4460, 392], [4780, 292],
      [5060, 422], [5640, 452], [5940, 352],
      [6350, 555], [6560, 332], [6910, 452], [7240, 372], [7560, 282],
      [7870, 422], [8300, 452], [8600, 352], [8910, 452], [9210, 372], [9510, 292],
      [9880, 555], [10290, 555], [10830, 555], [11350, 402], [11830, 555],
    ];
    this.orbs = orbPositions.map(([x, y], i) => ({ x, y, r: 10, collected: false, phase: i * 0.7 }));
    this.orbTotal = this.orbs.length;

    // enemy roster
    this.enemies = [
      { type: "drone", x: 900, y: 315, zone: 0 },
      { type: "melee", x: 1270, y: GROUND_Y, zone: 0 },
      { type: "drone", x: 1940, y: 305, zone: 0 },
      { type: "melee", x: 2290, y: GROUND_Y, zone: 0 },
      { type: "gunner", x: 2670, y: 430, zone: 0 },
      { type: "melee", x: 3380, y: GROUND_Y, zone: 1 },
      { type: "drone", x: 3720, y: 300, zone: 1 },
      { type: "gunner", x: 4050, y: GROUND_Y, zone: 1 },
      { type: "melee", x: 4520, y: GROUND_Y, zone: 1 },
      { type: "drone", x: 4830, y: 300, zone: 1 },
      { type: "gunner", x: 5180, y: GROUND_Y, zone: 1 },
      { type: "melee", x: 5730, y: GROUND_Y, zone: 1 },
      { type: "melee", x: 6320, y: GROUND_Y, zone: 2 },
      { type: "drone", x: 6650, y: 290, zone: 2 },
      { type: "gunner", x: 6960, y: GROUND_Y, zone: 2 },
      { type: "melee", x: 7370, y: 420, zone: 2 },
      { type: "drone", x: 7720, y: 280, zone: 2 },
      { type: "gunner", x: 7990, y: GROUND_Y, zone: 2 },
      { type: "melee", x: 8400, y: GROUND_Y, zone: 2 },
      { type: "drone", x: 8720, y: 290, zone: 2 },
      { type: "gunner", x: 9020, y: GROUND_Y, zone: 2 },
      { type: "melee", x: 9340, y: GROUND_Y, zone: 2 },
      { type: "drone", x: 9660, y: 300, zone: 2 },
      { type: "melee", x: 9970, y: GROUND_Y, zone: 2, elite: true },
    ];
  }

  getZone(x) {
    if (x >= this.arena.x0) return ZONES[3];
    for (let i = ZONES.length - 1; i >= 0; i--) if (x >= ZONES[i].x0) return ZONES[i];
    return ZONES[0];
  }

  checkpointAt(x) {
    for (const cp of this.checkpoints) {
      if (!cp.active && Math.abs(x - cp.x) < 70) return cp;
    }
    return null;
  }

  activateCheckpoint(cp) {
    cp.active = true;
    this.respawn = { x: cp.x - 30, y: GROUND_Y - 64 };
  }

  update(dt) {
    this.time += dt;
    for (const p of this.platforms) {
      p.dx = 0; p.dy = 0;
      if (p.moving) {
        const oldX = p.x, oldY = p.y;
        const t = this.time * p.moving.speed + p.moving.phase;
        if (p.moving.axis === "x") p.x = p.baseX + Math.sin(t) * p.moving.dist;
        else p.y = p.baseY + Math.sin(t) * p.moving.dist;
        p.dx = p.x - oldX;
        p.dy = p.y - oldY;
      }
    }
  }

  hazardActive(h) {
    const t = (this.time + h.offset) % h.period;
    return t < h.onTime;
  }

  drawSkylineAccents(ctx, cameraX) {
    // giant faint glyph wall in the last sector
    const wx = 11000 - cameraX;
    if (wx > -400 && wx < VIEW_W + 400) {
      ctx.save();
      ctx.globalAlpha = 0.07;
      ctx.fillStyle = "#ff3e62";
      ctx.font = '900 300px "DejaVu Sans", sans-serif';
      ctx.textAlign = "center";
      ctx.fillText("零", wx + 300, 520);
      ctx.restore();
    }
  }
}

// -------------------------------------------------------------------------
// Platform / environment rendering helpers
// -------------------------------------------------------------------------
const groundCache = new Map();

function getSurfacePattern(ctx, p, palette) {
  const key = `${p.id}-${p.w}`;
  if (groundCache.has(key)) return groundCache.get(key);
  const c = document.createElement("canvas");
  const scale = 1;
  c.width = Math.max(1, Math.ceil(p.w * scale));
  c.height = p.type === "ground" ? 140 : p.h;
  const g = c.getContext("2d");
  const rng = mulberry32(p.w * 17 + p.x * 3 + 11);
  if (p.type === "ground") {
    const grd = g.createLinearGradient(0, 0, 0, c.height);
    grd.addColorStop(0, "#141527");
    grd.addColorStop(0.12, "#0c0c1b");
    grd.addColorStop(1, "#05040d");
    g.fillStyle = grd;
    g.fillRect(0, 0, c.width, c.height);
    // panel seams
    g.strokeStyle = "rgba(93,247,255,0.06)";
    g.lineWidth = 1;
    const step = 86;
    for (let x = 0; x < c.width; x += step) {
      g.beginPath(); g.moveTo(x, 4); g.lineTo(x - 8, c.height); g.stroke();
    }
    for (let y = 35; y < c.height; y += 42) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(c.width, y); g.stroke();
    }
    // random tech grates
    for (let i = 0; i < Math.floor(c.width / 90); i++) {
      const gx = rng() * (c.width - 40), gy = 44 + rng() * 62;
      g.fillStyle = "rgba(2,3,8,0.7)";
      g.fillRect(gx, gy, 28 + rng() * 40, 9);
      g.fillStyle = "rgba(93,247,255,0.07)";
      for (let k = 0; k < 5; k++) g.fillRect(gx + 3 + k * 6, gy + 2, 2, 5);
    }
    // puddles / reflections
    for (let i = 0; i < Math.floor(c.width / 300); i++) {
      const px = rng() * c.width;
      const grad = g.createLinearGradient(px, 26, px, 100);
      grad.addColorStop(0, "rgba(255,63,206,0.10)");
      grad.addColorStop(1, "rgba(93,247,255,0)");
      g.fillStyle = grad;
      g.beginPath();
      g.ellipse(px, 34, 30 + rng() * 40, 4, 0, 0, TAU);
      g.fill();
    }
  }
  groundCache.set(key, c);
  return c;
}

export function drawPlatform(ctx, p, time, palette) {
  if (p.type === "ground") {
    const pattern = getSurfacePattern(ctx, p, palette);
    ctx.drawImage(pattern, p.x, p.y);
    // top neon trim
    const trim = palette.glow;
    ctx.save();
    ctx.shadowColor = trim;
    ctx.shadowBlur = 16;
    ctx.fillStyle = trim;
    ctx.globalAlpha = 0.85;
    ctx.fillRect(p.x, p.y - 2, p.w, 2);
    ctx.globalAlpha = 0.25;
    ctx.fillRect(p.x, p.y + 1, p.w, 5);
    ctx.restore();
    // edge caps
    ctx.fillStyle = "#0a0917";
    ctx.fillRect(p.x - 6, p.y, 6, 30);
    ctx.fillRect(p.x + p.w, p.y, 6, 30);
    ctx.strokeStyle = "rgba(93,247,255,0.22)";
    ctx.beginPath();
    ctx.moveTo(p.x - 6, p.y); ctx.lineTo(p.x - 6, p.y + 30);
    ctx.moveTo(p.x + p.w + 6, p.y); ctx.lineTo(p.x + p.w + 6, p.y + 30);
    ctx.stroke();
  } else {
    // floating platform
    ctx.save();
    ctx.translate(p.x, p.y);
    const h = Math.max(14, p.h);
    const grd = ctx.createLinearGradient(0, 0, 0, h + 22);
    grd.addColorStop(0, "#1a1b33");
    grd.addColorStop(0.5, "#0d0d1d");
    grd.addColorStop(1, "#05040c");
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, p.w, h + 14);
    // angled underside
    ctx.fillStyle = "#07060f";
    ctx.beginPath();
    ctx.moveTo(8, h + 14);
    ctx.lineTo(p.w - 8, h + 14);
    ctx.lineTo(p.w - 34, h + 32);
    ctx.lineTo(34, h + 32);
    ctx.closePath();
    ctx.fill();
    // top edge
    ctx.shadowColor = palette.accent;
    ctx.shadowBlur = 12;
    ctx.fillStyle = palette.accent;
    ctx.globalAlpha = 0.8;
    ctx.fillRect(0, 0, p.w, 1.5);
    ctx.globalAlpha = 0.2;
    ctx.fillRect(0, 2, p.w, 3);
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;
    // panel details
    ctx.strokeStyle = "rgba(93,247,255,0.12)";
    ctx.beginPath();
    ctx.moveTo(12, 5); ctx.lineTo(p.w - 12, 5);
    ctx.stroke();
    const lights = Math.max(2, Math.floor(p.w / 55));
    for (let i = 0; i < lights; i++) {
      const lx = 20 + i * ((p.w - 40) / Math.max(1, lights - 1));
      const glow = 0.35 + 0.25 * Math.sin(time * 2 + i * 1.7 + p.x);
      ctx.fillStyle = i % 3 === 0 ? "#ff3fce" : palette.accent;
      ctx.globalAlpha = glow;
      ctx.fillRect(lx, h + 5, 3, 2);
    }
    // side brackets
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#101126";
    ctx.fillRect(-3, 3, 4, h + 10);
    ctx.fillRect(p.w - 1, 3, 4, h + 10);
    ctx.restore();
  }
}

export function drawHazard(ctx, h, active, time) {
  ctx.save();
  ctx.translate(h.x, h.y);
  // emitter posts
  ctx.fillStyle = "#0e0b1a";
  ctx.fillRect(-10, -3, 10, h.h + 6);
  ctx.fillRect(h.w, -3, 10, h.h + 6);
  ctx.strokeStyle = "rgba(255,62,98,0.4)";
  ctx.strokeRect(-10, -3, 10, h.h + 6);
  ctx.strokeRect(h.w, -3, 10, h.h + 6);
  ctx.fillStyle = "#ff3e62";
  ctx.globalAlpha = 0.5 + 0.5 * Math.sin(time * 8);
  ctx.fillRect(-8, h.h / 2 - 2, 3, 4);
  ctx.fillRect(h.w + 5, h.h / 2 - 2, 3, 4);
  ctx.globalAlpha = 1;
  if (active) {
    ctx.globalCompositeOperation = "lighter";
    ctx.shadowColor = "#ff3e62";
    ctx.shadowBlur = 22;
    const g = ctx.createLinearGradient(0, 0, 0, h.h);
    g.addColorStop(0, "rgba(255,80,110,0.1)");
    g.addColorStop(0.3, "rgba(255,80,110,0.85)");
    g.addColorStop(0.5, "rgba(255,255,255,0.95)");
    g.addColorStop(0.7, "rgba(255,80,110,0.85)");
    g.addColorStop(1, "rgba(255,80,110,0.1)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, h.w, h.h);
    ctx.fillStyle = "rgba(255,130,150,0.3)";
    ctx.fillRect(-4, h.h / 2 - 1, h.w + 8, 2);
    ctx.globalCompositeOperation = "source-over";
  } else {
    ctx.strokeStyle = "rgba(255,62,98,0.35)";
    ctx.setLineDash([3, 7]);
    ctx.beginPath();
    ctx.moveTo(0, h.h / 2); ctx.lineTo(h.w, h.h / 2);
    ctx.stroke();
    ctx.setLineDash([]);
    // warning chevrons
    ctx.globalAlpha = 0.3 + 0.1 * Math.sin(time * 5);
    ctx.fillStyle = "#ff3e62";
    for (let x = 8; x < h.w; x += 24) {
      ctx.beginPath();
      ctx.moveTo(x, h.h / 2 - 7);
      ctx.lineTo(x + 8, h.h / 2);
      ctx.lineTo(x, h.h / 2 + 7);
      ctx.strokeStyle = "#ff3e62";
      ctx.stroke();
    }
  }
  ctx.restore();
}

export function drawOrb(ctx, orb, time) {
  if (orb.collected) return;
  const bob = Math.sin(time * 2.4 + orb.phase) * 7;
  const x = orb.x, y = orb.y + bob;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  const g = ctx.createRadialGradient(x, y, 0, x, y, 38);
  g.addColorStop(0, "rgba(190,255,255,0.55)");
  g.addColorStop(0.3, "rgba(93,247,255,0.22)");
  g.addColorStop(1, "rgba(93,247,255,0)");
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, 38, 0, TAU); ctx.fill();
  ctx.translate(x, y);
  ctx.rotate(time * 1.2 + orb.phase);
  ctx.shadowColor = "#5df7ff";
  ctx.shadowBlur = 14;
  ctx.strokeStyle = "rgba(205,255,255,0.9)";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(0, -11); ctx.lineTo(6, 0); ctx.lineTo(0, 11); ctx.lineTo(-6, 0); ctx.closePath();
  ctx.stroke();
  ctx.fillStyle = "#d9ffff";
  ctx.beginPath();
  ctx.moveTo(0, -6); ctx.lineTo(3.5, 0); ctx.lineTo(0, 6); ctx.lineTo(-3.5, 0); ctx.closePath();
  ctx.fill();
  ctx.restore();
}

export function drawCheckpoint(ctx, cp, time) {
  const x = cp.x, y = cp.y;
  ctx.save();
  ctx.translate(x, y);
  // base
  ctx.fillStyle = "#0b0a18";
  ctx.fillRect(-18, -8, 36, 8);
  ctx.strokeStyle = cp.active ? "rgba(93,247,255,0.5)" : "rgba(120,120,150,0.25)";
  ctx.strokeRect(-18, -8, 36, 8);
  // beam
  if (cp.active) {
    ctx.globalCompositeOperation = "lighter";
    const g = ctx.createLinearGradient(0, -260, 0, 0);
    g.addColorStop(0, "rgba(93,247,255,0)");
    g.addColorStop(0.7, "rgba(93,247,255,0.05)");
    g.addColorStop(1, "rgba(93,247,255,0.22)");
    ctx.fillStyle = g;
    ctx.fillRect(-18, -260, 36, 260);
    ctx.globalCompositeOperation = "source-over";
  }
  // diamond
  const bob = Math.sin(time * 2 + cp.id) * 4;
  ctx.translate(0, -58 + bob);
  ctx.rotate(time * 0.7);
  ctx.strokeStyle = cp.active ? "#5df7ff" : "#4a4a63";
  ctx.fillStyle = cp.active ? "rgba(93,247,255,0.18)" : "rgba(30,30,45,0.4)";
  ctx.lineWidth = 1.5;
  ctx.shadowColor = cp.active ? "#5df7ff" : "transparent";
  ctx.shadowBlur = cp.active ? 18 : 0;
  ctx.beginPath();
  ctx.moveTo(0, -17); ctx.lineTo(12, 0); ctx.lineTo(0, 17); ctx.lineTo(-12, 0); ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.rotate(-time * 0.7);
  ctx.fillStyle = cp.active ? "#eaffff" : "#77778f";
  ctx.fillRect(-2, -6, 4, 12);
  ctx.fillRect(-6, -2, 12, 4);
  ctx.restore();
  // label
  ctx.save();
  ctx.translate(x, y);
  ctx.textAlign = "center";
  ctx.font = '700 8px "DejaVu Sans Mono", monospace';
  ctx.fillStyle = cp.active ? "rgba(93,247,255,0.8)" : "rgba(120,120,150,0.4)";
  ctx.fillText(cp.active ? "LINK STABLE" : "CHECKPOINT", 0, -142);
  ctx.restore();
}

export function drawArenaGate(ctx, x, time, open) {
  ctx.save();
  ctx.translate(x, 0);
  const h = 360;
  // pillars
  ctx.fillStyle = "#090714";
  ctx.fillRect(-34, GROUND_Y - h, 30, h);
  ctx.fillRect(4, GROUND_Y - h, 30, h);
  ctx.strokeStyle = "rgba(255,62,98,0.35)";
  ctx.strokeRect(-34, GROUND_Y - h, 30, h);
  ctx.strokeRect(4, GROUND_Y - h, 30, h);
  if (!open) {
    ctx.globalCompositeOperation = "lighter";
    const g = ctx.createLinearGradient(0, GROUND_Y - h, 0, GROUND_Y);
    g.addColorStop(0, "rgba(255,62,98,0.03)");
    g.addColorStop(0.5, "rgba(255,62,98,0.22)");
    g.addColorStop(1, "rgba(255,62,98,0.08)");
    ctx.fillStyle = g;
    ctx.fillRect(-4, GROUND_Y - h, 8, h);
    ctx.fillStyle = "rgba(255,120,140,0.5)";
    for (let y = GROUND_Y - h + 20; y < GROUND_Y; y += 34) {
      ctx.fillRect(-3, y + Math.sin(time * 3 + y) * 2, 6, 14);
    }
    ctx.globalCompositeOperation = "source-over";
  }
  ctx.textAlign = "center";
  ctx.font = '700 9px "DejaVu Sans Mono", monospace';
  ctx.fillStyle = "rgba(255,62,98,0.65)";
  ctx.fillText(open ? "LOCKDOWN" : "SEALED // BOSS", 0, GROUND_Y - h - 14);
  ctx.restore();
}

import { TAU, clamp, approach, lerp, rand, rectsOverlap } from "./util.js";

const GRAVITY = 2050;
const MAX_FALL = 1120;
const RUN_MAX = 385;
const ACCEL = 2850;
const AIR_ACCEL = 1800;
const FRICTION = 3100;
const JUMP_FORCE = 740;
const DOUBLE_JUMP_FORCE = 680;

export class Player {
  constructor(x, y) {
    this.w = 34;
    this.h = 62;
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.facing = 1;
    this.grounded = false;
    this.groundPlatform = null;
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.jumps = 0;
    this.jumpCut = false;
    this.maxHealth = 100;
    this.health = 100;
    this.maxEnergy = 100;
    this.energy = 100;
    this.energyDelay = 0;
    this.invuln = 0;
    this.hurtTimer = 0;
    this.dashTime = 0;
    this.dashCooldown = 0;
    this.airDash = true;
    this.dashStrike = false;
    this.dashStrikeTimer = 0;
    this.dashStrikeHit = false;
    this.attack = null;
    this.attackQueued = false;
    this.attackIndex = 0;
    this.comboTimer = 0;
    this.hitSet = new Set();
    this.slashes = [];
    this.afterimages = [];
    this.time = 0;
    this.runPhase = 0;
    this.alive = true;
    this.deathTimer = 0;
    this.scarf = [];
    for (let i = 0; i < 7; i++) this.scarf.push({ x: this.x + 10, y: this.y + 12, px: this.x + 10, py: this.y + 12 });
    this.stepTimer = 0;
    this.hitFlash = 0;
    this.parryWindow = 0;
    this.idleTime = 0;
    this.shadowY = y + h;
  }

  get cx() { return this.x + this.w / 2; }
  get cy() { return this.y + this.h / 2; }
  get footY() { return this.y + this.h; }

  respawn(x, y) {
    this.x = x; this.y = y;
    this.vx = 0; this.vy = 0;
    this.health = this.maxHealth;
    this.energy = this.maxEnergy;
    this.invuln = 1.2;
    this.hurtTimer = 0; this.dashTime = 0; this.dashCooldown = 0;
    this.attack = null; this.attackQueued = false;
    this.grounded = false; this.jumps = 0; this.alive = true;
    this.afterimages.length = 0;
    this.slashes.length = 0;
  }

  addEnergy(v) {
    this.energy = clamp(this.energy + v, 0, this.maxEnergy);
    this.energyDelay = Math.max(this.energyDelay, 0.45);
  }

  heal(v) {
    this.health = clamp(this.health + v, 0, this.maxHealth);
  }

  update(dt, world, input, game) {
    this.time += dt;
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.dashCooldown = Math.max(0, this.dashCooldown - dt);
    this.attackQueued = false;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
    this.rare = 0;
    if (!this.alive) {
      this.deathTimer += dt;
      this.vx = approach(this.vx, 0, 700 * dt);
      this.x += this.vx * dt;
      this.vy = Math.min(MAX_FALL, this.vy + GRAVITY * dt);
      this.y += this.vy * dt;
      this.updateCosmetics(dt, game);
      return;
    }

    // carried by a moving platform
    if (this.groundPlatform && this.grounded) {
      this.x += this.groundPlatform.dx;
      this.y += this.groundPlatform.dy;
    }

    const axis = input.axis;
    const wasGrounded = this.grounded;
    const aliveTime = dt;

    // energy regeneration
    this.energyDelay = Math.max(0, this.energyDelay - dt);
    if (this.energyDelay <= 0 && this.dashTime <= 0) {
      this.energy = Math.min(this.maxEnergy, this.energy + 11 * dt);
    }

    // timers
    this.coyote = Math.max(0, this.coyote - dt);
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
    this.dashStrikeTimer = Math.max(0, this.dashStrikeTimer - dt);
    if (this.dashStrikeTimer <= 0) this.dashStrike = false;

    // jump input
    if (input.consume("jump")) {
      this.jumpBuffer = 0.125;
    }
    if (input.consume("attack")) {
      if (this.dashTime > 0 || this.dashStrikeTimer > 0) {
        this.beginDashStrike(game);
      } else if (this.attack) {
        if (this.attack.t > this.attack.dur * 0.26) this.attackQueued = true;
      } else {
        this.startAttack(game);
      }
    }
    if (input.consume("dash")) {
      if (this.dashTime <= 0 && this.dashCooldown <= 0 && this.energy >= 20 && (this.grounded || this.airDash)) {
        this.startDash(axis, game);
      }
    }

    // dash strike during dash
    if (this.dashStrike && this.dashTime > 0) {
      // already launched
    }

    // horizontal movement
    if (this.hurtTimer > 0.08) {
      this.vx = approach(this.vx, 0, 900 * dt);
    } else if (this.dashTime > 0) {
      this.vx = this.facing * 1120;
      this.vy = 0;
      this.dashTime -= dt;
      this.airDash = this.grounded ? this.airDash : false;
      if (Math.random() < dt * 70) {
        this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: 0.22, max: 0.22 });
      }
      if (this.dashTime <= 0) {
        this.vx = this.facing * 410;
        this.dashCooldown = 0.16;
      }
    } else {
      if (axis !== 0) {
        const accel = this.grounded ? ACCEL : AIR_ACCEL;
        this.vx = approach(this.vx, axis * RUN_MAX, accel * dt);
        this.facing = axis > 0 ? 1 : -1;
      } else {
        this.vx = approach(this.vx, 0, (this.grounded ? FRICTION : 700) * dt);
      }
      if (this.attack) this.vx *= Math.pow(0.012, dt);
    }

    // variable-height jump
    if (!input.jumpHeld && this.vy < -270 && !this.jumpCut && this.dashTime <= 0) {
      this.vy *= 0.52;
      this.jumpCut = true;
    }

    // jumping
    if (this.jumpBuffer > 0) {
      if (this.grounded || this.coyote > 0) {
        this.vy = -JUMP_FORCE;
        this.grounded = false;
        this.groundPlatform = null;
        this.coyote = 0;
        this.jumpBuffer = 0;
        this.jumps = 1;
        this.jumpCut = false;
        this.energyDelay = Math.max(this.energyDelay, 0.25);
        game?.audio?.play("jump");
        game?.particles?.dust(this.cx, this.footY, "#5df7ff", 6, 90);
      } else if (this.jumps < 2) {
        this.vy = -DOUBLE_JUMP_FORCE;
        this.jumps = 2;
        this.jumpBuffer = 0;
        this.jumpCut = false;
        this.energyDelay = Math.max(this.energyDelay, 0.3);
        game?.audio?.play("doubleJump");
        game?.particles?.ring(this.cx, this.cy + 14, "#5df7ff", 32, 0.28, 2);
        game?.particles?.spark(this.cx, this.cy + 14, "#bffcff", 10, 180);
      }
    }

    // gravity
    if (this.dashTime <= 0) {
      this.vy = Math.min(MAX_FALL, this.vy + GRAVITY * dt);
    }

    // attack state
    if (this.attack) {
      this.attack.t += dt;
      if (this.attack.t >= this.attack.dur) {
        if (this.attackQueued) {
          const next = (this.attack.index + 1) % 3;
          this.startAttack(game, next);
        } else {
          this.attack = null;
          this.comboTimer = 0.55;
        }
      }
    } else {
      this.comboTimer = Math.max(0, this.comboTimer - dt);
      if (this.comboTimer <= 0) this.attackIndex = 0;
    }

    this.comboTimer = Math.max(0, this.comboTimer - dt);

    // integrate
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.collide(world, wasGrounded, game, input);

    // world bounds
    if (this.x < 8) { this.x = 8; this.vx = 0; }
    const maxX = world.arena.active ? world.arena.x1 - this.w - 8 : world.width - this.w - 8;
    if (this.x > maxX) { this.x = maxX; this.vx = Math.min(0, this.vx); }

    // footsteps
    if (this.grounded && Math.abs(this.vx) > 90 && this.dashTime <= 0) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.16 - Math.min(0.08, Math.abs(this.vx) / 8000);
        game?.particles?.dust(this.cx + rand(-5, 5), this.footY, "#78c7d8", 2, 38);
        game?.audio?.play("land");
      }
    }

    if (this.grounded) {
      this.jumps = 0;
      this.airDash = true;
      this.coyote = 0.1;
      if (!wasGrounded && this.vy > 240) {
        game?.particles?.dust(this.cx, this.footY, "#9ec9d8", Math.min(10, 4 + this.vy / 150), 85);
        game?.audio?.play("land");
        game?.addShake?.(Math.min(4, this.vy / 240));
      }
    } else if (this.jumps === 0) {
      // walked off ledge: retain only the air jump after coyote expires
      if (this.coyote <= 0) this.jumps = 1;
    }

    // fall out of world
    if (this.y > 820) game?.playerFell?.();

    // dust while dashing
    if (this.dashTime > 0 && Math.random() < 0.8) {
      game?.particles?.add({
        x: this.cx + rand(-10, 10), y: this.cy + rand(-22, 22),
        vx: -this.facing * rand(60, 220), vy: rand(-40, 40),
        life: rand(0.2, 0.4), size: rand(1, 3), color: "#5df7ff",
        shape: "line", stretch: 2.5, glow: 8, drag: 0.92,
      });
    }

    // passive energy trail
    this.updateCosmetics(dt, game);
  }

  startAttack(game, forcedIndex = null) {
    let index;
    if (forcedIndex !== null) index = forcedIndex;
    else if (this.comboTimer > 0) index = (this.attackIndex + 1) % 3;
    else index = 0;
    this.attackIndex = index;
    const air = !this.grounded;
    const dur = air ? 0.34 : [0.27, 0.29, 0.34][index];
    this.attack = {
      index, t: 0, dur, air,
      activeFrom: air ? 0.055 : [0.045, 0.05, 0.07][index],
      activeTo: air ? 0.21 : [0.14, 0.15, 0.2][index],
    };
    this.hitSet = new Set();
    this.comboTimer = 0.75;
    this.energyDelay = Math.max(this.energyDelay, 0.3);
    const type = air ? "air" : index === 2 ? "overhead" : index === 1 ? "reverse" : "slash";
    this.slashes.push({ age: 0, max: air ? 0.3 : 0.24, type, facing: this.facing, x: this.x + this.w / 2, y: this.y + 27, seed: Math.random() * 4 });
    game?.audio?.play(index === 1 ? "slash2" : index === 2 ? "slash3" : "slash", 1 + index * 0.1);
    game?.addShake?.(index === 2 ? 2.5 : 1.2);
  }

  beginDashStrike(game) {
    if (this.dashStrikeHit) return;
    this.dashStrike = true;
    this.dashStrikeTimer = 0.3;
    this.dashStrikeHit = false;
    this.dashTime = Math.max(this.dashTime, 0.13);
    this.slashes.push({ age: 0, max: 0.26, type: "dash", facing: this.facing, x: this.x + this.w / 2, y: this.y + 30, seed: Math.random() * 4 });
    game?.audio?.play("slash3");
    game?.audio?.play("dash");
    game?.addShake?.(4);
  }

  startDash(axis, game) {
    this.facing = axis !== 0 ? (axis > 0 ? 1 : -1) : this.facing;
    this.dashTime = 0.17;
    this.invuln = Math.max(this.invuln, 0.24);
    this.energy -= 22;
    this.energyDelay = 0.7;
    this.airDash = this.grounded ? this.airDash : false;
    this.dashStrikeHit = false;
    game?.audio?.play("dash");
    game?.particles?.burst?.();
    game?.particles?.ring(this.cx, this.cy, "#5df7ff", 30, 0.2, 2);
    game?.particles?.spark(this.cx, this.cy, "#5df7ff", 8, 140);
  }

  collide(world, wasGrounded, game, input) {
    this.grounded = false;
    this.groundPlatform = null;
    const prevBottom = this.y + this.h - this.vy * (1 / 60);
    // horizontal
    for (const p of world.platforms) {
      if (p.oneWay) continue;
      if (p.type === "ground" && !rectsOverlap(this, p)) continue;
      if (!rectsOverlap(this, p)) continue;
      if (this.vx > 0) {
        this.x = p.x - this.w - 0.01;
        this.vx = 0;
      } else if (this.vx < 0) {
        this.x = p.x + p.w + 0.01;
        this.vx = 0;
      }
    }

    // vertical
    for (const p of world.platforms) {
      if (!rectsOverlap(this, p)) continue;
      if (this.vy >= 0) {
        const prevBot = prevBottom;
        const tolerance = p.oneWay ? 10 : 18;
        if (prevBot <= p.y + tolerance) {
          this.y = p.y - this.h;
          if (this.vy > 620) {
            game?.particles?.dust(this.cx, p.y, "#8fd2e2", 6, 70);
          }
          this.vy = 0;
          this.grounded = true;
          this.groundPlatform = p;
        }
      } else if (!p.oneWay) {
        const prevTop = this.y - this.vy * (1 / 60);
        if (prevTop >= p.y + p.h - 12) {
          this.y = p.y + p.h;
          this.vy = 60;
        }
      }
    }
    // drop through one-way if holding down? (not necessary, keep)
  }

  getAttackInfo() {
    if (!this.alive) return null;
    if (this.dashStrike && !this.dashStrikeHit && this.dashStrikeTimer > 0) {
      const dir = this.facing;
      return {
        x: dir > 0 ? this.x + 8 : this.x - 100,
        y: this.y + 2,
        w: 126,
        h: 60,
        damage: 34,
        knockX: dir * 460,
        knockY: -210,
        heavy: true,
        kind: "dash",
      };
    }
    if (!this.attack) return null;
    const a = this.attack;
    if (a.t < a.activeFrom || a.t > a.activeTo) return null;
    const dir = this.facing;
    if (a.air) {
      return {
        x: this.cx - 62, y: this.y - 2, w: 124, h: 68,
        damage: 16, knockX: dir * 200, knockY: -170, heavy: false, kind: "air",
      };
    }
    const idx = a.index;
    const reach = [84, 92, 104][idx];
    return {
      x: dir > 0 ? this.x + this.w - 8 : this.x - reach + 8,
      y: this.y + (idx === 2 ? -4 : 10),
      w: reach,
      h: idx === 2 ? 76 : 48,
      damage: [12, 14, 20][idx],
      knockX: dir * (idx === 2 ? 330 : 180),
      knockY: idx === 2 ? -330 : -60,
      heavy: idx === 2,
      kind: "combo",
    };
  }

  registerHit(kind) {
    if (kind === "dash") this.dashStrikeHit = true;
    this.addEnergy(kind === "dash" ? 12 : 7);
    this.energyDelay = Math.max(this.energyDelay, 0.4);
  }

  takeDamage(amount, fromX, game, opts = {}) {
    if (!this.alive) return false;
    if (this.invuln > 0 && !opts.ignoreInvuln) return false;
    if (this.dashTime > 0 && !opts.ignoreInvuln) return false;
    this.health -= amount;
    this.hitFlash = 1;
    this.invuln = opts.invuln ?? 0.9;
    this.hurtTimer = 0.24;
    const dir = fromX === undefined ? -this.facing : (this.cx < fromX ? -1 : 1);
    this.vx = dir * (opts.knockback ?? 260);
    this.vy = Math.min(this.vy, -180);
    this.attack = null;
    this.dashTime = 0;
    this.attackQueued = false;
    game?.audio?.play("hurt");
    game?.addShake?.(opts.shake ?? 8);
    game?.flashDamage?.();
    game?.hitstop?.(0.045);
    game?.particles?.hit(this.cx, this.cy, "#ff5a7a", true);
    game?.particles?.text(this.cx, this.y - 4, `-${Math.round(amount)}`, "#ff8aa0", 13);
    if (this.health <= 0) {
      this.health = 0;
      this.die(game);
    }
    return true;
  }

  die(game) {
    if (!this.alive) return;
    this.alive = false;
    this.deathTimer = 0;
    this.vy = -340;
    this.vx = -this.facing * 120;
    game?.audio?.play("death");
    game?.onPlayerDeath?.();
  }

  updateCosmetics(dt, game) {
    // run cycle
    if (this.grounded && Math.abs(this.vx) > 20) this.runPhase += dt * (5 + Math.abs(this.vx) * 0.028);
    else if (this.grounded) this.runPhase += dt * 1.6;
    // scarf follows head
    const targetX = this.x + this.w / 2 - this.facing * 12;
    const targetY = this.y + 15;
    const points = this.scarf;
    points[0].x = targetX;
    points[0].y = targetY;
    for (let i = 1; i < points.length; i++) {
      const p = points[i];
      const prev = points[i - 1];
      p.x += (prev.x - p.x) * Math.min(1, dt * 16);
      p.y += (prev.y - p.y) * Math.min(1, dt * 16);
      p.x -= this.vx * dt * 0.06;
      p.y += (18 + i * 1.5) * dt;
      p.y += Math.sin(this.time * 4 - i * 0.7) * 7 * dt;
    }
    // afterimages
    for (let i = this.afterimages.length - 1; i >= 0; i--) {
      const a = this.afterimages[i];
      a.life -= dt;
      if (a.life <= 0) this.afterimages.splice(i, 1);
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.age += dt;
      if (s.age >= s.max) this.slashes.splice(i, 1);
    }
    // passive trail when very fast
    if (this.grounded && Math.abs(this.vx) > 300 && Math.random() < dt * 10) {
      game?.particles?.add({
        x: this.cx - this.facing * 12, y: this.footY - rand(4, 30),
        vx: -this.facing * rand(10, 60), vy: rand(-20, 8),
        life: rand(0.2, 0.4), size: rand(1, 2.5), color: "#5df7ff", glow: 5, drag: 0.94,
      });
    }
  }

  // ------------------------------------------------------------------ DRAW
  draw(ctx, game, time) {
    // shadow
    ctx.save();
    const shadowY = this.grounded ? this.footY : Math.min(this.footY + 40, 640);
    const g = ctx.createRadialGradient(this.cx, shadowY, 2, this.cx, shadowY, 32);
    g.addColorStop(0, "rgba(0,0,0,0.55)");
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(this.cx, shadowY, 26, 6, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    // afterimages
    for (const a of this.afterimages) {
      const alpha = (a.life / a.max) * 0.32;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.globalCompositeOperation = "lighter";
      ctx.fillStyle = "#5df7ff";
      ctx.shadowColor = "#5df7ff";
      ctx.shadowBlur = 16;
      ctx.fillRect(a.x + 4, a.y + 8, this.w - 8, this.h - 10);
      ctx.restore();
    }

    // slash effects
    for (const s of this.slashes) this.drawSlash(ctx, s);

    if (!this.alive && this.deathTimer > 0.01) {
      // death dissolve flicker
    }

    const flicker = this.invuln > 0 && this.invuln < 0.9 && Math.floor(this.time * 24) % 2 === 0;
    if (flicker) return;

    ctx.save();
    ctx.translate(this.cx, this.footY);
    ctx.scale(this.facing, 1);

    const run = clamp(Math.abs(this.vx) / RUN_MAX, 0, 1);
    const phase = this.runPhase;
    const airborne = !this.grounded;
    const dashing = this.dashTime > 0;
    const attacking = !!this.attack || this.dashStrike;
    const hurt = this.hurtTimer > 0.05;
    const bob = this.grounded && !dashing ? Math.sin(phase * 2) * 1.2 * (1 - run) : 0;

    // scarf behind
    this.drawScarf(ctx);

    // legs
    let legA = 0, legB = 0, footLift = 0;
    if (airborne) {
      legA = 0.75; legB = -0.5;
      if (this.vy < 0) { legA = 0.95; legB = -0.7; }
    } else if (attack_in_progress(this)) {
      legA = 0.35; legB = -0.35;
    } else {
      legA = Math.sin(phase) * 0.8 * run;
      legB = -Math.sin(phase) * 0.8 * run;
    }
    const hipY = -27 + bob;
    const hipX = -1;
    const stance = airborne ? 6 : 7 + run * 3;
    this.limb(ctx, hipX, hipY, hipX + Math.sin(legA) * 7, -14 + Math.abs(Math.sin(legA)) * 1, -2 + legA * 1.2, 6.2, "#11192b");
    this.limb(ctx, hipX, hipY, hipX + Math.sin(legB) * 7, -14, -2 + legB * 1.2, 6.2, "#0a1020");
    // boots
    ctx.fillStyle = "#2b3b55";
    ctx.fillRect(-4 + legacyFoot(legA), -5, 11, 5);
    ctx.fillStyle = "#1c2940";
    ctx.fillRect(-4 + legacyFoot(legB), -5, 11, 5);

    // torso
    const torsoGrad = ctx.createLinearGradient(-10, -52, 12, -24);
    torsoGrad.addColorStop(0, "#1b2940");
    torsoGrad.addColorStop(0.6, "#0d1526");
    torsoGrad.addColorStop(1, "#070c16");
    ctx.fillStyle = torsoGrad;
    ctx.beginPath();
    ctx.moveTo(-8, -49 + bob);
    ctx.lineTo(9, -46 + bob);
    ctx.lineTo(7, -27 + bob);
    ctx.lineTo(-7, -28 + bob);
    ctx.closePath();
    ctx.fill();
    // chest armor highlight
    ctx.strokeStyle = "rgba(93,247,255,0.5)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-4, -44 + bob); ctx.lineTo(5, -42 + bob); ctx.lineTo(4, -33 + bob);
    ctx.stroke();
    // belt
    ctx.fillStyle = "#ff3fce";
    ctx.globalAlpha = 0.8;
    ctx.fillRect(-8, -29 + bob, 16, 2);
    ctx.globalAlpha = 1;

    // back arm
    const backArm = attacking ? -0.5 : Math.sin(phase) * 0.5 * run;
    this.limb(ctx, -4, -44 + bob, -10, -35 + bob, -8 + backArm * 5, -25 + bob, 4.3, "#0c1422");
    ctx.fillStyle = "#121d30";
    ctx.beginPath(); ctx.arc(-8 + backArm * 5, -24 + bob, 2.6, 0, TAU); ctx.fill();

    // head
    const headX = 2, headY = -57 + bob;
    ctx.save();
    ctx.translate(headX, headY);
    ctx.fillStyle = "#111a2b";
    ctx.beginPath();
    ctx.arc(0, 0, 8.5, 0, TAU);
    ctx.fill();
    // helmet crest
    ctx.fillStyle = "#1e2e49";
    ctx.beginPath();
    ctx.moveTo(-8, -3); ctx.lineTo(-2, -13); ctx.lineTo(7, -9); ctx.lineTo(8, -2); ctx.closePath();
    ctx.fill();
    // visor
    ctx.shadowColor = "#5df7ff";
    ctx.shadowBlur = 10;
    ctx.fillStyle = "#9bfbff";
    ctx.beginPath();
    ctx.moveTo(0, -2.5);
    ctx.lineTo(8.5, -1.6);
    ctx.lineTo(8.5, 1.6);
    ctx.lineTo(0, 2.2);
    ctx.closePath();
    ctx.fill();
    ctx.shadowBlur = 0;
    // scarf collar
    ctx.fillStyle = "#ff3fce";
    ctx.fillRect(-9, 5, 13, 2.5);
    ctx.restore();

    // front arm & sword
    if (attacking) this.drawAttackPose(ctx, bob);
    else this.drawIdleArm(ctx, bob, phase, run, airborne, dashing);

    // rim light
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.18;
    ctx.strokeStyle = "#5df7ff";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-7, -47 + bob); ctx.lineTo(-8, -28 + bob);
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.restore();

    // dash energy streaks
    if (this.dashTime > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.5;
      ctx.strokeStyle = "#5df7ff";
      ctx.shadowColor = "#5df7ff";
      ctx.shadowBlur = 14;
      for (let i = 0; i < 4; i++) {
        const y = this.y + 14 + i * 11;
        ctx.beginPath();
        ctx.moveTo(this.x - this.facing * (10 + i * 9), y);
        ctx.lineTo(this.x - this.facing * (70 + i * 20), y + rand(-2, 2));
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  drawScarf(ctx) {
    const pts = this.scarf;
    if (pts.length < 2) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (let layer = 0; layer < 2; layer++) {
      ctx.beginPath();
      ctx.moveTo(-6, -51);
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i];
        const x = p.x - (this.cx) + (layer === 0 ? 0 : 2);
        const y = p.y - this.footY + (layer === 0 ? 0 : 3);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = layer === 0 ? "rgba(255,63,206,0.85)" : "rgba(255,160,235,0.4)";
      ctx.lineWidth = layer === 0 ? 4 : 1.6;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.shadowColor = "#ff3fce";
      ctx.shadowBlur = layer === 0 ? 12 : 6;
      ctx.stroke();
    }
    ctx.restore();
  }

  drawIdleArm(ctx, bob, phase, run, airborne, dashing) {
    let handX, handY, elbowX, elbowY;
    if (dashing) {
      handX = 12; handY = -34; elbowX = 7; elbowY = -41;
    } else if (airborne) {
      handX = 11; handY = -42; elbowX = 9; elbowY = -46;
    } else {
      const swing = Math.sin(phase + Math.PI) * 0.55 * run;
      handX = 5 + swing * 7;
      handY = -30 + Math.abs(swing) * 2;
      elbowX = 7 + swing * 4;
      elbowY = -38 + bob;
    }
    this.limb(ctx, 4, -44 + bob, elbowX, elbowY, handX, handY, 4.2, "#152136");
    ctx.fillStyle = "#5df7ff";
    ctx.globalAlpha = 0.8;
    ctx.beginPath(); ctx.arc(handX, handY, 1.4, 0, TAU); ctx.fill();
    ctx.globalAlpha = 1;
    // sheathed katana on back
    ctx.save();
    ctx.translate(-7, -40 + bob);
    ctx.rotate(-0.62);
    ctx.strokeStyle = "#1a2740";
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-3, 0); ctx.lineTo(31, 0); ctx.stroke();
    ctx.strokeStyle = "rgba(93,247,255,0.75)";
    ctx.lineWidth = 1;
    ctx.shadowColor = "#5df7ff";
    ctx.shadowBlur = 7;
    ctx.beginPath(); ctx.moveTo(8, 0); ctx.lineTo(31, 0); ctx.stroke();
    ctx.restore();
  }

  drawAttackPose(ctx, bob) {
    let t;
    let kind;
    if (this.dashStrike && this.dashStrikeTimer > 0) {
      t = 1 - this.dashStrikeTimer / 0.3;
      kind = "dash";
    } else if (this.attack) {
      t = clamp(this.attack.t / this.attack.dur, 0, 1);
      kind = this.attack.air ? "air" : this.attack.index === 2 ? "overhead" : "combo";
    } else {
      t = 0; kind = "combo";
    }
    let handX = 20, handY = -38, elbowX = 12, elbowY = -40;
    let swordAngle = -0.5;
    if (kind === "dash") {
      handX = 30; handY = -36; elbowX = 16; elbowY = -41;
      swordAngle = -0.06;
    } else if (kind === "air") {
      const a = t * TAU;
      handX = Math.cos(a) * 14 + 8;
      handY = Math.sin(a) * 12 - 36;
      elbowX = handX * 0.7;
      elbowY = handY * 0.85 - 4;
      swordAngle = a + 1.4;
    } else if (kind === "overhead") {
      swordAngle = -1.9 + t * 3.1;
      handX = 17 + t * 8; handY = -43 + t * 12;
      elbowX = 9; elbowY = -42;
    } else {
      const idx = this.attack?.index ?? 0;
      if (idx === 1) {
        swordAngle = 1.75 - t * 3.4;
        handX = 15 - t * 2; handY = -33;
      } else {
        swordAngle = -1.45 + t * 3.0;
        handX = 19 + t * 4; handY = -38 - t * 2;
      }
      elbowX = 11; elbowY = -40;
    }
    this.limb(ctx, 4, -44 + bob, elbowX, elbowY, handX, handY, 4.4, "#18263e");
    // glove
    ctx.fillStyle = "#0a1220";
    ctx.beginPath(); ctx.arc(handX, handY, 3, 0, TAU); ctx.fill();
    // katana
    ctx.save();
    ctx.translate(handX, handY);
    ctx.rotate(swordAngle);
    // hilt
    ctx.strokeStyle = "#161c2b";
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(1, 0); ctx.stroke();
    ctx.strokeStyle = "#ff3fce";
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(-10, 0); ctx.lineTo(0, 0); ctx.stroke();
    // guard
    ctx.fillStyle = "#2a3b55";
    ctx.fillRect(0, -4, 2.5, 8);
    // blade
    ctx.globalCompositeOperation = "lighter";
    ctx.shadowColor = "#5df7ff";
    ctx.shadowBlur = 15;
    const grad = ctx.createLinearGradient(2, 0, 54, 0);
    grad.addColorStop(0, "#eaffff");
    grad.addColorStop(0.6, "#b9fbff");
    grad.addColorStop(1, "rgba(93,247,255,0.35)");
    ctx.strokeStyle = grad;
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.moveTo(2, 0);
    ctx.lineTo(52, -1.5);
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,0.9)";
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    ctx.moveTo(4, -0.6);
    ctx.lineTo(50, -2);
    ctx.stroke();
    ctx.restore();
    // arc afterimage near blade
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.2;
    ctx.strokeStyle = "#5df7ff";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(8, -36 + bob, 39, swordAngle - 0.45, swordAngle + 0.1);
    ctx.stroke();
    ctx.restore();
  }

  drawSlash(ctx, s) {
    const p = s.age / s.max;
    const alpha = Math.sin(Math.min(1, p * 1.6) * Math.PI) * (1 - p * 0.5);
    if (alpha <= 0) return;
    const dir = s.facing;
    ctx.save();
    ctx.translate(s.x, s.y);
    ctx.scale(dir, 1);
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = alpha * 0.85;
    ctx.shadowColor = "#5df7ff";
    ctx.shadowBlur = 18;
    let start, end, radius, width;
    if (s.type === "dash") {
      start = -0.9; end = 0.7; radius = 92; width = 9;
    } else if (s.type === "overhead") {
      start = -2.5; end = 1.4; radius = 72; width = 7;
    } else if (s.type === "air") {
      start = -2.8 + p * 1.5; end = start + TAU * 0.8; radius = 64; width = 6;
    } else if (s.type === "reverse") {
      start = 1.9 - p * 0.4; end = -1.4; radius = 68; width = 6;
    } else {
      start = -1.7 + p * 0.3; end = 0.9; radius = 66; width = 6;
    }
    const beats = s.type === "dash" ? 3 : 2;
    for (let i = 0; i < beats; i++) {
      const rr = radius - i * 7;
      ctx.globalAlpha = alpha * (0.7 - i * 0.2);
      ctx.lineWidth = width - i * 1.6;
      ctx.beginPath();
      ctx.arc(0, 0, rr, start, end, false);
      ctx.strokeStyle = i === 0 ? "#eaffff" : "#5df7ff";
      ctx.stroke();
    }
    ctx.globalAlpha = alpha * 0.35;
    ctx.lineWidth = width * 2.4;
    ctx.strokeStyle = "#5df7ff";
    ctx.beginPath();
    ctx.arc(0, 0, radius, start, end, false);
    ctx.stroke();
    ctx.restore();
  }

  limb(ctx, x1, y1, x2, y2, x3, y3, width, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x3, y3);
    ctx.stroke();
  }
}

function attack_in_progress(p) {
  return !!p.attack || p.dashStrike;
}
function legacyFoot(angle) {
  return Math.sin(angle) * 8;
}

import { TAU, clamp, approach, rand, lerp, rectsOverlap, dist2 } from "./util.js";

let boltId = 0;

export class Bolt {
  constructor(x, y, vx, vy, opts = {}) {
    this.id = ++boltId;
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.r = opts.r ?? 6;
    this.damage = opts.damage ?? 10;
    this.life = opts.life ?? 3.6;
    this.maxLife = this.life;
    this.color = opts.color ?? "#ff5a6e";
    this.trailColor = opts.trailColor ?? this.color;
    this.owner = opts.owner ?? "enemy";
    this.type = opts.type ?? "bolt";
    this.gravity = opts.gravity ?? 0;
    this.dead = false;
    this.trail = [];
    this.spin = rand(0, TAU);
  }

  update(dt, world, game) {
    this.life -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    this.vy += this.gravity * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.spin += dt * 5;
    this.trail.push({ x: this.x, y: this.y, life: 0.18 });
    if (this.trail.length > 8) this.trail.shift();
    for (const t of this.trail) t.life -= dt;
    if (this.y > 760 || this.x < 0 || this.x > world.width) this.dead = true;
    // projectile hits terrain
    for (const p of world.platforms) {
      if (p.oneWay) continue;
      if (this.x > p.x && this.x < p.x + p.w && this.y > p.y && this.y < p.y + Math.min(p.h, 16)) {
        this.dead = true;
        game?.particles?.spark(this.x, this.y, this.color, 5, 100);
        return;
      }
    }
  }

  draw(ctx, time) {
    const a = clamp(this.life / 0.4, 0, 1);
    ctx.save();
    ctx.globalAlpha = a;
    ctx.globalCompositeOperation = "lighter";
    for (let i = 0; i < this.trail.length; i++) {
      const t = this.trail[i];
      if (t.life <= 0) continue;
      ctx.globalAlpha = a * (i / this.trail.length) * 0.35;
      ctx.fillStyle = this.trailColor;
      ctx.beginPath();
      ctx.arc(t.x, t.y, this.r * (i / this.trail.length) * 0.9, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = a;
    ctx.shadowColor = this.color;
    ctx.shadowBlur = 16;
    if (this.type === "blade") {
      ctx.translate(this.x, this.y);
      ctx.rotate(this.spin);
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.moveTo(0, -this.r * 2.2);
      ctx.lineTo(this.r, this.r);
      ctx.lineTo(0, this.r * 0.4);
      ctx.lineTo(-this.r, this.r);
      ctx.closePath();
      ctx.fill();
    } else {
      const g = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.r * 2.6);
      g.addColorStop(0, "#ffffff");
      g.addColorStop(0.3, this.color);
      g.addColorStop(1, "rgba(255,60,90,0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r * 2.6, 0, TAU);
      ctx.fill();
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r * 0.55, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
}

class Enemy {
  constructor(spawn) {
    this.type = spawn.type;
    this.spawn = { x: spawn.x, y: spawn.y };
    this.zone = spawn.zone ?? 0;
    this.elite = !!spawn.elite;
    this.dead = false;
    this.deathTimer = 0;
    this.active = false;
    this.awake = false;
    this.health = 50;
    this.maxHealth = 50;
    this.vx = 0;
    this.vy = 0;
    this.facing = -1;
    this.grounded = false;
    this.groundPlatform = null;
    this.hitFlash = 0;
    this.hitStun = 0;
    this.time = rand(0, 10);
    this.attackCooldown = rand(0.8, 2);
    this.once = false;
    this.score = 100;
    this.orbDrop = 2;
    this.alpha = 1;
  }

  get cx() { return this.x + this.w / 2; }
  get cy() { return this.y + this.h / 2; }
  get bottom() { return this.y + this.h; }

  activateIfNear(player) {
    if (!this.awake) {
      const dx = Math.abs(player.cx - this.cx);
      const dy = Math.abs(player.cy - this.cy);
      if (dx < 640 && dy < 380) {
        this.awake = true;
        this.active = true;
        this.onWake?.();
      }
    } else {
      this.active = Math.abs(player.cx - this.cx) < 1150;
    }
  }

  hurt(damage, dirX, dirY, game, info = {}) {
    if (this.dead) return false;
    this.health -= damage;
    this.hitFlash = 1;
    this.hitStun = Math.max(this.hitStun, 0.08);
    this.awake = true;
    this.active = true;
    this.vx += dirX * (info.heavy ? 1 : 0.45);
    if (this.vy === 0 && dirY < 0) this.vy = dirY * 0.5;
    game?.particles?.hit(this.cx, this.cy - 4, info.heavy ? "#fff3b0" : "#c9ffff", info.heavy);
    game?.particles?.text(this.cx + rand(-8, 8), this.y - 6, `${Math.round(damage)}`, info.heavy ? "#fff3b0" : "#bffcff", info.heavy ? 16 : 12);
    game?.audio?.play(info.heavy ? "heavy" : "hit");
    game?.addShake?.(info.heavy ? 6 : 2.5);
    game?.hitstop?.(info.heavy ? 0.06 : 0.032);
    if (this.health <= 0) {
      this.die(game);
      return true;
    }
    return false;
  }

  die(game) {
    if (this.dead) return;
    this.dead = true;
    this.deathTimer = 0;
    this.health = 0;
    game?.onEnemyKilled?.(this);
    game?.particles?.explosion(this.cx, this.cy, this.elite ? "#ffc36b" : "#ff7a4d", this.elite ? 1.35 : 0.9);
    game?.audio?.play("enemyDie");
    game?.addShake?.(this.elite ? 9 : 5);
  }

  physics(dt, world, game, gravity = 1900) {
    this.vy = Math.min(1050, this.vy + gravity * dt);
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.grounded = false;
    this.groundPlatform = null;
    if (this.x < 20) { this.x = 20; this.vx = 0; }
    for (const p of world.platforms) {
      if (p.oneWay) continue;
      if (!rectsOverlap(this, p)) continue;
      if (this.vx > 0) { this.x = p.x - this.w; this.vx = 0; }
      else if (this.vx < 0) { this.x = p.x + p.w; this.vx = 0; }
    }
    for (const p of world.platforms) {
      if (!rectsOverlap(this, p)) continue;
      if (this.vy >= 0 && this.y + this.h - this.vy * dt <= p.y + 16) {
        this.y = p.y - this.h;
        this.vy = 0;
        this.grounded = true;
        this.groundPlatform = p;
      }
    }
    if (this.y > 760) this.die(game);
  }

  contact(player, game, damage = 7) {
    if (this.dead) return;
    if (rectsOverlap(this, player)) {
      player.takeDamage(damage, this.cx, game, { knockback: 220, shake: 5 });
    }
  }

  updateCommon(dt) {
    this.time += dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 4.2);
    this.hitStun = Math.max(0, this.hitStun - dt);
    if (this.dead) {
      this.deathTimer += dt;
      this.alpha = Math.max(0, 1 - this.deathTimer * 2);
    }
  }

  drawHealth(ctx) {
    if (this.dead || this.health >= this.maxHealth) return;
    const w = this.elite ? 58 : 44;
    const y = this.y - (this.type === "drone" ? 18 : 14);
    ctx.save();
    ctx.translate(this.cx - w / 2, y);
    ctx.fillStyle = "rgba(4,4,10,0.8)";
    ctx.fillRect(0, 0, w, 4);
    ctx.fillStyle = this.elite ? "#ffc36b" : "#ff5a6e";
    ctx.shadowColor = "#ff5a6e";
    ctx.shadowBlur = 6;
    ctx.fillRect(0, 0, w * clamp(this.health / this.maxHealth, 0, 1), 4);
    ctx.restore();
  }

  telegraph(ctx, time, color = "#ff3e62") {
    const r = 34 + Math.sin(time * 14) * 5;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.65;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.shadowColor = color;
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.stroke();
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
}

// ---------------------------------------------------------------- DRONE
export class Drone extends Enemy {
  constructor(spawn) {
    super(spawn);
    this.w = 44;
    this.h = 34;
    this.x = spawn.x;
    this.y = spawn.y;
    this.maxHealth = this.health = 32;
    this.score = 120;
    this.orbDrop = 2;
    this.baseY = spawn.y;
    this.diveTimer = 0;
    this.diving = false;
    this.diveDir = { x: 0, y: 0 };
    this.telegraphTimer = 0;
    this.returnTimer = 0;
    this.bobPhase = rand(0, TAU);
  }

  onWake() {}
  get cx() { return this.x + this.w / 2; }
  get cy() { return this.y + this.h / 2; }

  update(dt, player, world, game, projectiles) {
    this.updateCommon(dt);
    if (this.dead) return;
    this.activateIfNear(player);
    if (!this.active) {
      this.y = this.baseY + Math.sin(this.time * 1.5 + this.bobPhase) * 8;
      return;
    }
    if (this.hitStun > 0) { this.x += this.vx * dt; this.vx *= 0.9; return; }
    const dx = player.cx - this.cx;
    const dy = player.cy - this.cy;
    const dist = Math.hypot(dx, dy);
    this.facing = dx > 0 ? 1 : -1;

    if (this.diving) {
      this.diveTimer -= dt;
      this.x += this.diveDir.x * 620 * dt;
      this.y += this.diveDir.y * 620 * dt;
      if (Math.random() < 0.8) game?.particles?.add({ x: this.cx, y: this.cy, vx: rand(-20, 20), vy: rand(-10, 20), life: 0.35, size: rand(2, 4), color: "#ff3e62", glow: 8, drag: 0.94 });
      this.contact(player, game, 13);
      if (this.diveTimer <= 0) {
        this.diving = false;
        this.returnTimer = 0.9;
        this.attackCooldown = rand(2.2, 3.1);
        game?.particles?.ring(this.cx, this.cy, "#ff3e62", 30, 0.25, 2);
      }
      return;
    }

    // return to hover height
    if (this.returnTimer > 0) {
      this.returnTimer -= dt;
      const ty = player.y - 160 + Math.sin(this.time * 2) * 26;
      const tx = player.cx - this.facing * 140;
      this.x = approach(this.x, tx, 260 * dt);
      this.y = approach(this.y, ty, 260 * dt);
      this.contact(player, game, 8);
      return;
    }

    // hover / reposition
    const targetX = player.cx - Math.sign(dx || 1) * 190 + Math.sin(this.time * 1.1 + this.bobPhase) * 50;
    const targetY = player.y - 170 + Math.sin(this.time * 2.1 + this.bobPhase) * 18;
    this.x = approach(this.x, targetX, 170 * dt);
    this.y = approach(this.y, targetY, 180 * dt);
    this.contact(player, game, 8);
    this.attackCooldown -= dt;

    if (this.telegraphTimer > 0) {
      this.telegraphTimer -= dt;
      this.x += rand(-1.5, 1.5);
      this.y += rand(-1.5, 1.5);
      if (this.telegraphTimer <= 0) {
        this.diving = true;
        this.diveTimer = 0.48;
        const len = Math.hypot(dx, dy) || 1;
        this.diveDir = { x: dx / len * 0.75 + this.facing * 0.35, y: dy / len * 0.75 + 0.25 };
        const l = Math.hypot(this.diveDir.x, this.diveDir.y) || 1;
        this.diveDir.x /= l; this.diveDir.y /= l;
        game?.audio?.play("dash");
        game?.addShake?.(3);
      }
    } else if (this.attackCooldown <= 0 && dist < 540) {
      this.telegraphTimer = 0.5;
      this.attackCooldown = 3.5;
      game?.audio?.play("ui");
    }
  }

  draw(ctx, time) {
    if (this.dead && this.alpha <= 0) return;
    ctx.save();
    ctx.translate(this.cx, this.cy);
    ctx.globalAlpha = this.alpha;
    if (this.telegraphTimer > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      this.telegraph(ctx, time, "#ff3e62");
      ctx.restore();
    }
    const tilt = clamp(this.vx / 600, -0.4, 0.4);
    ctx.rotate(tilt);
    // thruster glow
    ctx.globalCompositeOperation = "lighter";
    const tg = ctx.createRadialGradient(0, 20, 0, 0, 20, 20);
    tg.addColorStop(0, "rgba(93,247,255,0.55)");
    tg.addColorStop(1, "rgba(93,247,255,0)");
    ctx.fillStyle = tg;
    ctx.beginPath(); ctx.arc(0, 22, 20, 0, TAU); ctx.fill();
    ctx.globalCompositeOperation = "source-over";
    // rotor fins
    ctx.strokeStyle = "#293a55";
    ctx.lineWidth = 2.5;
    for (let i = 0; i < 2; i++) {
      const a = time * (this.diving ? 15 : 7) + i * Math.PI;
      ctx.beginPath();
      ctx.ellipse(0, 0, 30, 7, a, 0, TAU);
      ctx.stroke();
    }
    // body
    const g = ctx.createLinearGradient(0, -14, 0, 15);
    g.addColorStop(0, "#3c4966");
    g.addColorStop(0.45, "#1b2438");
    g.addColorStop(1, "#0a0e18");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, 17, 14, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(93,247,255,0.45)";
    ctx.lineWidth = 1;
    ctx.stroke();
    // eye
    ctx.shadowColor = this.telegraphTimer > 0 ? "#ff3e62" : "#ff5a6e";
    ctx.shadowBlur = 16;
    ctx.fillStyle = this.telegraphTimer > 0 ? "#ffffff" : "#ff5a6e";
    ctx.beginPath();
    ctx.ellipse(this.facing * 6, 0, 5.5, 3, 0, 0, TAU);
    ctx.fill();
    ctx.shadowBlur = 0;
    // antenna
    ctx.strokeStyle = "#4b5f80";
    ctx.beginPath();
    ctx.moveTo(0, -13); ctx.lineTo(0, -22);
    ctx.stroke();
    ctx.fillStyle = "#ff3fce";
    ctx.fillRect(-1.4, -24, 2.8, 2.8);
    ctx.restore();
    this.drawHealth(ctx);
  }
}

// ---------------------------------------------------------------- MELEE
export class MeleeBot extends Enemy {
  constructor(spawn) {
    super(spawn);
    this.w = 42;
    this.h = 60;
    this.x = spawn.x;
    this.y = spawn.y - this.h;
    this.maxHealth = this.health = spawn.elite ? 110 : 58;
    this.score = spawn.elite ? 300 : 150;
    this.orbDrop = spawn.elite ? 4 : 2;
    this.speed = spawn.elite ? 170 : 125;
    this.state = "idle";
    this.stateTimer = 0;
    this.attackCooldown = rand(0.6, 1.4);
    this.swing = 0;
    this.jumpCooldown = 0;
    this.patrolDir = 1;
    this.spawnX = spawn.x;
  }

  update(dt, player, world, game, projectiles) {
    this.updateCommon(dt);
    if (this.dead) return;
    this.activateIfNear(player);
    if (!this.active) {
      this.physics(dt, world, game);
      this.vx = Math.sin(this.time * 0.8) * 16;
      return;
    }
    if (this.hitStun > 0) {
      this.physics(dt, world, game);
      this.vx *= 0.9;
      return;
    }
    this.attackCooldown -= dt;
    this.jumpCooldown = Math.max(0, this.jumpCooldown - dt);
    const dx = player.cx - this.cx;
    const dy = player.cy - this.cy;
    const adx = Math.abs(dx);
    this.facing = dx > 0 ? 1 : -1;
    this.contact(player, game, 6);

    if (this.state === "idle" || this.state === "chase") {
      if (!this.awake || adx > 520) {
        this.state = "idle";
        this.vx = Math.sin(this.time * 0.9) * 22;
      } else {
        this.state = "chase";
        if (adx > 82) this.vx = approach(this.vx, this.facing * this.speed, 700 * dt);
        else this.vx = approach(this.vx, 0, 800 * dt);
        // hop up to player
        if (this.grounded && player.y < this.y - 46 && adx < 150 && this.jumpCooldown <= 0) {
          this.vy = -620;
          this.jumpCooldown = 1.8;
          game?.particles?.dust(this.cx, this.y + this.h, "#b57a5a", 6, 60);
        }
        if (adx < 150 && Math.abs(dy) < 80 && this.attackCooldown <= 0) {
          this.state = "telegraph";
          this.stateTimer = this.elite ? 0.38 : 0.48;
          this.swing = 0;
          game?.audio?.play("ui");
        }
      }
    } else if (this.state === "telegraph") {
      this.vx *= 0.8;
      this.stateTimer -= dt;
      this.swing = Math.min(1, this.swing + dt * 2.5);
      if (this.stateTimer <= 0) {
        this.state = "strike";
        this.stateTimer = 0.24;
        this.vx = this.facing * (this.elite ? 560 : 440);
        this.attackHit = new Set();
        game?.audio?.play("slash2");
      }
    } else if (this.state === "strike") {
      this.stateTimer -= dt;
      this.vx = approach(this.vx, 0, 900 * dt);
      const hb = {
        x: this.facing > 0 ? this.x + this.w - 10 : this.x - 48,
        y: this.y + 8, w: 76, h: 48,
      };
      if (rectsOverlap(hb, player)) player.takeDamage(this.elite ? 22 : 15, this.cx, game, { knockback: 280, shake: 6 });
      if (this.stateTimer <= 0) {
        this.state = "recover";
        this.stateTimer = 0.48;
        this.attackCooldown = this.elite ? 0.55 : 0.9;
        this.swing = 0;
      }
    } else if (this.state === "recover") {
      this.stateTimer -= dt;
      this.vx = approach(this.vx, 0, 600 * dt);
      if (this.stateTimer <= 0) this.state = "chase";
    }

    if (this.grounded && this.groundPlatform) this.x += this.groundPlatform.dx;
    this.physics(dt, world, game);
  }

  draw(ctx, time) {
    if (this.dead && this.alpha <= 0) return;
    ctx.save();
    ctx.translate(this.cx, this.y + this.h);
    ctx.scale(this.facing, 1);
    ctx.globalAlpha = this.alpha;
    if (this.elite) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      const g = ctx.createRadialGradient(0, -30, 0, 0, -30, 55);
      g.addColorStop(0, "rgba(255,195,107,0.2)");
      g.addColorStop(1, "rgba(255,195,107,0)");
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0, -30, 55, 0, TAU); ctx.fill();
      ctx.restore();
    }
    if (this.state === "telegraph") {
      ctx.save();
      this.telegraph(ctx, time, this.elite ? "#ffc36b" : "#ff3e62");
      ctx.restore();
    }
    const lean = this.state === "strike" ? 0.18 : this.state === "chase" ? 0.06 * Math.sign(this.vx) : 0;
    ctx.rotate(lean);
    const walk = this.grounded ? Math.sin(this.time * 8) * Math.min(1, Math.abs(this.vx) / 80) : 0;
    // legs
    ctx.strokeStyle = "#1b2438";
    ctx.lineWidth = 7;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-7, -22); ctx.lineTo(-10 + walk * 7, -12); ctx.lineTo(-12 + walk * 12, -1);
    ctx.moveTo(7, -22); ctx.lineTo(10 - walk * 7, -12); ctx.lineTo(13 - walk * 12, -1);
    ctx.stroke();
    ctx.strokeStyle = "#ff5a3c";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-10 + walk * 7, -12); ctx.lineTo(-12 + walk * 12, -1);
    ctx.moveTo(10 - walk * 7, -12); ctx.lineTo(13 - walk * 12, -1);
    ctx.stroke();
    // torso
    const g = ctx.createLinearGradient(-14, -52, 14, -20);
    g.addColorStop(0, this.elite ? "#4a3a22" : "#2d3348");
    g.addColorStop(0.6, "#141a29");
    g.addColorStop(1, "#080c14");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-15, -48);
    ctx.lineTo(14, -46);
    ctx.lineTo(11, -22);
    ctx.lineTo(-11, -23);
    ctx.closePath();
    ctx.fill();
    // shoulder plates
    ctx.fillStyle = this.elite ? "#5a4726" : "#232b3e";
    ctx.beginPath(); ctx.moveTo(-23, -49); ctx.lineTo(-10, -52); ctx.lineTo(-7, -39); ctx.lineTo(-20, -37); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(22, -48); ctx.lineTo(9, -51); ctx.lineTo(7, -38); ctx.lineTo(20, -36); ctx.closePath(); ctx.fill();
    // core
    ctx.shadowColor = this.elite ? "#ffc36b" : "#ff5a3c";
    ctx.shadowBlur = 13;
    ctx.fillStyle = this.elite ? "#ffc36b" : "#ff5a3c";
    ctx.beginPath(); ctx.arc(0, -35, 3.2, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // head
    ctx.fillStyle = "#1b2234";
    ctx.fillRect(-7, -57, 15, 9);
    ctx.fillStyle = this.elite ? "#ffe2a0" : "#ff7b6a";
    ctx.fillRect(2, -54, 6, 2);
    ctx.fillStyle = "#5d6d88";
    ctx.fillRect(-8, -59, 2, 3);
    // sword arm
    const swingAngle = this.state === "telegraph" ? lerp(0.5, -1.9, this.swing) : this.state === "strike" ? 1.25 : -0.25;
    ctx.save();
    ctx.translate(17, -42);
    ctx.rotate(swingAngle);
    ctx.strokeStyle = "#0c111b";
    ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 0); ctx.stroke();
    ctx.fillStyle = "#2b3852";
    ctx.fillRect(9, -3, 3, 6);
    // blade
    ctx.globalCompositeOperation = "lighter";
    ctx.strokeStyle = this.elite ? "#ffdca0" : "#ff8b76";
    ctx.shadowColor = this.elite ? "#ffc36b" : "#ff5a3c";
    ctx.shadowBlur = 13;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(11, 0); ctx.lineTo(52, -3);
    ctx.stroke();
    ctx.restore();
    // eye glow
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = this.elite ? "#ffc36b" : "#ff3e62";
    ctx.beginPath(); ctx.arc(3, -53, 13, 0, TAU); ctx.fill();
    ctx.restore();
    this.drawHealth(ctx);
  }
}

// ---------------------------------------------------------------- GUNNER
export class Gunner extends Enemy {
  constructor(spawn) {
    super(spawn);
    this.w = 46;
    this.h = 52;
    this.x = spawn.x;
    this.y = spawn.y - this.h;
    this.maxHealth = this.health = 46;
    this.score = 180;
    this.orbDrop = 2;
    this.state = "idle";
    this.stateTimer = 0;
    this.burst = 0;
    this.burstTimer = 0;
    this.aimAngle = 0;
    this.recoil = 0;
  }

  update(dt, player, world, game, projectiles) {
    this.updateCommon(dt);
    if (this.dead) return;
    this.activateIfNear(player);
    if (!this.active) {
      this.physics(dt, world, game);
      return;
    }
    if (this.hitStun > 0) { this.physics(dt, world, game); return; }
    const dx = player.cx - this.cx;
    const dy = (player.cy - 6) - (this.y + 18);
    const adx = Math.abs(dx);
    this.facing = dx > 0 ? 1 : -1;
    this.aimAngle = Math.atan2(dy, dx);
    this.recoil = Math.max(0, this.recoil - dt * 5);
    this.attackCooldown -= dt;
    this.contact(player, game, 5);

    if (this.state === "idle" || this.state === "move") {
      this.state = "move";
      if (adx > 340) this.vx = approach(this.vx, this.facing * 100, 400 * dt);
      else if (adx < 240) this.vx = approach(this.vx, -this.facing * 90, 400 * dt);
      else this.vx = approach(this.vx, 0, 400 * dt);
      if (this.attackCooldown <= 0 && adx < 620) {
        this.state = "telegraph";
        this.stateTimer = 0.42;
        this.burst = 3;
        this.burstTimer = 0;
        game?.audio?.play("ui");
      }
    } else if (this.state === "telegraph") {
      this.vx *= 0.82;
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) {
        this.state = "fire";
        this.burstTimer = 0;
        this.attackCooldown = rand(2.2, 3.1);
      }
    } else if (this.state === "fire") {
      this.vx *= 0.85;
      this.burstTimer -= dt;
      if (this.burstTimer <= 0 && this.burst > 0) {
        this.burst--;
        this.burstTimer = 0.11;
        this.recoil = 1;
        const spread = rand(-0.07, 0.07);
        const speed = 390;
        const ox = this.cx + Math.cos(this.aimAngle) * 32;
        const oy = this.y + 18 + Math.sin(this.aimAngle) * 10;
        projectiles.push(new Bolt(ox, oy, Math.cos(this.aimAngle + spread) * speed, Math.sin(this.aimAngle + spread) * speed, {
          color: "#ff8a5c", trailColor: "#ffc36b", damage: 9, r: 5, life: 4,
        }));
        game?.audio?.play("laser");
        game?.particles?.spark(ox, oy, "#ffc36b", 4, 120);
        game?.addShake?.(1.5);
      }
      if (this.burst <= 0 && this.burstTimer <= 0) {
        this.state = "move";
        this.stateTimer = 0.5;
      }
    }
    if (this.grounded && this.groundPlatform) this.x += this.groundPlatform.dx;
    this.physics(dt, world, game);
  }

  draw(ctx, time) {
    if (this.dead && this.alpha <= 0) return;
    ctx.save();
    ctx.translate(this.cx, this.y + this.h);
    ctx.globalAlpha = this.alpha;
    if (this.state === "telegraph" || this.state === "fire") {
      ctx.save();
      this.telegraph(ctx, time, "#ffc36b");
      ctx.restore();
    }
    const walk = this.grounded ? Math.sin(this.time * 6) * Math.min(1, Math.abs(this.vx) / 70) : 0;
    // tripod legs
    ctx.strokeStyle = "#1d2538";
    ctx.lineWidth = 5;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-8, -24); ctx.lineTo(-17 + walk * 6, -1);
    ctx.moveTo(8, -24); ctx.lineTo(17 - walk * 6, -1);
    ctx.moveTo(0, -24); ctx.lineTo(-4, -2);
    ctx.stroke();
    // body
    const g = ctx.createLinearGradient(-14, -50, 14, -24);
    g.addColorStop(0, "#35405c");
    g.addColorStop(0.55, "#181f30");
    g.addColorStop(1, "#080b13");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-15, -47);
    ctx.lineTo(13, -47);
    ctx.lineTo(16, -30);
    ctx.lineTo(-16, -30);
    ctx.closePath();
    ctx.fill();
    // head visor
    ctx.fillStyle = "#121a29";
    ctx.fillRect(-8, -55, 17, 8);
    ctx.shadowColor = "#ff5a6e";
    ctx.shadowBlur = 12;
    ctx.fillStyle = "#ff7b6a";
    ctx.fillRect(-5, -53, 11, 2.2);
    ctx.shadowBlur = 0;
    // cannon arm
    ctx.save();
    ctx.translate(8, -38);
    ctx.rotate(this.aimAngle - 0.05 * this.recoil);
    ctx.fillStyle = "#2b3550";
    ctx.fillRect(-4, -5, 24, 10);
    ctx.fillStyle = "#0b101a";
    ctx.fillRect(16, -3.5, 14, 7);
    ctx.strokeStyle = "rgba(255,195,107,0.7)";
    ctx.strokeRect(16, -3.5, 14, 7);
    if (this.state === "telegraph" || this.state === "fire") {
      ctx.globalCompositeOperation = "lighter";
      ctx.fillStyle = "#ffc36b";
      ctx.shadowColor = "#ffc36b";
      ctx.shadowBlur = 14;
      ctx.beginPath(); ctx.arc(31, 0, 2.5 + Math.sin(time * 20) * 1, 0, TAU); ctx.fill();
    }
    ctx.restore();
    // shoulder antenna
    ctx.strokeStyle = "#4b5b7a";
    ctx.beginPath(); ctx.moveTo(-13, -47); ctx.lineTo(-16, -60); ctx.stroke();
    ctx.fillStyle = "#5df7ff";
    ctx.fillRect(-17, -62, 2, 2);
    ctx.restore();
    this.drawHealth(ctx);
  }
}

export function createEnemy(spawn) {
  if (spawn.type === "drone") return new Drone(spawn);
  if (spawn.type === "gunner") return new Gunner(spawn);
  return new MeleeBot(spawn);
}

import { TAU, clamp, approach, rand, lerp, rectsOverlap } from "./util.js";
import { Bolt } from "./enemies.js";

export class Boss {
  constructor(x, y, game) {
    this.x = x;
    this.y = y;
    this.w = 96;
    this.h = 158;
    this.vx = 0;
    this.vy = 0;
    this.facing = -1;
    this.maxHealth = 880;
    this.health = this.maxHealth;
    this.phase = 1;
    this.state = "intro";
    this.stateTimer = 1.7;
    this.cooldown = 1.4;
    this.time = 0;
    this.hitFlash = 0;
    this.invuln = true;
    this.dead = false;
    this.deathTimer = 0;
    this.airOffset = 0;
    this.slashes = [];
    this.waves = [];
    this.afterimages = [];
    this.attackStep = 0;
    this.attackHit = false;
    this.telegraphTimer = 0;
    this.laserY = 0;
    this.laserActive = 0;
    this.laserCharge = 0;
    this.groundY = y + this.h;
    this.arena = game.world.arena;
    this.score = 5000;
    this.roared = false;
    this.defeatReported = false;
    this.slow = 1;
  }

  get cx() { return this.x + this.w / 2; }
  get cy() { return this.y + this.h / 2; }
  get bottom() { return this.y + this.h; }

  hurt(damage, dirX, dirY, game, info = {}) {
    if (this.dead || this.state === "dying" || this.state === "phase") return false;
    if (this.state === "intro") return false;
    this.health -= damage;
    this.hitFlash = 1;
    game?.particles?.hit(this.cx + this.facing * 10, this.cy, info.heavy ? "#fff3b0" : "#ffd0d8", info.heavy);
    game?.particles?.text(this.cx + rand(-20, 20), this.y + 20, `${Math.round(damage)}`, info.heavy ? "#fff3b0" : "#ffd0d8", info.heavy ? 19 : 14);
    game?.audio?.play("bossHit");
    game?.addShake?.(info.heavy ? 7 : 3.5);
    game?.hitstop?.(info.heavy ? 0.05 : 0.025);
    if (this.health <= 0) {
      this.health = 0;
      this.die(game);
      return true;
    }
    const nextPhase = this.health <= this.maxHealth * 0.33 ? 3 : this.health <= this.maxHealth * 0.66 ? 2 : 1;
    if (nextPhase > this.phase) {
      this.phase = nextPhase;
      this.enterPhase(game);
    }
    return false;
  }

  enterPhase(game) {
    this.state = "phase";
    this.stateTimer = 1.45;
    this.invuln = true;
    this.vx = 0;
    this.laserCharge = 0;
    this.laserActive = 0;
    game?.audio?.play("bossRoar");
    game?.addShake?.(14);
    game?.hitstop?.(0.1);
    game?.particles?.explosion(this.cx, this.cy, "#ff3e62", 1.6);
    game?.particles?.ring(this.cx, this.cy, "#ffc36b", 220, 0.8, 6);
    game?.onBossPhase?.(this.phase);
  }

  die(game) {
    this.dead = true;
    this.state = "dying";
    this.deathTimer = 0;
    this.invuln = true;
    this.vx = 0;
    game?.audio?.play("bossDie");
    game?.addShake?.(18);
    game?.hitstop?.(0.14);
    game?.slowmo?.(0.35, 1.4);
    game?.onBossDefeated?.(this);
  }

  begin(state, timer) {
    this.state = state;
    this.stateTimer = timer;
    this.attackHit = false;
  }

  update(dt, player, world, game, projectiles) {
    this.time += dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
    if (this.state === "dying") {
      this.deathTimer += dt;
      this.stateTimer -= dt;
      if (Math.random() < dt * 12) {
        const ex = this.cx + rand(-70, 70), ey = this.y + rand(0, this.h);
        game?.particles?.explosion(ex, ey, Math.random() > 0.5 ? "#ffc36b" : "#ff5a3e", rand(0.5, 1.1));
        game?.audio?.play("enemyDie");
      }
      this.y += dt * 8;
      if (this.stateTimer <= 0 && !this.defeatReported) {
        this.defeatReported = true;
        game?.onVictory?.();
      }
      return;
    }
    if (this.state === "intro") {
      this.stateTimer -= dt;
      this.facing = player.cx < this.cx ? -1 : 1;
      if (this.stateTimer <= 0) {
        this.invuln = false;
        this.state = "idle";
        this.stateTimer = 0.7;
      }
      return;
    }
    if (this.state === "phase") {
      this.stateTimer -= dt;
      this.airOffset = -Math.sin(clamp((1.45 - this.stateTimer) / 1.45, 0, 1) * Math.PI) * 24;
      if (Math.random() < dt * 14) {
        game?.particles?.add({
          x: this.cx + rand(-60, 60), y: this.y + rand(0, this.h),
          vx: rand(-80, 80), vy: rand(-220, -60), life: rand(0.4, 0.9),
          size: rand(2, 5), color: this.phase === 2 ? "#ffc36b" : "#ff3e62", glow: 10, drag: 0.96,
        });
      }
      if (this.stateTimer <= 0) {
        this.invuln = false;
        this.airOffset = 0;
        this.state = "idle";
        this.stateTimer = 0.4;
        this.cooldown = 0.4;
      }
      return;
    }
    if (this.state === "stagger") {
      this.stateTimer -= dt;
      this.vx = approach(this.vx, 0, 900 * dt);
      this.move(dt, world);
      if (this.stateTimer <= 0) {
        this.state = "idle";
        this.stateTimer = 0.3;
      }
      return;
    }

    this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
    this.cooldown -= dt;
    this.stateTimer -= dt;
    this.facing = player.cx < this.cx ? -1 : 1;
    const speedMult = this.phase === 1 ? 1 : this.phase === 2 ? 1.2 : 1.45;

    // contact body damage
    if (rectsOverlap(this, player)) {
      player.takeDamage(9, this.cx, game, { knockback: 300, shake: 6 });
    }

    switch (this.state) {
      case "idle": {
        this.vx = approach(this.vx, 0, 800 * dt);
        const dx = player.cx - this.cx;
        if (Math.abs(dx) > 300) this.vx = approach(this.vx, Math.sign(dx) * 55 * speedMult, 300 * dt);
        if (this.stateTimer <= 0 && this.cooldown <= 0) this.chooseAttack(player, game);
        break;
      }
      case "walk": {
        const dx = player.cx - this.cx;
        this.vx = approach(this.vx, Math.sign(dx) * 95 * speedMult, 500 * dt);
        if (this.stateTimer <= 0) { this.state = "idle"; this.stateTimer = 0.25; }
        break;
      }
      case "slash": {
        this.vx = approach(this.vx, 0, 900 * dt);
        const total = 1.0;
        const p = 1 - this.stateTimer / total;
        if (p < 0.38) {
          this.telegraphTimer = 1 - p / 0.38;
        } else if (p < 0.55) {
          this.telegraphTimer = 0;
          if (!this.attackHit) {
            const hb = { x: this.facing > 0 ? this.x + 40 : this.x - 90, y: this.y + 10, w: 160, h: 120 };
            if (rectsOverlap(hb, player)) player.takeDamage(this.phase === 3 ? 20 : 16, this.cx, game, { knockback: 340, shake: 7 });
            this.attackHit = true;
            this.addSlash(game, this.facing, 1, 0);
            game?.audio?.play("slash3");
            game?.addShake?.(6);
          }
          this.vx = this.facing * 130;
        } else if (p < 0.72) {
          this.attackHit = false;
          if (!this.attackHit) {
            const hb = { x: this.facing > 0 ? this.x + 40 : this.x - 90, y: this.y + 10, w: 160, h: 120 };
            if (rectsOverlap(hb, player)) player.takeDamage(this.phase === 3 ? 24 : 19, this.cx, game, { knockback: 360, shake: 8 });
            this.attackHit = true;
            this.addSlash(game, this.facing, -1, 1);
            game?.audio?.play("slash3");
            game?.addShake?.(7);
          }
        } else {
          this.attackHit = false;
        }
        if (this.stateTimer <= 0) {
          this.state = "recover";
          this.stateTimer = this.phase === 3 ? 0.32 : 0.55;
        }
        break;
      }
      case "dashSlash": {
        const p = 1 - this.stateTimer / 0.62;
        if (p < 0.5) {
          this.vx = 0;
          this.telegraphTimer = p / 0.5;
        } else {
          this.telegraphTimer = 0;
          this.vx = this.facing * 980 * speedMult;
          if (Math.random() < 0.75) this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: 0.2, max: 0.2 });
          if (!this.attackHit && rectsOverlap(this, player)) {
            player.takeDamage(this.phase === 3 ? 24 : 18, this.cx, game, { knockback: 390, shake: 8 });
            this.attackHit = true;
          }
          if (p > 0.78) this.addSlash(game, this.facing, 2, 0);
        }
        if (this.stateTimer <= 0) {
          this.vx = 0;
          this.state = "recover";
          this.stateTimer = this.phase === 3 ? 0.3 : 0.5;
        }
        break;
      }
      case "volley": {
        this.vx = 0;
        const total = this.phase === 3 ? 1.15 : 1.3;
        const p = 1 - this.stateTimer / total;
        if (p < 0.3) {
          this.telegraphTimer = 1 - p / 0.3;
        } else {
          this.telegraphTimer = 0;
          const shots = this.phase === 3 ? 3 : 1;
          const interval = 0.2;
          const key = Math.floor((p - 0.3) / interval);
          if (key !== this.attackStep && key < (this.phase === 3 ? 3 : 2)) {
            this.attackStep = key;
            const base = Math.atan2(player.cy - (this.y + 40), player.cx - this.cx);
            for (let i = 0; i < shots; i++) {
              const spread = (i - (shots - 1) / 2) * 0.2;
              const speed = 350;
              projectiles.push(new Bolt(this.cx + this.facing * 30, this.y + 46, Math.cos(base + spread) * speed, Math.sin(base + spread) * speed, {
                color: "#ff3e62", trailColor: "#ff9aae", damage: 11, r: 6, life: 4, type: "blade",
              }));
            }
            game?.audio?.play("laser");
            game?.addShake?.(2);
            this.attackStep++;
          }
        }
        if (this.stateTimer <= 0) {
          this.state = "recover";
          this.stateTimer = 0.4;
          this.attackStep = 0;
        }
        break;
      }
      case "shockwave": {
        this.vx = 0;
        const p = 1 - this.stateTimer / 1.25;
        if (p < 0.55) {
          this.telegraphTimer = p / 0.55;
        } else if (!this.attackHit && p > 0.62) {
          this.attackHit = true;
          this.spawnWaves(game);
          game?.audio?.play("shockwave");
          game?.addShake?.(12);
          game?.particles?.dust(this.cx, 640, "#ff8a5c", 20, 200);
          game?.particles?.ring(this.cx, 620, "#ffc36b", 100, 0.4, 4);
        }
        if (this.stateTimer <= 0) {
          this.state = "recover";
          this.stateTimer = 0.45;
        }
        break;
      }
      case "storm": {
        this.vx = 0;
        const total = 1.8;
        const p = 1 - this.stateTimer / total;
        this.telegraphTimer = p < 0.55 ? p / 0.55 : 0;
        if (p < 0.55) {
          this.airOffset = -Math.sin(p / 0.55 * Math.PI * 0.5) * 150;
        } else if (p > 0.62) {
          this.airOffset = 0;
          if (!this.attackHit) {
            this.attackHit = true;
            this.spawnWaves(game);
            const base = rand(0, TAU);
            for (let i = 0; i < 12; i++) {
              const a = base + i / 12 * TAU;
              projectiles.push(new Bolt(this.cx, this.y + 55, Math.cos(a) * 270, Math.sin(a) * 270, {
                color: "#ffc36b", trailColor: "#ff5a3e", damage: 10, r: 5, life: 3, type: "blade",
              }));
            }
            game?.audio?.play("bossRoar");
            game?.audio?.play("shockwave");
            game?.addShake?.(15);
            game?.particles?.explosion(this.cx, 620, "#ff5a3e", 1.4);
          }
        }
        if (this.stateTimer <= 0) {
          this.state = "recover";
          this.stateTimer = 0.55;
        }
        break;
      }
      case "laser": {
        this.vx = 0;
        const total = 1.5;
        const p = 1 - this.stateTimer / total;
        if (p < 0.18) {
          this.telegraphTimer = p / 0.18;
          this.laserY = player.cy;
        } else if (p < 0.62) {
          this.telegraphTimer = 0.3;
          this.laserCharge = (p - 0.18) / 0.44;
          this.laserY = lerp(this.laserY, player.cy, dt * 3);
        } else if (p < 0.82) {
          this.laserCharge = 0;
          this.laserActive = 1;
          const beam = { x: this.arena.x0, y: this.laserY - 14, w: this.arena.x1 - this.arena.x0, h: 28 };
          if (rectsOverlap(beam, player)) {
            player.takeDamage(22, this.cx, game, { knockback: 320, shake: 8 });
          }
          if (!this.laserSound) { game?.audio?.play("laser"); this.laserSound = true; }
        } else {
          this.laserActive = 0;
        }
        if (this.stateTimer <= 0) {
          this.laserActive = 0;
          this.laserCharge = 0;
          this.laserSound = false;
          this.state = "recover";
          this.stateTimer = 0.45;
        }
        break;
      }
      case "recover": {
        this.vx = approach(this.vx, 0, 900 * dt);
        if (this.stateTimer <= 0) {
          this.state = "idle";
          this.stateTimer = 0.25;
          this.cooldown = this.phase === 1 ? 0.7 : this.phase === 2 ? 0.45 : 0.24;
        }
        break;
      }
      default:
        this.state = "idle";
        this.stateTimer = 0.3;
    }

    if (this.state !== "idle" && this.telegraphTimer < 0.3) {
      this.airOffset = lerp(this.airOffset, 0, dt * 8);
    }
    this.move(dt, world);
    this.updateWaves(dt, player, game);
    for (let i = this.afterimages.length - 1; i >= 0; i--) {
      const a = this.afterimages[i];
      a.life -= dt;
      if (a.life <= 0) this.afterimages.splice(i, 1);
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.age += dt;
      if (s.age >= s.max) this.slashes.splice(i, 1);
    }
  }

  chooseAttack(player, game) {
    const dist = Math.abs(player.cx - this.cx);
    const options = [];
    if (dist < 230) options.push("slash", "shockwave");
    if (dist >= 160) options.push("dashSlash");
    options.push("volley");
    if (this.phase >= 2) options.push("laser");
    if (this.phase >= 3) options.push("storm");
    if (this.phase === 1 && Math.random() < 0.3) options.push("walk");
    let choice = options[Math.floor(Math.random() * options.length)];
    if (choice === "slash") this.begin("slash", 1.0);
    else if (choice === "dashSlash") this.begin("dashSlash", 0.62);
    else if (choice === "volley") { this.begin("volley", this.phase === 3 ? 1.15 : 1.3); this.attackStep = 0; }
    else if (choice === "shockwave") this.begin("shockwave", 1.25);
    else if (choice === "laser") { this.begin("laser", 1.5); this.laserSound = false; this.laserY = player.cy; }
    else if (choice === "storm") this.begin("storm", 1.8);
    else this.begin("walk", 0.7);
    this.telegraphTimer = 0;
  }

  spawnWaves(game) {
    for (const dir of [-1, 1]) {
      this.waves.push({ x: this.cx + dir * 40, y: 620, dir, speed: 430 * (dir > 0 ? 1 : 0.92), life: 2.4, hit: false, phase: Math.random() * 4 });
    }
    game?.particles?.ring(this.cx, 620, "#ffc36b", 140, 0.5, 5);
  }

  updateWaves(dt, player, game) {
    for (let i = this.waves.length - 1; i >= 0; i--) {
      const w = this.waves[i];
      w.x += w.dir * w.speed * dt;
      w.life -= dt;
      const rect = { x: w.x - 22, y: w.y - 30, w: 44, h: 34 };
      if (!w.hit && rectsOverlap(rect, player)) {
        w.hit = true;
        player.takeDamage(15, w.x, game, { knockback: 260, shake: 6 });
      }
      if (w.life <= 0 || w.x < this.arena.x0 - 60 || w.x > this.arena.x1 + 60) this.waves.splice(i, 1);
    }
  }

  addSlash(game, dir, kind, variant) {
    this.slashes.push({ age: 0, max: 0.28, dir, kind, variant });
  }

  move(dt, world) {
    this.x += this.vx * dt;
    if (this.x < this.arena.x0 + 50) { this.x = this.arena.x0 + 50; this.vx = Math.max(0, this.vx); }
    if (this.x + this.w > this.arena.x1 - 20) { this.x = this.arena.x1 - 20 - this.w; this.vx = Math.min(0, this.vx); }
    this.y = this.groundY - this.h + this.airOffset;
  }

  // ------------------------------------------------------------- DRAW
  draw(ctx, game, time) {
    // waves under boss
    for (const w of this.waves) this.drawWave(ctx, w, time);
    // afterimages
    for (const a of this.afterimages) {
      ctx.save();
      ctx.globalAlpha = (a.life / a.max) * 0.22;
      ctx.globalCompositeOperation = "lighter";
      ctx.fillStyle = "#ff3e62";
      ctx.shadowColor = "#ff3e62";
      ctx.shadowBlur = 20;
      ctx.fillRect(a.x + 10, a.y + 20, this.w - 20, this.h - 30);
      ctx.restore();
    }
    // slash effects
    for (const s of this.slashes) this.drawSlash(ctx, s);

    ctx.save();
    const shakeX = this.telegraphTimer > 0.01 ? Math.sin(time * 70) * this.telegraphTimer * 3 : 0;
    ctx.translate(this.cx + shakeX, this.y + this.h);
    ctx.scale(this.facing, 1);
    if (this.state === "dying") {
      ctx.globalAlpha = Math.max(0, 1 - this.deathTimer / 2.8);
      ctx.rotate(Math.min(0.4, this.deathTimer * 0.12));
    }
    const bob = Math.sin(time * 1.7) * 2;
    const walk = Math.abs(this.vx) > 20 ? Math.sin(time * 7) * 6 : 0;
    const phaseColor = this.phase === 3 ? "#ffc36b" : this.phase === 2 ? "#ff7a3e" : "#ff3e62";
    const heat = this.phase === 3 ? 1 : 0;

    // aura
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const aura = ctx.createRadialGradient(0, -80, 10, 0, -80, 130);
    aura.addColorStop(0, `rgba(255,62,98,${0.1 + heat * 0.05})`);
    aura.addColorStop(0.5, `rgba(255,62,98,${0.045 + heat * 0.03})`);
    aura.addColorStop(1, "rgba(255,62,98,0)");
    ctx.fillStyle = aura;
    ctx.beginPath(); ctx.arc(0, -80, 130, 0, TAU); ctx.fill();
    ctx.restore();

    // cape ribbons
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-11, -125);
      const sway = Math.sin(time * 2.4 + i) * 12;
      ctx.quadraticCurveTo(-52 - i * 10, -100 + i * 14 + sway, -80 - i * 18, -52 + i * 22 + sway * 1.5);
      ctx.strokeStyle = i === 0 ? "rgba(255,63,206,0.55)" : "rgba(255,63,206,0.22)";
      ctx.lineWidth = 7 - i * 1.8;
      ctx.lineCap = "round";
      ctx.shadowColor = "#ff3fce";
      ctx.shadowBlur = 12;
      ctx.stroke();
    }
    ctx.restore();

    // legs
    ctx.strokeStyle = "#1a1a2b";
    ctx.lineWidth = 15;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-22, -75); ctx.lineTo(-30 + walk, -42); ctx.lineTo(-40 + walk, -6);
    ctx.moveTo(21, -75); ctx.lineTo(30 - walk, -42); ctx.lineTo(42 - walk, -6);
    ctx.stroke();
    ctx.strokeStyle = "#2c2b44";
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.moveTo(-23, -68); ctx.lineTo(-30 + walk, -43);
    ctx.moveTo(22, -68); ctx.lineTo(30 - walk, -43);
    ctx.stroke();
    // feet
    ctx.fillStyle = "#171726";
    ctx.fillRect(-54 + walk, -10, 28, 10);
    ctx.fillRect(28 - walk, -10, 30, 10);
    ctx.fillStyle = phaseColor;
    ctx.globalAlpha = 0.55;
    ctx.fillRect(-52 + walk, -7, 9, 1.5);
    ctx.fillRect(30 - walk, -7, 9, 1.5);
    ctx.globalAlpha = 1;

    // tassets / skirt armor
    ctx.fillStyle = "#12121f";
    ctx.beginPath();
    ctx.moveTo(-31, -82); ctx.lineTo(31, -82); ctx.lineTo(24, -46); ctx.lineTo(-24, -46); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(255,62,98,0.28)";
    ctx.lineWidth = 1;
    ctx.stroke();
    for (let i = -2; i <= 2; i++) {
      ctx.fillStyle = i % 2 ? "#1d1c30" : "#181726";
      ctx.fillRect(i * 12 - 5, -80, 9, 30);
      ctx.fillStyle = phaseColor;
      ctx.globalAlpha = 0.35;
      ctx.fillRect(i * 12 - 5, -54, 9, 1);
      ctx.globalAlpha = 1;
    }

    // torso
    const torsoGrad = ctx.createLinearGradient(-45, -145, 50, -75);
    torsoGrad.addColorStop(0, "#2a2841");
    torsoGrad.addColorStop(0.4, "#171628");
    torsoGrad.addColorStop(1, "#0a0912");
    ctx.fillStyle = torsoGrad;
    ctx.beginPath();
    ctx.moveTo(-36, -138 + bob);
    ctx.lineTo(34, -138 + bob);
    ctx.lineTo(42, -102 + bob);
    ctx.lineTo(28, -72 + bob);
    ctx.lineTo(-26, -72 + bob);
    ctx.lineTo(-42, -100 + bob);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(255,62,98,0.22)";
    ctx.stroke();
    // chest ribs
    ctx.strokeStyle = "rgba(138,92,255,0.28)";
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-28, -124 + i * 13 + bob);
      ctx.quadraticCurveTo(0, -118 + i * 13 + bob, 28, -124 + i * 13 + bob);
      ctx.stroke();
    }
    // core
    const corePulse = 0.65 + Math.sin(time * 3.3) * 0.18 + heat * 0.2;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.shadowColor = phaseColor;
    ctx.shadowBlur = 26;
    const core = ctx.createRadialGradient(0, -108 + bob, 0, 0, -108 + bob, 20);
    core.addColorStop(0, "#fff");
    core.addColorStop(0.28, phaseColor);
    core.addColorStop(1, "rgba(255,62,98,0)");
    ctx.fillStyle = core;
    ctx.globalAlpha = corePulse;
    ctx.beginPath(); ctx.arc(0, -108 + bob, 20, 0, TAU); ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#fff";
    ctx.beginPath(); ctx.arc(0, -108 + bob, 3.4, 0, TAU); ctx.fill();
    ctx.restore();

    // shoulder pauldrons
    const shoulderRaise = (this.state === "shockwave" || this.state === "laser") ? -8 : 0;
    ctx.fillStyle = "#242339";
    ctx.strokeStyle = "rgba(255,62,98,0.4)";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(-40, -138 + bob); ctx.lineTo(-64, -128 + bob + shoulderRaise); ctx.lineTo(-58, -109 + bob + shoulderRaise); ctx.lineTo(-34, -118 + bob); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(40, -138 + bob); ctx.lineTo(64, -128 + bob + shoulderRaise); ctx.lineTo(58, -109 + bob + shoulderRaise); ctx.lineTo(34, -118 + bob); ctx.closePath();
    ctx.fill(); ctx.stroke();
    // spikes
    ctx.fillStyle = phaseColor;
    ctx.beginPath(); ctx.moveTo(-63, -128 + shoulderRaise + bob); ctx.lineTo(-78, -145 + shoulderRaise + bob); ctx.lineTo(-56, -136 + shoulderRaise + bob); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(63, -128 + shoulderRaise + bob); ctx.lineTo(81, -147 + shoulderRaise + bob); ctx.lineTo(56, -136 + shoulderRaise + bob); ctx.closePath(); ctx.fill();

    // head + horned helmet
    ctx.save();
    ctx.translate(0, -158 + bob);
    ctx.fillStyle = "#191827";
    ctx.beginPath(); ctx.arc(0, 0, 19, 0, TAU); ctx.fill();
    // helmet crest
    ctx.fillStyle = "#29273f";
    ctx.beginPath();
    ctx.moveTo(-20, 0); ctx.lineTo(-10, -20); ctx.lineTo(0, -26); ctx.lineTo(12, -19); ctx.lineTo(20, 0); ctx.lineTo(8, -6); ctx.lineTo(-8, -6); ctx.closePath();
    ctx.fill();
    // horns
    ctx.fillStyle = phaseColor;
    ctx.beginPath(); ctx.moveTo(-17, -14); ctx.lineTo(-34, -38); ctx.lineTo(-12, -22); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(17, -14); ctx.lineTo(35, -40); ctx.lineTo(12, -22); ctx.closePath(); ctx.fill();
    // mask
    ctx.fillStyle = "#0a0912";
    ctx.fillRect(-13, -7, 26, 14);
    ctx.shadowColor = phaseColor;
    ctx.shadowBlur = 18;
    ctx.fillStyle = "#fff";
    ctx.fillRect(-10, -3, 8, 2.4);
    ctx.fillRect(3, -3, 8, 2.4);
    ctx.shadowBlur = 0;
    // mask vents
    ctx.strokeStyle = "rgba(255,62,98,0.5)";
    ctx.beginPath();
    for (let i = 0; i < 3; i++) { ctx.moveTo(-5 + i * 4, 5); ctx.lineTo(-5 + i * 4, 9); }
    ctx.stroke();
    ctx.restore();

    // arms + swords
    this.drawArms(ctx, bob, phaseColor, time);

    // hit flash
    if (this.hitFlash > 0.02) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = this.hitFlash * 0.55;
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.ellipse(0, -95, 55, 85, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

    // telegraph circle under boss
    if (this.telegraphTimer > 0.02 && this.state !== "phase") {
      ctx.save();
      ctx.translate(this.cx, 620);
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.25 + this.telegraphTimer * 0.4;
      ctx.strokeStyle = "#ff3e62";
      ctx.shadowColor = "#ff3e62";
      ctx.shadowBlur = 20;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(0, 0, 70 + this.telegraphTimer * 50, 18 + this.telegraphTimer * 10, 0, 0, TAU); ctx.stroke();
      ctx.restore();
    }

    // laser telegraph / beam
    if (this.state === "laser") {
      if (this.laserCharge > 0) {
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        ctx.globalAlpha = 0.2 + this.laserCharge * 0.6;
        ctx.strokeStyle = "#ffc36b";
        ctx.lineWidth = 1 + this.laserCharge * 3;
        ctx.shadowColor = "#ff3e62";
        ctx.shadowBlur = 18;
        ctx.beginPath();
        ctx.moveTo(this.cx, this.y + 46);
        const targetX = this.facing > 0 ? this.arena.x1 : this.arena.x0;
        ctx.lineTo(targetX, this.laserY);
        ctx.stroke();
        ctx.restore();
      }
      if (this.laserActive > 0) {
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        const y = this.laserY;
        const grad = ctx.createLinearGradient(0, y - 16, 0, y + 16);
        grad.addColorStop(0, "rgba(255,62,98,0)");
        grad.addColorStop(0.28, "rgba(255,62,98,0.6)");
        grad.addColorStop(0.5, "rgba(255,255,255,0.95)");
        grad.addColorStop(0.72, "rgba(255,62,98,0.6)");
        grad.addColorStop(1, "rgba(255,62,98,0)");
        ctx.fillStyle = grad;
        ctx.fillRect(this.arena.x0, y - 17, this.arena.x1 - this.arena.x0, 34);
        ctx.strokeStyle = "rgba(255,240,200,0.8)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(this.arena.x0, y); ctx.lineTo(this.arena.x1, y); ctx.stroke();
        ctx.restore();
      }
    }
  }

  drawArms(ctx, bob, phaseColor, time) {
    let angleL = 0.5, angleR = 0.6, lift = 0;
    if (this.state === "slash") {
      const p = 1 - this.stateTimer / 1.0;
      angleR = p < 0.38 ? lerp(0.6, -2.4, p / 0.38) : p < 0.72 ? lerp(-2.4, 1.1, (p - 0.38) / 0.34) : 1.1;
      angleL = -0.3;
    } else if (this.state === "dashSlash") {
      angleR = 0.15; angleL = 0.4;
    } else if (this.state === "volley") {
      angleR = -1.1; angleL = -0.9;
    } else if (this.state === "shockwave") {
      const p = 1 - this.stateTimer / 1.25;
      angleR = p < 0.55 ? lerp(0.6, -2.6, p / 0.55) : lerp(-2.6, 1.5, (p - 0.55) / 0.3);
      angleL = -2.0;
    } else if (this.state === "storm") {
      angleR = -1.9 - Math.sin(time * 20) * 0.3; angleL = -1.9 + Math.sin(time * 20) * 0.3;
    } else if (this.state === "laser") {
      angleR = -0.9; angleL = 0.9; lift = -8;
    } else if (this.state === "phase") {
      angleR = -2.2; angleL = 2.2;
    } else if (this.state === "recover") {
      angleR = 1.1; angleL = 0.5;
    }
    const armY = -126 + bob + lift;
    // left arm (back)
    this.drawArm(ctx, -32, armY, angleL, "#1a1930", phaseColor, false, time);
    // right arm (front)
    this.drawArm(ctx, 32, armY, angleR, "#242239", phaseColor, true, time);
  }

  drawArm(ctx, sx, sy, angle, color, glow, front, time) {
    ctx.save();
    ctx.translate(sx, sy);
    ctx.rotate(angle);
    // upper arm
    ctx.strokeStyle = color;
    ctx.lineWidth = 13;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(28, 8);
    ctx.stroke();
    // forearm
    ctx.strokeStyle = "#2f2c48";
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(28, 8); ctx.lineTo(54, 18);
    ctx.stroke();
    // hand
    ctx.fillStyle = "#0d0c16";
    ctx.beginPath(); ctx.arc(56, 19, 6, 0, TAU); ctx.fill();
    // blade
    const glowCol = this.phase === 3 ? "#ffc36b" : "#ff5a7a";
    ctx.globalCompositeOperation = "lighter";
    ctx.strokeStyle = glowCol;
    ctx.shadowColor = glowCol;
    ctx.shadowBlur = 18;
    ctx.lineWidth = 3.2;
    ctx.beginPath();
    ctx.moveTo(58, 16);
    ctx.lineTo(128, -6);
    ctx.stroke();
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(61, 15);
    ctx.lineTo(126, -6);
    ctx.stroke();
    // hilt
    ctx.globalCompositeOperation = "source-over";
    ctx.strokeStyle = "#0b0a12";
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(48, 20); ctx.lineTo(58, 16);
    ctx.stroke();
    ctx.restore();
  }

  drawWave(ctx, w, time) {
    const alpha = clamp(w.life / 0.5, 0, 1);
    ctx.save();
    ctx.translate(w.x, w.y);
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = alpha;
    ctx.scale(w.dir, 1);
    ctx.shadowColor = "#ffc36b";
    ctx.shadowBlur = 24;
    // ground fissure
    ctx.fillStyle = "rgba(255,195,107,0.65)";
    ctx.beginPath();
    ctx.moveTo(-26, 0);
    ctx.lineTo(-8, -34 - Math.sin(time * 18 + w.phase) * 6);
    ctx.lineTo(4, -20);
    ctx.lineTo(20, -48 - Math.sin(time * 20) * 8);
    ctx.lineTo(30, 0);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#fff4d6";
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(0, -24); ctx.lineTo(8, 0); ctx.closePath(); ctx.fill();
    ctx.fillStyle = "rgba(255,120,80,0.3)";
    ctx.fillRect(-30, -4, 60, 4);
    ctx.restore();
  }

  drawSlash(ctx, s) {
    const p = s.age / s.max;
    const alpha = Math.sin(Math.min(1, p * 1.5) * Math.PI);
    ctx.save();
    ctx.translate(this.cx, this.y + 40);
    ctx.scale(s.dir, 1);
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = alpha * 0.8;
    ctx.strokeStyle = s.variant ? "#ffc36b" : "#ff6a82";
    ctx.shadowColor = "#ff3e62";
    ctx.shadowBlur = 26;
    ctx.lineWidth = 10 - p * 5;
    const start = s.variant ? 0.7 : -2.2;
    const end = s.variant ? -1.3 : 1.1;
    ctx.beginPath();
    ctx.arc(0, 0, 150, start, end, false);
    ctx.stroke();
    ctx.globalAlpha = alpha * 0.5;
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 155, start, end, false);
    ctx.stroke();
    ctx.restore();
  }
}

import {
  Background, World, ZONES, VIEW_W, VIEW_H, GROUND_Y,
  drawPlatform, drawHazard, drawOrb, drawCheckpoint, drawArenaGate,
} from "./level.js";
import { Player } from "./player.js";
import { createEnemy } from "./enemies.js";
import { Boss } from "./boss.js";
import { Particles } from "./particles.js";
import { TAU, clamp, lerp, rand, rectsOverlap, formatScore } from "./util.js";

const ROMAN = ["I", "II", "III"];

export class Game {
  constructor(canvas, input, audio, ui) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d", { alpha: false });
    this.input = input;
    this.audio = audio;
    this.ui = ui;
    this.background = new Background();
    this.particles = new Particles();
    this.mode = "menu";
    this.clock = 0;
    this.menuTime = 0;
    this.camera = { x: 0, y: 0, shake: 0, shakeX: 0, shakeY: 0 };
    this.world = null;
    this.player = null;
    this.enemies = [];
    this.projectiles = [];
    this.looseOrbs = [];
    this.boss = null;
    this.bossDefeated = false;
    this.bossIntroTimer = 0;
    this.hitstop = 0;
    this.slowmo = 0;
    this.flash = 0;
    this.flashColor = "#ffffff";
    this.deathDelay = 0;
    this.score = 0;
    this.orbCount = 0;
    this.kills = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.maxCombo = 0;
    this.elapsed = 0;
    this.zone = ZONES[0];
    this.zonesSeen = new Set();
    this.hintsShown = new Set();
    this.checkpoint = null;
    this.spawnDefs = [];
    this.killed = new Set();
    this.menuParticles = [];
    for (let i = 0; i < 55; i++) {
      this.menuParticles.push({ x: rand(0, VIEW_W), y: rand(0, VIEW_H), s: rand(0.5, 2), v: rand(2, 14), p: rand(0, TAU) });
    }
    this.onVictoryScreen = null;
    this.onGameOverScreen = null;
    this.fgRain = [];
    for (let i = 0; i < 55; i++) {
      this.fgRain.push({ x: rand(0, VIEW_W), y: rand(0, VIEW_H), len: rand(12, 30), speed: rand(900, 1500), a: rand(0.05, 0.18) });
    }
    this.debugGod = false;
    this.resize();
    window.addEventListener("resize", () => this.resize());
  }

  resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = this.canvas.clientWidth || 1280;
    const h = this.canvas.clientHeight || 720;
    this.cssW = w;
    this.cssH = h;
    this.dpr = dpr;
    this.canvas.width = Math.max(1, Math.round(w * dpr));
    this.canvas.height = Math.max(1, Math.round(h * dpr));
    this.scale = Math.min(w / VIEW_W, h / VIEW_H);
    this.offsetX = (w - VIEW_W * this.scale) / 2;
    this.offsetY = (h - VIEW_H * this.scale) / 2;
  }

  // ------------------------------------------------------------- LIFECYCLE
  startNewRun() {
    this.world = new World();
    this.player = new Player(this.world.respawn.x, GROUND_Y - 62);
    this.enemies = [];
    this.spawnDefs = this.world.enemies.map((s, i) => ({ ...s, __id: `enemy-${i}` }));
    this.killed = new Set();
    for (const def of this.spawnDefs) {
      const enemy = createEnemy(def);
      enemy.id = def.__id;
      enemy.zone = def.zone;
      enemy.maxHealth *= [1, 1.12, 1.25, 1.35][def.zone] || 1;
      enemy.health = enemy.maxHealth;
      this.enemies.push(enemy);
    }
    this.projectiles = [];
    this.looseOrbs = [];
    this.boss = null;
    this.bossDefeated = false;
    this.bossIntroTimer = 0;
    this.hitstop = 0;
    this.slowmo = 0;
    this.flash = 0;
    this.deathDelay = 0;
    this.score = 0;
    this.orbCount = 0;
    this.kills = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.maxCombo = 0;
    this.elapsed = 0;
    this.zone = ZONES[0];
    this.zonesSeen = new Set([0]);
    this.hintsShown = new Set();
    this.checkpoint = null;
    this.world.checkpoints.forEach(cp => { cp.active = false; });
    this.camera.x = 0;
    this.camera.shake = 0;
    this.particles.clear();
    this.mode = "playing";
    this.audio.init();
    this.audio.resumeMusic();
    this.audio.setIntensity(0.12);
    this.ui?.showScreen("game");
    this.ui?.resetHUD();
    this.ui?.setTouchVisible(true);
    this.ui?.showSector(ZONES[0]);
    this.ui?.hint("A / D  ·  MOVE      SPACE  ·  JUMP", 6200);
    this.hintsShown.add("start");
    this.snapCamera();
    this.updateHUD(true);
  }

  enterMenu() {
    this.mode = "menu";
    this.menuTime = 0;
    this.ui?.showScreen("menu");
    this.ui?.hideBoss();
    this.ui?.setTouchVisible(false);
    this.audio.setIntensity(0.05);
    this.input.releaseAll();
    this.camera.x = 340;
  }

  pause() {
    if (this.mode !== "playing") return;
    this.mode = "paused";
    this.input.releaseAll();
    this.ui?.showScreen("pause");
    this.ui?.setTouchVisible(false);
    this.ui?.updatePause(this);
    this.audio.setIntensity(0.02);
  }

  resume() {
    if (this.mode !== "paused") return;
    this.mode = "playing";
    this.ui?.showScreen("game");
    this.ui?.setTouchVisible(true);
    this.audio.resumeMusic();
    this.audio.setIntensity(this.zone.id === 3 ? 0.9 : 0.2 + this.zone.id * 0.12);
  }

  retryCheckpoint() {
    if (!this.world || !this.player) return;
    const px = this.world.respawn.x;
    const py = this.world.respawn.y;
    this.player.respawn(px, py);
    this.player.health = this.player.maxHealth;
    this.deathDelay = 0;
    this.projectiles = [];
    this.looseOrbs = [];
    this.boss = null;
    this.bossDefeated = false;
    this.world.arena.active = false;
    this.world.gateOpen = false;
    this.hitstop = 0;
    this.slowmo = 0;
    this.mode = "playing";
    this.combo = 0;
    this.comboTimer = 0;
    this.ui?.hideBoss();
    // revive enemies belonging to the current sector
    const zoneId = this.zone.id;
    for (const def of this.spawnDefs) {
      if (def.zone !== zoneId) continue;
      this.killed.delete(def.__id);
      if (!this.enemies.some(e => e.id === def.__id)) {
        const e = createEnemy(def);
        e.id = def.__id;
        e.maxHealth *= [1, 1.12, 1.25, 1.35][def.zone] || 1;
        e.health = e.maxHealth;
        this.enemies.push(e);
      }
    }
    this.ui?.showScreen("game");
    this.ui?.setTouchVisible(true);
    this.ui?.resetHUD();
    this.ui?.showToast("CHECKPOINT LINK RESTORED", 1800);
    this.snapCamera();
    this.audio.resumeMusic();
    this.audio.play("checkpoint");
    this.updateHUD(true);
  }

  // --------------------------------------------------------------- UPDATE
  update(dt) {
    this.clock += dt;
    const bgCam = this.mode === "menu" ? this.camera.x : this.camera.x;
    this.background.update(dt, bgCam);
    this.background.camera = bgCam;
    for (const p of this.fgRain) {
      p.y += p.speed * dt;
      p.x -= p.speed * 0.14 * dt;
      if (p.y > VIEW_H + 30) { p.y = -30; p.x = rand(0, VIEW_W + 200); }
      if (p.x < -30) p.x += VIEW_W + 60;
    }

    if (this.mode === "menu") {
      this.menuTime += dt;
      this.camera.x = 520 + Math.sin(this.menuTime * 0.035) * 520;
      this.audio.update(dt);
      for (const p of this.menuParticles) {
        p.y -= p.v * dt;
        p.x += Math.sin(this.menuTime * 0.5 + p.p) * 5 * dt;
        if (p.y < -10) { p.y = VIEW_H + 10; p.x = rand(0, VIEW_W); }
      }
      return;
    }
    if (this.mode !== "playing") {
      this.particles.update(dt * 0.15);
      this.updateShake(dt);
      this.audio.update(dt);
      return;
    }

    // hitstop freezes gameplay for a few frames while effects catch up
    if (this.hitstop > 0) {
      this.hitstop = Math.max(0, this.hitstop - dt);
      this.particles.update(dt * 0.25);
      this.updateShake(dt);
      this.audio.update(dt);
      this.ui?.updateHUD(this);
      return;
    }
    const sdt = this.slowmo > 0 ? dt * 0.36 : dt;
    this.slowmo = Math.max(0, this.slowmo - dt);
    this.elapsed += sdt;

    const prevHealth = this.player.health;
    this.world.update(sdt);
    this.player.update(sdt, this.world, this.input, this);
    if (this.player.health < prevHealth - 0.01) this.onPlayerHurt();
    this.updateEnemies(sdt);
    this.updateBoss(sdt);
    this.updateProjectiles(sdt);
    this.handlePlayerAttack();
    this.updateLooseOrbs(sdt);
    this.handleCollectibles();
    this.handleCheckpoints();
    this.handleArena();
    this.handleZones();
    this.updateCombo(sdt);
    this.updateCamera(dt);
    this.particles.update(sdt);
    this.updateShake(dt);
    this.flash = Math.max(0, this.flash - dt * 3.6);
    this.bossIntroTimer = Math.max(0, this.bossIntroTimer - dt);
    this.updateHUD();
    this.updateHints();
    this.audio.update(dt);

    if (this.deathDelay > 0) {
      this.deathDelay -= dt;
      if (this.deathDelay <= 0) this.finishGameOver();
    }
  }

  updateEnemies(dt) {
    for (const e of this.enemies) {
      if (e.dead) { e.updateCommon(dt); continue; }
      if (Math.abs(e.cx - this.player.cx) > 1500) continue;
      e.update(dt, this.player, this.world, this, this.projectiles);
    }
    // prune corpses after fade
    if (this.enemies.length > 0 && this.enemies.some(e => e.dead && e.deathTimer > 1.2)) {
      this.enemies = this.enemies.filter(e => !(e.dead && e.deathTimer > 1.2));
    }
  }

  updateBoss(dt) {
    if (!this.boss) return;
    this.boss.update(dt, this.player, this.world, this, this.projectiles);
  }

  updateProjectiles(dt) {
    for (const b of this.projectiles) {
      b.update(dt, this.world, this);
      if (!b.dead && b.owner === "enemy") {
        const p = this.player;
        if (b.x + b.r > p.x && b.x - b.r < p.x + p.w && b.y + b.r > p.y && b.y - b.r < p.y + p.h) {
          if (p.takeDamage(b.damage, b.x, this, { knockback: 210, shake: 5 })) {
            b.dead = true;
            this.particles.spark(b.x, b.y, b.color, 10, 200);
          }
        }
      }
    }
    this.projectiles = this.projectiles.filter(b => !b.dead);
  }

  handlePlayerAttack() {
    const p = this.player;
    if (!p.alive) return;
    const info = p.getAttackInfo();
    if (!info) return;
    let connected = false;
    for (const e of this.enemies) {
      if (e.dead || p.hitSet.has(e.id)) continue;
      if (rectsOverlap(info, e)) {
        p.hitSet.add(e.id);
        e.hurt(info.damage, info.knockX, info.knockY, this, { heavy: info.heavy });
        p.registerHit(info.kind);
        connected = true;
      }
    }
    if (this.boss && !this.boss.dead && !p.hitSet.has("boss")) {
      if (rectsOverlap(info, this.boss)) {
        p.hitSet.add("boss");
        this.boss.hurt(info.damage, info.knockX, info.knockY, this, { heavy: info.heavy });
        p.registerHit(info.kind);
        connected = true;
      }
    }
    for (const b of this.projectiles) {
      if (b.dead || b.owner !== "enemy") continue;
      if (b.x > info.x - b.r && b.x < info.x + info.w + b.r && b.y > info.y - b.r && b.y < info.y + info.h + b.r) {
        b.dead = true;
        p.registerHit("parry");
        this.particles.spark(b.x, b.y, "#bffcff", 10, 210);
        this.particles.ring(b.x, b.y, "#5df7ff", 22, 0.2, 2);
        this.audio.play("parry");
        this.combo++;
        this.comboTimer = 2.2;
        this.addScore(12);
        connected = true;
      }
    }
    if (connected) {
      this.combo++;
      this.comboTimer = 2.2;
      this.maxCombo = Math.max(this.maxCombo, this.combo);
      this.addScore(6 + (info.heavy ? 6 : 0));
    }
  }

  onEnemyKilled(enemy) {
    if (this.killed.has(enemy.id)) return;
    this.killed.add(enemy.id);
    this.kills++;
    const mult = this.multiplier;
    this.addScore(Math.round(enemy.score * mult));
    this.spawnDrops(enemy);
    this.audio.setIntensity(clamp(0.15 + this.kills * 0.03, 0, 0.8));
    if (!this.hintsShown.has("kill")) {
      this.hintsShown.add("kill");
      this.ui?.hint("SHIFT / K  ·  DASH — INVULNERABLE MID-DASH", 5400);
    }
  }

  spawnDrops(enemy) {
    const count = enemy.orbDrop ?? 2;
    for (let i = 0; i < count; i++) {
      this.looseOrbs.push({
        x: enemy.cx, y: enemy.cy,
        vx: rand(-150, 150), vy: rand(-330, -160),
        r: 9, collected: false, phase: rand(0, TAU), age: 0,
        delay: 0.25 + i * 0.05,
      });
    }
  }

  updateLooseOrbs(dt) {
    for (const o of this.looseOrbs) {
      o.age += dt;
      o.vy += 950 * dt;
      o.x += o.vx * dt;
      o.y += o.vy * dt;
      if (o.y > 596) {
        o.y = 596;
        o.vy *= -0.32;
        if (Math.abs(o.vy) < 45) o.vy = 0;
        o.vx *= 0.8;
      }
    }
    this.looseOrbs = this.looseOrbs.filter(o => o.age < 20 || o.collected);
  }

  handleCollectibles() {
    const p = this.player;
    for (const orb of this.world.orbs) {
      if (orb.collected) continue;
      const dx = orb.x - p.cx, dy = orb.y - p.cy;
      if (dx * dx + dy * dy < 34 * 34) {
        orb.collected = true;
        this.collectOrb(orb, 45, 14);
      }
    }
    for (const orb of this.looseOrbs) {
      if (orb.collected || orb.age < orb.delay) continue;
      const dx = orb.x - p.cx, dy = orb.y - p.cy;
      if (dx * dx + dy * dy < 34 * 34) {
        orb.collected = true;
        this.collectOrb(orb, 25, 10);
      }
    }
    this.looseOrbs = this.looseOrbs.filter(o => !o.collected);
  }

  collectOrb(orb, base, energy) {
    this.orbCount++;
    this.player.addEnergy(energy);
    this.addScore(Math.round(base * this.multiplier));
    this.audio.play("orb");
    this.particles.ring(orb.x, orb.y, "#5df7ff", 26, 0.28, 2);
    for (let i = 0; i < 8; i++) this.particles.add({
      x: orb.x, y: orb.y, vx: rand(-90, 90), vy: rand(-140, 20),
      life: rand(0.25, 0.5), size: rand(1.5, 3.5), color: "#bffcff", glow: 8, drag: 0.9,
    });
    this.particles.text(orb.x, orb.y - 18, `+${Math.round(base * this.multiplier)}`, "#bffcff", 11);
  }

  handleCheckpoints() {
    const p = this.player;
    for (const cp of this.world.checkpoints) {
      if (cp.active) continue;
      if (Math.abs(p.cx - cp.x) < 58 && Math.abs(p.footY - cp.y) < 100) {
        this.world.activateCheckpoint(cp);
        this.checkpoint = cp;
        p.heal(38);
        p.energy = p.maxEnergy;
        p.invuln = Math.max(p.invuln, 0.8);
        this.audio.play("checkpoint");
        this.particles.ring(cp.x, cp.y - 40, "#5df7ff", 90, 0.7, 4);
        this.particles.spark(cp.x, cp.y - 40, "#bffcff", 22, 260);
        this.ui?.toast("CHECKPOINT LINKED  //  VITALS RESTORED", 2200);
        this.ui?.hint("CHECKPOINT SECURED — ENEMIES IN THIS SECTOR WILL RESET ON DEATH", 4200);
        this.addScore(100);
      }
    }
  }

  handleArena() {
    if (!this.world || this.world.arena.active) {
      if (this.world?.arena.active && this.player.x < this.world.arena.x0 + 40) {
        this.player.x = this.world.arena.x0 + 40;
        this.player.vx = Math.max(0, this.player.vx);
      }
      return;
    }
    if (this.player.cx > this.world.arena.trigger && !this.bossDefeated) {
      this.startBossFight();
    }
  }

  startBossFight() {
    const a = this.world.arena;
    a.active = true;
    this.world.gateOpen = false;
    this.boss = new Boss(11660, GROUND_Y - 158, this);
    this.bossIntroTimer = 2.4;
    this.projectiles = [];
    this.hitstop = 0.12;
    this.flash = 0.35;
    this.flashColor = "#ff3e62";
    this.addShake(10);
    this.audio.play("bossRoar");
    this.audio.setIntensity(1);
    this.ui?.showBoss(this.boss);
    this.ui?.toast("OVERLORD ZERO  //  SIGNAL UNSTABLE", 3000);
    this.ui?.hint("DASH THROUGH RED. STRIKE BOLTS TO PARRY.", 7000);
    this.particles.ring(this.boss.cx, 620, "#ff3e62", 260, 1.1, 6);
    this.particles.explosion(this.boss.cx, 560, "#ff3e62", 1.6);
  }

  onBossPhase(phase) {
    this.ui?.toast(`OVERLORD ZERO  //  PHASE ${ROMAN[phase - 1]}`, 2200);
    this.flash = 0.35;
    this.flashColor = phase === 3 ? "#ffc36b" : "#ff3e62";
    this.addShake(16);
  }

  onBossDefeated(boss) {
    this.bossDefeated = true;
    this.addScore(5000);
    this.ui?.toast("OVERLORD ZERO  //  TERMINATED", 3200);
    this.ui?.setBossPhase(3);
    this.audio.setIntensity(0.2);
    this.audio.play("victory");
    this.flash = 0.8;
    this.flashColor = "#ffffff";
    this.particles.explosion(boss.cx, boss.cy, "#ffc36b", 2.4);
  }

  onVictory() {
    if (this.mode !== "playing") return;
    this.mode = "victory";
    this.ui?.showVictory(this);
    this.ui?.setTouchVisible(false);
    this.ui?.hideBoss();
    this.audio.play("victory");
    this.audio.setIntensity(0.08);
    this.onVictoryScreen?.(this);
  }

  onPlayerDeath() {
    if (this.deathDelay > 0) return;
    this.deathDelay = 2.0;
    this.slowmo = 0.8;
    this.addShake(14);
    this.flash = 0.5;
    this.flashColor = "#ff3e62";
    this.ui?.hint("", 0);
    this.particles.explosion(this.player.cx, this.player.cy, "#ff3e62", 1.4);
    this.audio.setIntensity(0.03);
  }

  finishGameOver() {
    if (this.mode !== "playing") return;
    this.mode = "gameover";
    this.ui?.showGameOver(this);
    this.ui?.setTouchVisible(false);
    this.ui?.hideBoss();
    this.onGameOverScreen?.(this);
  }

  onPlayerHurt() {
    this.combo = 0;
    this.comboTimer = 0;
    this.player.comboTimer = 0;
  }

  playerFell() {
    if (!this.player.alive) return;
    const dmg = this.debugGod ? 0 : 22;
    if (dmg > 0) this.player.takeDamage(dmg, this.player.cx, this, { ignoreInvuln: true, knockback: 0, shake: 7, invuln: 1.5 });
    if (!this.player.alive) return;
    this.player.x = this.world.respawn.x;
    this.player.y = this.world.respawn.y;
    this.player.vx = 0;
    this.player.vy = 0;
    this.player.invuln = Math.max(this.player.invuln, 1.4);
    this.particles.ring(this.player.cx, this.player.cy, "#ff3e62", 70, 0.5, 4);
    this.particles.spark(this.player.cx, this.player.cy, "#ff5a7a", 16, 260);
    this.ui?.toast("VOID RECOVERY  //  SIGNAL RESTORED", 1600);
    this.snapCamera();
    this.addShake(8);
  }

  handleZones() {
    const z = this.world.getZone(this.player.cx);
    if (z.id !== this.zone.id) {
      this.zone = z;
      if (!this.zonesSeen.has(z.id)) {
        this.zonesSeen.add(z.id);
        this.ui?.showSector(z);
        this.audio.play("checkpoint");
        if (z.id === 1) this.ui?.hint("CHAIN KILLS TO RAISE THE SCORE MULTIPLIER", 5000);
        if (z.id === 2) this.ui?.hint("ELITE UNITS AHEAD — USE AIR STRIKES", 5000);
        this.audio.setIntensity(clamp(0.18 + z.id * 0.16, 0, 0.8));
      }
    }
    if (this.player.cx > 700 && !this.hintsShown.has("attack")) {
      this.hintsShown.add("attack");
      this.ui?.hint("J / CLICK  ·  STRIKE      SPACE ×2  ·  DOUBLE JUMP", 6400);
    }
    if (this.player.cx > 3280 && !this.hintsShown.has("dash")) {
      this.hintsShown.add("dash");
      this.ui?.hint("SHIFT / K  ·  DASH THROUGH DANGER", 5000);
    }
  }

  updateHints() {
    // reserved for contextual prompts triggered by position
  }

  updateCombo(dt) {
    if (this.combo > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) {
        this.combo = 0;
        this.comboTimer = 0;
      }
    }
  }

  get multiplier() {
    if (this.combo <= 1) return 1;
    return 1 + Math.min(2.5, (this.combo - 1) * 0.12);
  }

  addScore(v) {
    this.score += Math.max(0, Math.round(v));
  }

  addShake(v) {
    this.camera.shake = Math.min(24, this.camera.shake + v);
  }

  hitstopFor(seconds) {
    this.hitstop = Math.max(this.hitstop, seconds);
  }

  hitstop(seconds) { this.hitstopFor(seconds); }

  slowmo(scale, duration) {
    this.slowmo = Math.max(this.slowmo, duration);
  }

  flashDamage() {
    this.ui?.flashDamage();
    this.flash = Math.max(this.flash, 0.16);
    this.flashColor = "#ff3e62";
  }

  updateShake(dt) {
    this.camera.shake = Math.max(0, this.camera.shake - dt * 34);
    const s = this.camera.shake;
    this.camera.shakeX = s > 0.1 ? rand(-s, s) : 0;
    this.camera.shakeY = s > 0.1 ? rand(-s * 0.7, s * 0.7) : 0;
  }

  updateCamera(dt) {
    if (!this.player) return;
    let target = this.player.cx - VIEW_W * 0.43 + this.player.facing * 42;
    const max = this.world.width - VIEW_W;
    target = clamp(target, 0, max);
    this.camera.x = lerp(this.camera.x, target, 1 - Math.exp(-6.5 * dt));
    this.camera.y = 0;
  }

  snapCamera() {
    if (!this.player || !this.world) return;
    const target = clamp(this.player.cx - VIEW_W * 0.43 + this.player.facing * 42, 0, this.world.width - VIEW_W);
    this.camera.x = target;
    this.camera.shake = 0;
  }

  updateHUD(force = false) {
    this.ui?.updateHUD(this, force);
  }

  // --------------------------------------------------------------- RENDER
  draw() {
    const ctx = this.ctx;
    const dpr = this.dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = "#020106";
    ctx.fillRect(0, 0, this.cssW, this.cssH);
    ctx.save();
    ctx.translate(this.offsetX, this.offsetY);
    ctx.scale(this.scale, this.scale);
    ctx.beginPath();
    ctx.rect(0, 0, VIEW_W, VIEW_H);
    ctx.clip();

    if (this.mode === "menu") {
      this.drawMenu(ctx);
      ctx.restore();
      return;
    }

    const camX = this.camera.x + this.camera.shakeX;
    const camY = this.camera.y + this.camera.shakeY;
    this.background.draw(ctx, this.camera.x);
    ctx.save();
    ctx.translate(-camX, -camY);

    this.drawSceneryBack(ctx);
    this.drawWorld(ctx);
    this.drawEntities(ctx);
    this.particles.draw(ctx);
    this.drawSceneryFront(ctx);

    ctx.restore();

    // foreground rain
    ctx.save();
    ctx.lineCap = "round";
    for (const d of this.fgRain) {
      ctx.globalAlpha = d.a;
      ctx.strokeStyle = "#c6e8ff";
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(d.x, d.y);
      ctx.lineTo(d.x - d.len * 0.16, d.y + d.len);
      ctx.stroke();
    }
    ctx.restore();

    // bottom haze
    const haze = ctx.createLinearGradient(0, 560, 0, 720);
    haze.addColorStop(0, "rgba(4,3,12,0)");
    haze.addColorStop(1, "rgba(4,3,12,0.5)");
    ctx.fillStyle = haze;
    ctx.fillRect(0, 550, VIEW_W, 170);

    // speed lines during dash
    if (this.player && this.player.dashTime > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < 9; i++) {
        const y = 180 + i * 46 + rand(-10, 10);
        ctx.globalAlpha = rand(0.03, 0.11);
        ctx.strokeStyle = "#5df7ff";
        ctx.lineWidth = rand(0.6, 2);
        ctx.beginPath();
        ctx.moveTo(rand(0, 400), y);
        ctx.lineTo(rand(900, 1280), y);
        ctx.stroke();
      }
      ctx.restore();
    }

    if (this.flash > 0) {
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      ctx.globalAlpha = Math.min(0.75, this.flash * 0.5);
      ctx.fillStyle = this.flashColor;
      ctx.fillRect(0, 0, VIEW_W, VIEW_H);
      ctx.restore();
    }

    // cinematic letterbox during boss intro
    if (this.bossIntroTimer > 0) {
      const t = Math.min(1, (2.4 - this.bossIntroTimer) * 3);
      const h = 58 * Math.min(1, this.bossIntroTimer < 0.6 ? this.bossIntroTimer / 0.6 : t);
      ctx.fillStyle = "#020106";
      ctx.fillRect(0, 0, VIEW_W, h);
      ctx.fillRect(0, VIEW_H - h, VIEW_W, h);
      if (this.bossIntroTimer > 0.35) {
        ctx.save();
        ctx.textAlign = "center";
        ctx.font = '900 30px "DejaVu Sans", sans-serif';
        ctx.letterSpacing = "8px";
        ctx.fillStyle = "#fff";
        ctx.shadowColor = "#ff3e62";
        ctx.shadowBlur = 24;
        ctx.globalAlpha = clamp(this.bossIntroTimer / 2, 0, 1);
        ctx.fillText("OVERLORD  ZERO", VIEW_W / 2, 112);
        ctx.font = '400 10px "DejaVu Sans Mono", monospace';
        ctx.fillStyle = "#ff8aa6";
        ctx.fillText("SIGNAL ANOMALY // PHASE I", VIEW_W / 2, 136);
        ctx.restore();
      }
    }

    ctx.restore();
  }

  drawMenu(ctx) {
    this.background.draw(ctx, this.camera.x, true);
    // distant rain shimmer
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const p of this.menuParticles) {
      ctx.globalAlpha = 0.15 + Math.abs(Math.sin(this.menuTime + p.p)) * 0.25;
      ctx.fillStyle = p.x % 2 > 1 ? "#5df7ff" : "#ff3fce";
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.s, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
    // foreground rooftop
    ctx.save();
    const groundGrad = ctx.createLinearGradient(0, 610, 0, 720);
    groundGrad.addColorStop(0, "#0a0a17");
    groundGrad.addColorStop(1, "#030208");
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, 632, VIEW_W, 88);
    ctx.fillStyle = "#0d0d1c";
    ctx.beginPath();
    ctx.moveTo(0, 632);
    for (let x = 0; x <= VIEW_W; x += 160) {
      ctx.lineTo(x, 632 - Math.sin(x * 0.013 + 1) * 8);
    }
    ctx.lineTo(VIEW_W, 680);
    ctx.lineTo(0, 680);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(93,247,255,0.55)";
    ctx.shadowColor = "#5df7ff";
    ctx.shadowBlur = 14;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(0, 632);
    for (let x = 0; x <= VIEW_W; x += 160) ctx.lineTo(x, 632 - Math.sin(x * 0.013 + 1) * 8);
    ctx.stroke();
    // neon reflections
    ctx.globalCompositeOperation = "lighter";
    const refl = ctx.createLinearGradient(0, 638, 0, 720);
    refl.addColorStop(0, "rgba(255,63,206,0.10)");
    refl.addColorStop(1, "rgba(93,247,255,0)");
    ctx.fillStyle = refl;
    ctx.fillRect(0, 638, VIEW_W, 82);
    ctx.restore();

    // silhouette cables
    ctx.save();
    ctx.strokeStyle = "rgba(5,4,14,0.9)";
    ctx.lineWidth = 3;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.moveTo(0, 160 + i * 70);
      ctx.bezierCurveTo(300, 220 + i * 70, 980, 150 + i * 70, VIEW_W, 210 + i * 70);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawSceneryBack(ctx) {
    const cam = this.camera.x;
    const left = cam - 100, right = cam + VIEW_W + 100;
    // sagging cables with lanterns
    ctx.save();
    for (let base = 250; base < this.world.width; base += 760) {
      if (base > right + 760 || base < left - 760) continue;
      const p1 = 90 + (base % 3) * 20;
      ctx.strokeStyle = "rgba(10,8,22,0.8)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(base, p1);
      ctx.quadraticCurveTo(base + 380, p1 + 120, base + 760, p1 + 10);
      ctx.stroke();
      for (let k = 1; k < 5; k++) {
        const t = k / 5;
        const lx = base + t * 760;
        const ly = p1 + Math.sin(t * Math.PI) * 60;
        ctx.fillStyle = k % 2 ? "#ff3fce" : "#5df7ff";
        ctx.shadowColor = ctx.fillStyle;
        ctx.shadowBlur = 12;
        ctx.globalAlpha = 0.4 + 0.2 * Math.sin(this.clock * 2 + k);
        ctx.beginPath(); ctx.arc(lx, ly, 2.2, 0, TAU); ctx.fill();
        ctx.globalAlpha = 1;
        ctx.shadowBlur = 0;
        ctx.fillStyle = "rgba(8,7,18,0.8)";
        ctx.fillRect(lx - 1, ly - 22, 2, 22);
      }
    }
    ctx.restore();

    // floating holograms behind the route
    const holo = [
      { x: 1180, y: 245, text: "SHADOW", color: "#ff3fce", w: 90, h: 150 },
      { x: 3720, y: 230, text: "GHOST", color: "#5df7ff", w: 100, h: 130 },
      { x: 6480, y: 260, text: "RONIN", color: "#8a5cff", w: 92, h: 145 },
      { x: 9340, y: 205, text: "ZERO", color: "#ff3e62", w: 100, h: 120 },
    ];
    for (const s of holo) {
      if (s.x > right + 200 || s.x + s.w < left - 200) continue;
      const flicker = Math.sin(this.clock * 7 + s.x) > 0.94 ? 0.35 : 0.8;
      ctx.save();
      ctx.translate(s.x, s.y + Math.sin(this.clock * 1.4) * 5);
      ctx.globalAlpha = 0.16 * flicker;
      ctx.fillStyle = s.color;
      ctx.fillRect(0, 0, s.w, s.h);
      ctx.globalAlpha = 0.14;
      ctx.fillStyle = "#05040e";
      ctx.fillRect(4, 4, s.w - 8, s.h - 8);
      ctx.globalAlpha = 0.4 * flicker;
      ctx.strokeStyle = s.color;
      ctx.strokeRect(0, 0, s.w, s.h);
      ctx.globalAlpha = 0.6 * flicker;
      ctx.fillStyle = s.color;
      ctx.font = '700 20px "DejaVu Sans Mono", monospace';
      ctx.shadowColor = s.color;
      ctx.shadowBlur = 12;
      const chars = s.text.split("");
      for (let i = 0; i < chars.length; i++) {
        ctx.fillText(chars[i], 14 + (i % 2) * 16, 32 + i * 22);
      }
      ctx.restore();
    }
  }

  drawSceneryFront(ctx) {
    const cam = this.camera.x;
    const right = cam + VIEW_W + 100;
    // boss arena monolith
    if (right > this.world.arena.x0 - 200) {
      const x = 11620;
      ctx.save();
      ctx.globalAlpha = 0.5;
      ctx.fillStyle = "#07050e";
      ctx.fillRect(x - 120, 120, 240, 500);
      ctx.strokeStyle = "rgba(255,62,98,0.16)";
      ctx.strokeRect(x - 120, 120, 240, 500);
      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = `rgba(255,62,98,${0.04 + 0.02 * Math.sin(this.clock + i)})`;
        ctx.fillRect(x - 90 + i * 45, 180, 2, 380);
      }
      ctx.restore();
    }
    // torii gate at sector 3
    if (right > 7300 && cam < 8100) {
      const x = 7660;
      ctx.save();
      ctx.globalAlpha = 0.9;
      ctx.fillStyle = "#080610";
      ctx.fillRect(x - 150, 340, 22, 280);
      ctx.fillRect(x + 128, 340, 22, 280);
      ctx.fillRect(x - 180, 320, 360, 22);
      ctx.fillRect(x - 155, 355, 310, 12);
      ctx.strokeStyle = "rgba(138,92,255,0.35)";
      ctx.lineWidth = 1;
      ctx.strokeRect(x - 180, 320, 360, 22);
      ctx.globalCompositeOperation = "lighter";
      ctx.fillStyle = "rgba(138,92,255,0.32)";
      ctx.fillRect(x - 150, 342, 2, 278);
      ctx.fillRect(x + 148, 342, 2, 278);
      ctx.font = '700 26px "DejaVu Sans Mono", monospace';
      ctx.fillStyle = "rgba(255,63,206,0.5)";
      ctx.shadowColor = "#ff3fce";
      ctx.shadowBlur = 14;
      ctx.fillText("R O N I N", x - 76, 302);
      ctx.restore();
    }
  }

  drawWorld(ctx) {
    const cam = this.camera.x;
    const left = cam - 120, right = cam + VIEW_W + 120;
    // arena gate
    if (right > this.world.arena.x0 - 100) {
      drawArenaGate(ctx, this.world.arena.x0, this.world.time, this.world.arena.active);
    }
    for (const p of this.world.platforms) {
      if (p.x + p.w < left || p.x > right) continue;
      drawPlatform(ctx, p, this.world.time, this.world.paletteFor(this.player.cx));
    }
    for (const h of this.world.hazards) {
      if (h.x + h.w < left || h.x > right) continue;
      drawHazard(ctx, h, this.world.hazardActive(h), this.world.time);
    }
    for (const cp of this.world.checkpoints) {
      if (cp.x < left || cp.x > right) continue;
      drawCheckpoint(ctx, cp, this.world.time);
    }
    for (const orb of this.world.orbs) {
      if (orb.collected || orb.x < left || orb.x > right) continue;
      drawOrb(ctx, orb, this.world.time);
    }
    for (const orb of this.looseOrbs) {
      if (orb.collected || orb.x < left || orb.x > right) continue;
      drawOrb(ctx, orb, this.world.time + 2);
    }
  }

  drawEntities(ctx) {
    const cam = this.camera.x;
    const left = cam - 200, right = cam + VIEW_W + 200;
    for (const e of this.enemies) {
      if (e.dead && e.alpha <= 0) continue;
      if (e.cx < left || e.cx > right) continue;
      e.draw(ctx, this.world.time);
      if (this.debugGod) {
        // optional overlays for automated verification only
      }
    }
    if (this.boss) {
      this.boss.draw(ctx, this, this.world.time);
    }
    for (const b of this.projectiles) {
      if (b.x > left && b.x < right) b.draw(ctx, this.world.time);
    }
    if (this.player) this.player.draw(ctx, this, this.world.time);
  }

  // ------------------------------------------------------------- UI GLUE
  showScreen(name) { this.ui?.showScreen(name); }

  get stats() {
    return {
      score: this.score,
      orbs: this.orbCount,
      duration: this.elapsed,
      maxCombo: this.maxCombo,
      kills: this.kills,
      checkpoint: this.checkpoint,
      health: this.player?.health ?? 0,
      energy: this.player?.energy ?? 0,
      zone: this.zone,
      boss: this.boss ? { health: this.boss.health, max: this.boss.maxHealth, phase: this.boss.phase, state: this.boss.state } : null,
    };
  }

  screenPosition(worldX, worldY) {
    return {
      x: this.offsetX + (worldX - this.camera.x) * this.scale,
      y: this.offsetY + (worldY - this.camera.y) * this.scale,
    };
  }
}

