409:   update(dt, cameraX) {
410:     this.time += dt;
411:     this.camera = cameraX;
412:     for (const d of this.rain) {
413:       d.y += d.speed * dt;
414:       d.x -= d.speed * 0.16 * dt;
415:       if (d.y > VIEW_H + 24) { d.y = -20; d.x = Math.random() * VIEW_W + 220; }
416:       if (d.x < -40) d.x += VIEW_W + 80;
417:     }
418:     for (const c of this.cars) {
419:       c.x += c.speed * c.dir * dt;
420:       if (c.x > VIEW_W + 160) c.x = -120;
421:       if (c.x < -160) c.x = VIEW_W + 120;
422:     }
423:     for (const d of this.dust) {
424:       d.y -= d.speed * dt;
425:       d.x += Math.sin(this.time * 0.3 + d.y * 0.01) * d.drift * dt;
426:       if (d.y < -20) { d.y = VIEW_H + 10; d.x = Math.random() * VIEW_W; }
427:     }
428:     this.nextLightning -= dt;
429:     if (this.nextLightning <= 0) {
430:       this.nextLightning = 9 + Math.random() * 14;
431:       this.flash = 0.55 + Math.random() * 0.35;
432:     }
433:     this.flash = Math.max(0, this.flash - dt * 2.2);
434:   }
