436:   paletteFor(x) {
437:     const zi = Math.max(0, Math.min(ZONES.length - 1, ZONES.findIndex(z => x >= z.x0 && x < z.x1)));
438:     const i = zi === -1 ? ZONES.length - 1 : zi;
439:     const z = ZONES[i];
440:     const next = ZONES[Math.min(ZONES.length - 1, i + 1)];
441:     const blend = clamp((x - (z.x1 - 380)) / 380, 0, 1);
442:     const a = z.palette, b = next.palette;
443:     return {
444:       top: css(mixRgb(a.top, b.top, blend)),
445:       mid: css(mixRgb(a.mid, b.mid, blend)),
446:       glow: css(mixRgb(a.glow, b.glow, blend)),
447:       accent: css(mixRgb(a.accent, b.accent, blend)),
448:       haze: css(mixRgb(a.haze, b.haze, blend)),
449:       glowRaw: mixRgb(a.glow, b.glow, blend),
450:       accentRaw: mixRgb(a.accent, b.accent, blend),
451:     };
452:   }
