454:   draw(ctx, cameraX, menu = false) {
455:     const pal = this.paletteFor(menu ? 420 : cameraX);
456:     const W = VIEW_W, H = VIEW_H;
457:     // sky
458:     const sky = ctx.createLinearGradient(0, 0, 0, H);
459:     sky.addColorStop(0, pal.top);
460:     sky.addColorStop(0.48, pal.mid);
461:     sky.addColorStop(0.78, pal.haze);
462:     sky.addColorStop(1, "#05030d");
463:     ctx.fillStyle = sky;
464:     ctx.fillRect(0, 0, W, H);
465: 
466:     // horizon glow
467:     const hg = ctx.createRadialGradient(W * 0.56, H * 0.7, 20, W * 0.56, H * 0.7, W * 0.7);
468:     hg.addColorStop(0, `rgba(${pal.glowRaw.r},${pal.glowRaw.g},${pal.glowRaw.b},0.22)`);
469:     hg.addColorStop(0.4, `rgba(${pal.glowRaw.r},${pal.glowRaw.g},${pal.glowRaw.b},0.07)`);
470:     hg.addColorStop(1, "rgba(0,0,0,0)");
471:     ctx.fillStyle = hg;
472:     ctx.fillRect(0, 0, W, H);
473: 
474:     // stars
475:     ctx.save();
476:     const starOff = (cameraX * 0.015) % 2400;
477:     for (const s of this.stars) {
478:       let sx = s.x - starOff;
479:       if (sx < -10) sx += 2400;
480:       const tw = 0.45 + 0.55 * Math.abs(Math.sin(this.time * 0.8 + s.p));
481:       ctx.globalAlpha = tw * 0.8;
482:       ctx.fillStyle = "#d9fbff";
483:       ctx.fillRect(sx, s.y, s.s, s.s);
484:     }
485:     ctx.restore();
486: 
487:     // moon / ringed planet
488:     const moonX = 1010 - (cameraX * 0.012 % 600);
489:     const moonY = 136;
490:     ctx.save();
491:     const halo = ctx.createRadialGradient(moonX, moonY, 10, moonX, moonY, 190);
492:     halo.addColorStop(0, "rgba(255,150,220,0.22)");
493:     halo.addColorStop(0.35, "rgba(150,120,255,0.10)");
494:     halo.addColorStop(1, "rgba(0,0,0,0)");
495:     ctx.fillStyle = halo;
496:     ctx.beginPath(); ctx.arc(moonX, moonY, 190, 0, TAU); ctx.fill();
497:     ctx.translate(moonX, moonY);
498:     ctx.rotate(-0.22);
499:     ctx.strokeStyle = "rgba(191,154,255,0.25)";
500:     ctx.lineWidth = 2;
501:     ctx.beginPath(); ctx.ellipse(0, 0, 130, 28, 0, 0, TAU); ctx.stroke();
502:     ctx.strokeStyle = "rgba(255,114,210,0.18)";
503:     ctx.beginPath(); ctx.ellipse(0, 0, 150, 34, 0, 0, TAU); ctx.stroke();
504:     const body = ctx.createLinearGradient(-44, -44, 44, 44);
505:     body.addColorStop(0, "#f4d9ff");
506:     body.addColorStop(0.4, "#c48de0");
507:     body.addColorStop(0.7, "#6b4c99");
508:     body.addColorStop(1, "#26173f");
509:     ctx.fillStyle = body;
510:     ctx.beginPath(); ctx.arc(0, 0, 53, 0, TAU); ctx.fill();
511:     ctx.globalAlpha = 0.2;
512:     ctx.fillStyle = "#2b1748";
513:     for (let i = 0; i < 6; i++) {
514:       ctx.beginPath();
515:       ctx.arc(Math.sin(i * 2.1) * 26, Math.cos(i * 1.7) * 22, 5 + (i % 3) * 4, 0, TAU);
516:       ctx.fill();
517:     }
518:     ctx.restore();
519: 
520:     // parallax skyline layers
521:     for (const layer of this.layers) {
522:       const lw = layer.canvas.width;
523:       const offset = ((cameraX * layer.factor) % lw + lw) % lw;
524:       ctx.save();
525:       ctx.globalAlpha = layer.alpha ?? 1;
526:       for (let i = -1; i < Math.ceil(W / lw) + 1; i++) {
527:         ctx.drawImage(layer.canvas, Math.round(-offset + i * lw), layer.y);
528:       }
529:       if (layer.factor < 0.3) {
530:         ctx.globalCompositeOperation = "screen";
531:         ctx.globalAlpha = 0.06;
532:         ctx.fillStyle = pal.glow;
533:         ctx.fillRect(0, 0, W, H);
534:       }
535:       ctx.restore();
536:     }
537: 
538:     // holographic billboards
539:     for (const b of this.billboards) {
540:       let bx = b.x - ((cameraX * b.speed + this.time * 7) % 2900);
541:       if (bx < -300) bx += 2900;
542:       bx = ((bx + 300) % 2900) - 300;
543:       if (bx > W + 260) continue;
544:       this.drawBillboard(ctx, bx, b);
545:     }
546: 
547:     // flying cars
548:     for (const c of this.cars) {
549:       ctx.save();
550:       ctx.globalCompositeOperation = "lighter";
551:       const grad = ctx.createLinearGradient(c.x - c.dir * 90, c.y, c.x, c.y);
552:       grad.addColorStop(0, "rgba(0,0,0,0)");
553:       grad.addColorStop(1, c.hue === "#ff3fce" ? "rgba(255,63,206,0.32)" : "rgba(93,247,255,0.32)");
554:       ctx.fillStyle = grad;
555:       ctx.fillRect(c.x - (c.dir > 0 ? 90 : -10), c.y - 1, 90, 2);
556:       ctx.shadowBlur = 14;
557:       ctx.shadowColor = c.hue;
558:       ctx.fillStyle = c.hue;
559:       ctx.fillRect(c.x - c.size / 2, c.y - 2, c.size, 2.5);
560:       ctx.fillStyle = "#fff";
561:       ctx.fillRect(c.x + c.dir * (c.size / 2) - 1, c.y - 1.5, 2, 1.5);
562:       ctx.restore();
563:     }
564: 
565:     // lightning flash
566:     if (this.flash > 0) {
567:       ctx.save();
568:       ctx.globalCompositeOperation = "screen";
569:       ctx.globalAlpha = this.flash * 0.22;
570:       ctx.fillStyle = "#cfeaff";
571:       ctx.fillRect(0, 0, W, H);
572:       ctx.restore();
573:     }
574: 
575:     // low fog bands
576:     ctx.save();
577:     const fog = ctx.createLinearGradient(0, 500, 0, 720);
578:     fog.addColorStop(0, "rgba(20,12,40,0)");
579:     fog.addColorStop(0.6, "rgba(20,12,40,0.32)");
580:     fog.addColorStop(1, "rgba(8,5,18,0.6)");
581:     ctx.fillStyle = fog;
582:     ctx.fillRect(0, 470, W, 250);
583:     ctx.restore();
584: 
585:     // floating embers
586:     ctx.save();
587:     ctx.globalCompositeOperation = "lighter";
588:     for (const d of this.dust) {
589:       ctx.globalAlpha = d.alpha * (0.6 + 0.4 * Math.sin(this.time + d.y));
590:       ctx.fillStyle = d.color;
591:       ctx.beginPath(); ctx.arc(d.x, d.y, d.s, 0, TAU); ctx.fill();
592:     }
593:     ctx.restore();
594: 
595:     // rain
596:     ctx.save();
597:     ctx.lineCap = "round";
598:     for (const d of this.rain) {
599:       ctx.globalAlpha = d.alpha;
600:       ctx.strokeStyle = d.layer > 0.7 ? "#b9d9ff" : "#6f9bb8";
601:       ctx.lineWidth = d.layer > 0.7 ? 1.15 : 0.7;
602:       ctx.beginPath();
603:       ctx.moveTo(d.x, d.y);
604:       ctx.lineTo(d.x - d.len * 0.18, d.y + d.len);
605:       ctx.stroke();
606:     }
607:     ctx.restore();
608:   }
