610:   drawBillboard(ctx, x, b) {
611:     const glitch = Math.sin(this.time * 2.1 + b.x) > 0.96 ? 5 : 0;
612:     ctx.save();
613:     ctx.translate(x, b.y);
614:     ctx.globalAlpha = 0.82;
615:     // frame
616:     ctx.fillStyle = "rgba(5,4,15,0.55)";
617:     ctx.fillRect(-b.w / 2, -b.h / 2, b.w, b.h);
618:     ctx.strokeStyle = "rgba(93,247,255,0.16)";
619:     ctx.strokeRect(-b.w / 2, -b.h / 2, b.w, b.h);
620:     // scanlines
621:     ctx.globalAlpha = 0.09;
622:     ctx.fillStyle = b.color;
623:     for (let y = -b.h / 2 + 4; y < b.h / 2; y += 5) ctx.fillRect(-b.w / 2 + 4, y, b.w - 8, 1);
624:     ctx.globalAlpha = 0.85;
625:     ctx.shadowColor = b.color;
626:     ctx.shadowBlur = 15;
627:     ctx.fillStyle = b.color;
628:     if (b.vertical) {
629:       ctx.translate(-b.w / 2 + 28, -b.h / 2 + 22);
630:       ctx.font = '700 19px "DejaVu Sans Mono", monospace';
631:       const chars = b.text.split("");
632:       for (let i = 0; i < chars.length; i++) ctx.fillText(chars[i], (i % 2) * 14 + (i === 0 ? glitch : 0), i * 23);
633:     } else {
634:       ctx.textAlign = "center";
635:       ctx.font = '700 22px "DejaVu Sans Mono", monospace';
636:       ctx.fillText(b.text, glitch, 4);
637:       ctx.globalAlpha = 0.5;
638:       ctx.font = '400 8px "DejaVu Sans Mono", monospace';
639:       ctx.fillText("SIGNAL // ACTIVE", 0, 26);
640:     }
641:     ctx.restore();
642:   }
643: }
