288:     else if (this.comboTimer > 0) index = (this.attackIndex + 1) % 3;
289:     else index = 0;
290:     this.attackIndex = index;
291:     const air = !this.grounded;
292:     const dur = air ? 0.34 : [0.27, 0.29, 0.34][index];
293:     this.attack = {
294:       index, t: 0, dur, air,
295:       activeFrom: air ? 0.055 : [0.045, 0.05, 0.07][index],
296:       activeTo: air ? 0.21 : [0.14, 0.15, 0.2][index],
297:     };
298:     this.hitSet = new Set();
299:     this.comboTimer = 0.75;
300:     this.energyDelay = Math.max(this.energyDelay, 0.3);
301:     const type = air ? "air" : index === 2 ? "overhead" : index === 1 ? "reverse" : "slash";
302:     this.slashes.push({ age: 0, max: air ? 0.3 : 0.24, type, facing: this.facing, x: this.x + this.w / 2, y: this.y + 27, seed: Math.random() * 4 });
303:     game?.audio?.play(index === 1 ? "slash2" : index === 2 ? "slash3" : "slash", 1 + index * 0.1);
304:     game?.addShake?.(index === 2 ? 2.5 : 1.2);
