333:   resolveHorizontal(world) {
334:     for (const p of world.platforms) {
335:       if (p.oneWay) continue;
336:       if (!rectsOverlap(this, p)) continue;
337:       if (this.vx > 0) {
338:         this.x = p.x - this.w - 0.01;
339:         this.vx = 0;
340:       } else if (this.vx < 0) {
341:         this.x = p.x + p.w + 0.01;
342:         this.vx = 0;
343:       }
344:     }
345:   }
