347:   resolveVertical(world, prevBottom, prevTop, wasGrounded, game, input) {
348:     this.grounded = false;
349:     this.groundPlatform = null;
350:     for (const p of world.platforms) {
351:       if (!rectsOverlap(this, p)) continue;
352:       if (this.vy >= 0) {
353:         const tolerance = p.oneWay ? 12 : 20;
354:         if (prevBottom <= p.y + tolerance) {
355:           this.y = p.y - this.h;
356:           if (this.vy > 620) {
357:             game?.particles?.dust(this.cx, p.y, "#8fd2e2", 6, 70);
358:           }
359:           this.vy = 0;
360:           this.grounded = true;
361:           this.groundPlatform = p;
362:         }
363:       } else if (!p.oneWay) {
364:         if (prevTop >= p.y + p.h - 14) {
365:           this.y = p.y + p.h;
366:           this.vy = 60;
367:         }
368:       }
369:     }
370:   }
