457:   updateCosmetics(dt, game) {
458:     // run cycle
459:     if (this.grounded && Math.abs(this.vx) > 20) this.runPhase += dt * (5 + Math.abs(this.vx) * 0.028);
460:     else if (this.grounded) this.runPhase += dt * 1.6;
461:     // scarf follows head
462:     const targetX = this.x + this.w / 2 - this.facing * 12;
463:     const targetY = this.y + 15;
464:     const points = this.scarf;
465:     points[0].x = targetX;
466:     points[0].y = targetY;
467:     for (let i = 1; i < points.length; i++) {
468:       const p = points[i];
469:       const prev = points[i - 1];
470:       p.x += (prev.x - p.x) * Math.min(1, dt * 16);
471:       p.y += (prev.y - p.y) * Math.min(1, dt * 16);
472:       p.x -= this.vx * dt * 0.06;
473:       p.y += (18 + i * 1.5) * dt;
474:       p.y += Math.sin(this.time * 4 - i * 0.7) * 7 * dt;
475:     }
476:     // afterimages
477:     for (let i = this.afterimages.length - 1; i >= 0; i--) {
478:       const a = this.afterimages[i];
479:       a.life -= dt;
480:       if (a.life <= 0) this.afterimages.splice(i, 1);
481:     }
482:     for (let i = this.slashes.length - 1; i >= 0; i--) {
483:       const s = this.slashes[i];
484:       s.age += dt;
485:       if (s.age >= s.max) this.slashes.splice(i, 1);
486:     }
487:     // passive trail when very fast
488:     if (this.grounded && Math.abs(this.vx) > 300 && Math.random() < dt * 10) {
489:       game?.particles?.add({
490:         x: this.cx - this.facing * 12, y: this.footY - rand(4, 30),
491:         vx: -this.facing * rand(10, 60), vy: rand(-20, 8),
492:         life: rand(0.2, 0.4), size: rand(1, 2.5), color: "#5df7ff", glow: 5, drag: 0.94,
493:       });
494:     }
495:   }
