531:     const flicker = this.invuln > 0 && this.invuln < 0.9 && Math.floor(this.time * 24) % 2 === 0;
532:     if (flicker) return;
533: 
534:     ctx.save();
535:     ctx.translate(this.cx, this.footY);
536:     ctx.scale(this.facing, 1);
537: 
538:     const run = clamp(Math.abs(this.vx) / RUN_MAX, 0, 1);
539:     const phase = this.runPhase;
540:     const airborne = !this.grounded;
541:     const dashing = this.dashTime > 0;
