564:     this.limb(ctx, hipX, hipY, hipX + Math.sin(legB) * 7, -14, -2 + legB * 1.2, 6.2, "#0a1020");
565:     // boots
566:     ctx.fillStyle = "#2b3b55";
567:     ctx.fillRect(-4 + legacyFoot(legA), -5, 11, 5);
568:     ctx.fillStyle = "#1c2940";
