595: 
596:     // back arm
597:     const backArm = attacking ? -0.5 : Math.sin(phase) * 0.5 * run;
598:     this.limb(ctx, -4, -44 + bob, -10, -35 + bob, -8 + backArm * 5, -25 + bob, 4.3, "#0c1422");
