731:     } else if (this.attack) {
732:       t = clamp(this.attack.t / this.attack.dur, 0, 1);
733:       kind = this.attack.air ? "air" : this.attack.index === 2 ? "overhead" : "combo";
734:     } else {
735:       t = 0; kind = "combo";
736:     }
737:     let handX = 20, handY = -38, elbowX = 12, elbowY = -40;
738:     let swordAngle = -0.5;
739:     if (kind === "dash") {
740:       handX = 30; handY = -36; elbowX = 16; elbowY = -41;
741:       swordAngle = -0.06;
742:     } else if (kind === "air") {
743:       const a = t * TAU;
744:       handX = Math.cos(a) * 14 + 8;
745:       handY = Math.sin(a) * 12 - 36;
746:       elbowX = handX * 0.7;
747:       elbowY = handY * 0.85 - 4;
748:       swordAngle = a + 1.4;
749:     } else if (kind === "overhead") {
750:       swordAngle = -1.9 + t * 3.1;
751:       handX = 17 + t * 8; handY = -43 + t * 12;
752:       elbowX = 9; elbowY = -42;
753:     } else {
754:       const idx = this.attack?.index ?? 0;
755:       if (idx === 1) {
756:         swordAngle = 1.75 - t * 3.4;
757:         handX = 15 - t * 2; handY = -33;
758:       } else {
759:         swordAngle = -1.45 + t * 3.0;
760:         handX = 19 + t * 4; handY = -38 - t * 2;
761:       }
762:       elbowX = 11; elbowY = -40;
763:     }
764:     this.limb(ctx, 4, -44 + bob, elbowX, elbowY, handX, handY, 4.4, "#18263e");
