const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless:false, executablePath:'/usr/bin/chromium', args:['--no-sandbox','--window-size=1440,900'] });
  const page = await (await browser.newContext({viewport:{width:1440,height:900}})).newPage();
  const errors=[]; page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message, e.stack); });
  page.on('console', m => { if (m.type()==='error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });
  await page.goto('http://localhost:3000', {waitUntil:'load'});
  await page.waitForTimeout(900);
  await page.click('#btn-start');
  await page.waitForTimeout(700);
  const st = () => page.evaluate(() => window.__SHADOW__.state());

  // freeze player damage
  await page.evaluate(() => window.__SHADOW__.god(true));
  console.log('start', JSON.stringify(await st()));

  async function killType(type, shots=8) {
    const info = await page.evaluate((type) => {
      const g = window.__SHADOW__.game;
      const e = g.enemies.find(x => !x.dead && x.type === type);
      return e ? { x:e.x, y:e.y, w:e.w, h:e.h, hp:e.health, id:e.id } : null;
    }, type);
    if (!info) { console.log('NO ENEMY', type); return; }
    console.log('engaging', type, JSON.stringify(info));
    for (let i=0;i<shots;i++) {
      const alive = await page.evaluate(({type, id}) => {
        const g = window.__SHADOW__.game;
        const e = g.enemies.find(x => x.id === id);
        if (!e || e.dead) return false;
        const p = g.player;
        p.invuln = 999;
        if (type === 'drone') {
          p.x = e.cx - p.w/2 - 30; p.y = e.cy - p.h/2;
        } else {
          p.x = e.x - 58; p.y = 620 - p.h; p.vy = 0;
        }
        p.facing = 1; p.vx = 0;
        g.snapCamera();
        return true;
      }, {type, id});
      if (!alive) break;
      await page.keyboard.press('j');
      await page.waitForTimeout(320);
    }
    const after = await page.evaluate((id) => {
      const g = window.__SHADOW__.game;
      const e = g.enemies.find(x => x.id === id);
      return { dead: !e || e.dead, hp: e?.health, kills:g.kills, score:g.score, orbs:g.orbCount, loose:g.looseOrbs.length, combo:g.combo };
    }, info.id);
    console.log('killed?', type, JSON.stringify(after));
  }

  await killType('melee');
  await killType('gunner');
  await killType('drone');
  await page.waitForTimeout(500);
  // collect a loose orb if nearby
  const orbBefore = (await st()).orbs;
  await page.evaluate(() => {
    const g = window.__SHADOW__.game;
    const o = g.looseOrbs.find(o => !o.collected);
    if (o) { g.player.x = o.x - 17; g.player.y = o.y - 31; }
  });
  await page.waitForTimeout(700);
  console.log('orbs', orbBefore, '->', (await st()).orbs, 'score', (await st()).score);
  await page.screenshot({path:'/tmp/shadow-shots/combat2.png'});

  // checkpoint
  await page.evaluate(() => { const g=window.__SHADOW__.game; g.player.x=2800-10; g.player.y=620-62; g.player.vx=0; g.player.vy=0; g.snapCamera(); });
  await page.waitForTimeout(400);
  const cp = await page.evaluate(() => {
    const g = window.__SHADOW__.game;
    return { active:g.world.checkpoints.map(c=>c.active), respawn:g.world.respawn, checkpoint:g.checkpoint?.id };
  });
  console.log('checkpoint', JSON.stringify(cp));

  // pause / resume
  await page.keyboard.press('Escape');
  await page.waitForTimeout(350);
  console.log('pause', JSON.stringify(await st()));
  await page.screenshot({path:'/tmp/shadow-shots/pause.png'});
  await page.click('#btn-resume');
  await page.waitForTimeout(350);
  console.log('resume', JSON.stringify(await st()));

  // boss
  await page.evaluate(() => window.__SHADOW__.gotoBoss());
  await page.waitForTimeout(3000);
  console.log('boss start', JSON.stringify(await st()));
  await page.screenshot({path:'/tmp/shadow-shots/boss1.png'});
  // hit boss a few times to observe phase
  await page.evaluate(() => {
    const g=window.__SHADOW__.game, b=g.boss, p=g.player;
    p.x = b.x - 70; p.y = 620 - p.h; p.invuln=999; p.facing=1;
  });
  for (let i=0;i<5;i++){ await page.keyboard.press('j'); await page.waitForTimeout(300); }
  console.log('boss after hits', JSON.stringify(await st()));
  const phases = [];
  for (let k=0;k<3;k++){
    await page.evaluate(() => window.__SHADOW__.hurtBoss(120));
    await page.waitForTimeout(600);
    phases.push(await page.evaluate(() => { const b=window.__SHADOW__.game.boss; return b?{hp:b.health,max:b.maxHealth,phase:b.phase,state:b.state}:null; }));
  }
  console.log('phases', JSON.stringify(phases));
  await page.screenshot({path:'/tmp/shadow-shots/boss2.png'});
  await page.evaluate(() => window.__SHADOW__.killBoss());
  await page.waitForTimeout(3800);
  console.log('victory', JSON.stringify(await st()), 'screen', await page.evaluate(()=>window.__SHADOW__.ui.current));
  await page.screenshot({path:'/tmp/shadow-shots/victory.png'});
  console.log('errors', errors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

