  await page.evaluate(() => { const g=window.__SHADOW__.game; g.player.health=5; g.player.invuln=0; g.player.takeDamage(50, g.player.cx+20, g, {ignoreInvuln:true}); });
  for (let i=0;i<12;i++){
    await page.waitForTimeout(400);
