const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless:false, executablePath:'/usr/bin/chromium', args:['--no-sandbox','--window-size=1440,900'] });
  const page = await (await browser.newContext({viewport:{width:1440,height:900}})).newPage();
  const errors=[]; page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  await page.goto('http://localhost:3000'); await page.waitForTimeout(800); await page.click('#btn-start'); await page.waitForTimeout(700);
  const st = () => page.evaluate(() => window.__SHADOW__.state());
  await page.evaluate(() => { const g=window.__SHADOW__.game; g.player.x=2790; g.player.y=558; g.snapCamera(); });
  await page.waitForTimeout(500);
  console.log('cp', JSON.stringify(await page.evaluate(()=>({cp:window.__SHADOW__.game.checkpoint?.id, respawn:window.__SHADOW__.game.world.respawn, score:window.__SHADOW__.game.score}))));
  await page.evaluate(() => { const g=window.__SHADOW__.game; g.player.health=5; g.player.invuln=0; g.player.takeDamage(50, g.player.cx+20, g, {ignoreInvuln:true}); });
  await page.waitForFunction(() => window.__SHADOW__.game.mode === 'gameover', null, {timeout:20000});
  console.log('dead', JSON.stringify(await st()), 'screen', await page.evaluate(()=>window.__SHADOW__.ui.current));
  await page.screenshot({path:'/tmp/shadow-shots/gameover.png'});
  await page.click('#btn-retry');
  await page.waitForTimeout(900);
  console.log('retry', JSON.stringify(await st()));
  // fall
  await page.evaluate(() => { const g=window.__SHADOW__.game; g.player.x=1590; g.player.y=760; g.player.vy=300; g.player.invuln=0; g.player.health=10; g.snapCamera(); });
  await page.waitForFunction(() => window.__SHADOW__.game.mode === 'gameover', null, {timeout:20000});
  console.log('fall death', JSON.stringify(await st()));
  await page.click('#btn-retry'); await page.waitForTimeout(600);
  await page.keyboard.press('Escape'); await page.waitForTimeout(400);
  await page.evaluate(() => { window.__SHADOW__.game.score = 1234; });
  await page.click('#btn-restart'); await page.waitForTimeout(800);
  console.log('pause restart', JSON.stringify(await st()), 'score', await page.evaluate(()=>window.__SHADOW__.game.score));
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);
  await page.click('#btn-quit'); await page.waitForTimeout(500);
  console.log('menu', JSON.stringify(await st()), 'screen', await page.evaluate(()=>window.__SHADOW__.ui.current));
  await page.click('#btn-start'); await page.waitForTimeout(600);
  console.log('restart', JSON.stringify(await st()));
  console.log('errors', errors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

